def calculate_macros(protein, carbs, fat, fiber, sugar, sodium, servings):
    net_carbs = max(carbs - fiber, 0.0)
    return dict(protein=round(protein / servings, 2), carbs=round(net_carbs / servings, 2), fat=round(fat / servings, 2), fiber=round(fiber / servings, 2), sugar=round(sugar / servings, 2), sodium=round(sodium / servings, 1))


def calculate_vitamins(vitamin_a, vitamin_c, vitamin_d, iron, calcium, magnesium, potassium):
    return dict(A=round(vitamin_a / 900 * 100, 1), C=round(vitamin_c / 90 * 100, 1), D=round(vitamin_d / 20 * 100, 1), Fe=round(iron / 18 * 100, 1), Ca=round(calcium / 1300 * 100, 1), Mg=round(magnesium / 420 * 100, 1), K=round(potassium / 3400 * 100, 1))


def estimate_calories(protein, carbs, fat, alcohol, fiber, cooking_multiplier, thermic_effect):
    gross = protein * 4 + carbs * 4 + fat * 9 + alcohol * 7 - fiber * 2
    return round(gross * cooking_multiplier * (1 - thermic_effect), 1)


def generate_label(recipe_name, calories, macros, vitamins, daily_value_pct, serving_size, allergen_warning):
    top_vitamins = sorted(vitamins.items(), key=lambda kv: -kv[1])[:3]
    vitamin_text = ", ".join(f"{name} {pct}%DV" for name, pct in top_vitamins)
    macro_text = "P{protein}g/C{carbs}g/F{fat}g".format(**macros)
    return "{} | {}g serving | {} kcal ({}% DV) | {} | {} | Allergens: {}".format(recipe_name, serving_size, calories, daily_value_pct, macro_text, vitamin_text, allergen_warning)


def analyze(recipes):
    allergen_names = {0: "none", 1: "milk", 2: "gluten", 3: "nuts"}
    labels = []
    for recipe in recipes:
        protein, carbs, fat, fiber, sugar, sodium, servings = recipe[1:8]
        vitamin_a, vitamin_c, vitamin_d, iron, calcium, magnesium, potassium = recipe[8:15]
        alcohol, cooking_multiplier, thermic_effect = recipe[15:18]
        serving_size, daily_value_pct, allergen_code = recipe[18:21]
        macros = calculate_macros(protein, carbs, fat, fiber, sugar, sodium, servings)
        vitamins = calculate_vitamins(vitamin_a, vitamin_c, vitamin_d, iron, calcium, magnesium, potassium)
        calories = estimate_calories(protein, carbs, fat, alcohol, fiber, cooking_multiplier, thermic_effect)
        labels.append(generate_label(recipe[0], round(calories / servings, 1), macros, vitamins, daily_value_pct, serving_size, allergen_names.get(allergen_code, "unspecified")))
    return labels


