SPEED_MULTIPLIERS = dict(standard=1.0, express=1.6, overnight=2.4)


def calculate_cost(weight, length, width, height, distance, delivery_speed, insurance_value):
    volumetric = (length * width * height) / 5000.0
    billable = max(weight, volumetric)
    base = 4.5 + billable * 1.15 + distance * 0.08
    return round(base * SPEED_MULTIPLIERS[delivery_speed] + insurance_value * 0.012, 2)


def select_carrier(cost, reliability, weekend_delivery, signature_required, hazardous, international, customs_fee):
    if hazardous:
        return "HazMat Freight", "HZ"
    if international or customs_fee > 0:
        return "GlobalEx", "GX"
    if weekend_delivery and reliability >= 0.9:
        return "WeekendRunner", "WR"
    if signature_required and cost > 60:
        return "SecureLine", "SL"
    return "BudgetPost", "BP"


def estimate_transit(distance, average_speed, mandatory_rests, border_delays, traffic_factor, weather_factor, timezone_shifts):
    driving = distance / average_speed * traffic_factor * weather_factor
    overhead = mandatory_rests * 8.0 + border_delays * 1.5 + abs(timezone_shifts) * 0.5
    return round(driving + overhead, 1)


def print_label(order_id, destination_address, return_address, carrier_name, tracking_number, package_weight, barcode_data):
    label = "[{}] {} #{} | to: {} | from: {} | {}kg | {}".format(order_id, carrier_name, tracking_number, destination_address, return_address, package_weight, barcode_data)
    print(label)
    return label


def route(orders):
    labels = []
    for order in orders:
        if len(order) != 22:
            raise ValueError(f"order {order[0]!r} must carry 22 fields, got {len(order)}")
        cost = calculate_cost(order[3], order[4], order[5], order[6], order[7], order[8], order[9])
        carrier, prefix = select_carrier(cost, order[10], order[11], order[12], order[13], order[14], order[15])
        transit = estimate_transit(order[7], order[16], order[17], order[18], order[19], order[20], order[21])
        tracking = f"{prefix}{int(cost * 100):06d}{int(transit * 10):04d}"
        labels.append(print_label(order[0], order[1], order[2], carrier, tracking, order[3], f"*{tracking}*"))
    return labels


