TOTAL_GAMES = 162


def score_batter(singles, doubles, triples, home_runs, runs_batted_in, walks, stolen_bases):
    return singles + doubles * 2.0 + triples * 3.0 + home_runs * 4.0 + runs_batted_in * 1.5 + walks * 0.7 + stolen_bases * 1.2


def score_pitcher(innings_pitched, strikeouts, earned_runs, hits_allowed, walks_allowed, wins, saves):
    return innings_pitched * 1.8 + strikeouts * 1.4 - earned_runs * 2.0 - hits_allowed * 0.4 - walks_allowed * 0.6 + wins * 5.0 + saves * 3.0


def evaluate_trade(player_one_score, player_two_score, team_needs, salary_cap_hit, contract_years, injury_history, age_decline):
    combined = player_one_score + player_two_score * team_needs
    cost = salary_cap_hit / max(contract_years, 1)
    return combined * (1.0 - injury_history) * (1.0 - age_decline) - cost


def project_season(current_score, games_played, total_games, historical_average, health_probability, park_factor, strength_of_schedule):
    pace = current_score / max(games_played, 1) * total_games
    blended = pace * 0.75 + historical_average * total_games * 0.25
    return blended * health_probability * park_factor / max(strength_of_schedule, 0.5)


def format_summary(team_names, projections, total_games):
    league_average = sum(projections) / len(projections)
    lines = []
    for name, projected in zip(team_names, projections):
        margin = projected - league_average
        lines.append(f"{name}: {projected:.2f} over {total_games} games ({margin:+.2f} vs league)")
    return lines


def score(rosters):
    projections = []
    for stats in rosters:
        if len(stats) != 20:
            raise ValueError(f"each roster needs 20 statistics, got {len(stats)}")
        batter_score = score_batter(stats[0], stats[1], stats[2], stats[3], stats[4], stats[5], stats[6])
        pitcher_score = score_pitcher(stats[7], stats[8], stats[9], stats[10], stats[11], stats[12], stats[13])
        games_played, park_factor, strength_of_schedule = stats[14], stats[15], stats[16]
        contract_years, injury_history, age_decline = stats[17], stats[18], stats[19]
        trade_value = evaluate_trade(batter_score, pitcher_score, pitcher_score / (abs(batter_score) + 1.0), (batter_score + pitcher_score) * 0.01 * contract_years, contract_years, injury_history, age_decline)
        projected = project_season(trade_value, games_played, TOTAL_GAMES, (batter_score + pitcher_score) / 2.0 / max(games_played, 1), max(1.0 - injury_history, 0.0), park_factor, strength_of_schedule)
        projections.append(round(projected, 2))
    return projections


