def calculate_calories(user_age, user_weight, user_heart_rate, workout_duration, elevation_gain, average_speed, exercise_type):
    intensity = user_heart_rate / max(220 - user_age, 1)
    terrain = 1.0 + elevation_gain / 1000.0
    pace_factor = 1.0 + average_speed / 20.0
    multiplier = {"run": 1.1, "bike": 0.8, "swim": 1.0}.get(exercise_type, 0.9)
    burn = user_weight * workout_duration / 60.0 * 9.0
    return round(burn * intensity * terrain * pace_factor * multiplier, 1)


def assess_recovery(sleep_duration, sleep_quality, resting_heart_rate, heart_rate_variability, muscle_soreness_level, hydration_level, calorie_deficit):
    score = sleep_duration * 6.0 + sleep_quality * 3.0 + heart_rate_variability * 0.5
    score += hydration_level * 2.0
    score -= resting_heart_rate * 0.6 + muscle_soreness_level * 4.0
    score -= max(calorie_deficit, 0) / 200.0
    return round(max(min(score, 100.0), 0.0), 1)


def track_progress(current_weight, goal_weight, weekly_mileage, body_fat_percent, muscle_mass, breathing_capacity, motivation_level):
    gap = current_weight - goal_weight
    fitness = weekly_mileage * 0.8 + muscle_mass * 0.5 + breathing_capacity * 0.3
    fitness -= body_fat_percent * 0.7 + abs(gap) * 1.5
    return dict(weight_gap=round(gap, 1), fitness_index=round(fitness + motivation_level * 2.0, 1), on_track=gap <= 1.0 and motivation_level >= 5)


def build_weekly_plan(easy_run_days, workout_days, long_run_distance, rest_days, cross_training_activities, target_pace, stretching_minutes):
    template = "{} easy / {} hard / {} rest, long run {} km at {} min/km, cross: {}, stretch {} min"
    return template.format(easy_run_days, workout_days, rest_days, long_run_distance, target_pace, ", ".join(cross_training_activities) or "none", stretching_minutes)


def summarize(workouts):
    plans = []
    for w in workouts:
        calories = calculate_calories(w[0], w[1], w[2], w[3], w[4], w[5], w[6])
        recovery = assess_recovery(w[7], w[8], w[9], w[10], w[11], w[12], calories - 400)
        progress = track_progress(w[1], w[13], w[14], w[15], w[16], w[17], w[18])
        hard = 2 if recovery >= 60 and progress["on_track"] else 1
        plans.append(build_weekly_plan(easy_run_days=7 - w[19] - hard, workout_days=hard, long_run_distance=round(w[14] * 0.3, 1), rest_days=w[19], cross_training_activities=["swim"] if recovery < 60 else ["bike", "yoga"], target_pace=round(6.5 - progress["fitness_index"] / 100.0, 2), stretching_minutes=10 + w[11] * 5))
    return plans


