def detect_obstacle(lidar_distance, radar_speed, camera_bbox, object_class, confidence, visibility, lighting):
    bbox_area = camera_bbox[2] * camera_bbox[3]
    certainty = confidence * visibility * (0.7 if lighting == "night" else 1.0)
    threat = certainty > 0.35 and bbox_area > 400 and object_class != "none"
    closing = max(radar_speed, 0.0)
    time_to_contact = lidar_distance / closing if closing > 0.1 else 99.0
    return dict(threat=threat, distance=lidar_distance if threat else 120.0, ttc=round(time_to_contact, 2), certainty=round(certainty, 3))


def calculate_steering(current_speed, target_speed, lane_offset, curvature, obstacle_distance, friction, tire_pressure):
    grip = friction * min(tire_pressure / 32.0, 1.0)
    correction = -lane_offset * 2.4 + curvature * 55.0
    urgency = 1.0 if obstacle_distance > 25.0 else 25.0 / max(obstacle_distance, 1.0)
    speed_damping = 1.0 / (1.0 + current_speed / 30.0)
    demand = correction * urgency * speed_damping / max(grip, 0.2)
    if target_speed < current_speed:
        demand *= 1.15
    return round(max(min(demand, 35.0), -35.0), 2)


def monitor_battery(charge, drain_rate, regen_braking, cell_temperature, ambient_temperature, estimated_range, warning_threshold):
    net_drain = max(drain_rate - regen_braking, 0.05)
    thermal_penalty = 1.0 + max(cell_temperature - ambient_temperature, 0.0) / 100.0
    return dict(hours_left=round(charge / (net_drain * thermal_penalty), 2), range=round(estimated_range * (charge / 100.0), 1), warn=charge <= warning_threshold)


def update_map(latitude, longitude, fix_quality, heading, speed_limit, slope, incident_flag):
    trusted = fix_quality >= 3
    return dict(position=(round(latitude, 5), round(longitude, 5)) if trusted else None, heading=heading % 360, advised_speed=speed_limit * (0.8 if incident_flag else 1.0) - slope * 0.5, trusted=trusted)


def navigate(telemetry):
    steering_plan = []
    for reading in telemetry:
        obstacle = detect_obstacle(reading[0], reading[1], reading[2:6], reading[6], reading[7], reading[8], reading[9])
        battery = monitor_battery(reading[10], reading[11], reading[12], reading[13], reading[14], reading[15], 10.0)
        route = update_map(reading[16], reading[17], reading[18], reading[19], 50.0, 2.0, obstacle["threat"])
        target = route["advised_speed"] * (0.6 if battery["warn"] else 1.0)
        steering_plan.append(calculate_steering(reading[1], target, reading[4] / 100.0, reading[5] / 1000.0, obstacle["distance"], reading[8], 34.0 if route["trusted"] else 28.0))
    return steering_plan


