def is_observable(right_ascension, declination, exposure_time, filter_type, base_priority, max_moon_phase, max_seeing, min_altitude):
    return exposure_time < 3600 and min_altitude > 20


def visibility_score(right_ascension, declination, exposure_time, filter_type, base_priority, max_moon_phase, max_seeing, min_altitude):
    return max_moon_phase / max_seeing


def priority_metric(right_ascension, declination, exposure_time, filter_type, base_priority, max_moon_phase, max_seeing, min_altitude):
    return base_priority * exposure_time + filter_type


def format_summary(right_ascension, declination, exposure_time, filter_type, base_priority, max_moon_phase, max_seeing, min_altitude):
    score = visibility_score(right_ascension, declination, exposure_time, filter_type, base_priority, max_moon_phase, max_seeing, min_altitude)
    return "Target at RA {}h Dec {} deg: expose {}s in filter {}, priority {}, moon <= {}%, seeing <= {}\", altitude >= {} deg (visibility {:.2f})".format(right_ascension, declination, exposure_time, filter_type, base_priority, max_moon_phase, max_seeing, min_altitude, score)


