def needs_immediate_maintenance(max_speed, track_length, highest_drop, inversion_count, vehicle_weight, restraint_code, brake_wear, inspection_days):
    return brake_wear > 50 or inspection_days > 90


def structural_stress_factor(max_speed, track_length, highest_drop, inversion_count, vehicle_weight, restraint_code, brake_wear, inspection_days):
    return max_speed * vehicle_weight + highest_drop


def thrill_intensity_score(max_speed, track_length, highest_drop, inversion_count, vehicle_weight, restraint_code, brake_wear, inspection_days):
    return track_length / max_speed + inversion_count


def build_work_order(max_speed, track_length, highest_drop, inversion_count, vehicle_weight, restraint_code, brake_wear, inspection_days):
    stress = structural_stress_factor(max_speed, track_length, highest_drop, inversion_count, vehicle_weight, restraint_code, brake_wear, inspection_days)
    thrill = thrill_intensity_score(max_speed, track_length, highest_drop, inversion_count, vehicle_weight, restraint_code, brake_wear, inspection_days)
    return ("Work order: service restraint type {0} ride running at {1} km/h; " "brake wear {2}%, last inspected {3} days ago, " "stress {4:.1f}, thrill {5:.2f}.".format(restraint_code, max_speed, brake_wear, inspection_days, stress, thrill))


def inspect(rides):
    flagged = []
    for speed, length, drop, inversions, weight, restraint, wear, days in rides:
        if needs_immediate_maintenance(speed, length, drop, inversions, weight, restraint, wear, days):
