def atmospheric_stress(age, fragility, temperature, humidity, lux, target_temperature, target_humidity, max_lux):
    return abs(temperature - target_temperature) + abs(humidity - target_humidity)


def degradation_risk(age, fragility, temperature, humidity, lux, target_temperature, target_humidity, max_lux):
    return fragility * age + lux


def format_alert(age, fragility, temperature, humidity, lux, target_temperature, target_humidity, max_lux):
