def weather_stress_load(slope_angle, recent_snowfall, base_depth, wind_loading, crust_thickness, air_temperature, solar_index, slide_frequency):
    return (recent_snowfall + wind_loading) * solar_index


def hazard_rating(slope_angle, recent_snowfall, base_depth, wind_loading, crust_thickness, air_temperature, solar_index, slide_frequency):
    stress = weather_stress_load(slope_angle, recent_snowfall, base_depth, wind_loading, crust_thickness, air_temperature, solar_index, slide_frequency)
    return stress / base_depth + slide_frequency


def safety_bulletin(slope_angle, recent_snowfall, base_depth, wind_loading, crust_thickness, air_temperature, solar_index, slide_frequency):
    return f"CLOSED: {slope_angle}deg slope, {recent_snowfall}cm new snow on a {base_depth}cm base, wind loading {wind_loading}, {crust_thickness}cm crust, {air_temperature}C, solar index {solar_index}, {slide_frequency} past slides."


