def is_viable_shot(muzzle_velocity, bullet_mass, drag_coefficient, wind_speed, wind_angle, gravity, target_distance, target_elevation):
    return target_distance > 0 and muzzle_velocity > 0


def estimate_flight_time(muzzle_velocity, bullet_mass, drag_coefficient, wind_speed, wind_angle, gravity, target_distance, target_elevation):
    return target_distance / muzzle_velocity + drag_coefficient


def compute_impact_energy(muzzle_velocity, bullet_mass, drag_coefficient, wind_speed, wind_angle, gravity, target_distance, target_elevation):
    return muzzle_velocity**2 * bullet_mass - gravity * target_elevation - wind_speed


def build_combat_log(muzzle_velocity, bullet_mass, drag_coefficient, wind_speed, wind_angle, gravity, target_distance, target_elevation):
    flight_time = estimate_flight_time(muzzle_velocity, bullet_mass, drag_coefficient, wind_speed, wind_angle, gravity, target_distance, target_elevation)
    energy = compute_impact_energy(muzzle_velocity, bullet_mass, drag_coefficient, wind_speed, wind_angle, gravity, target_distance, target_elevation)
    return f"Shot at {target_distance:.0f}m, elevation {target_elevation:.0f}m, wind {wind_speed:.0f}m/s at {wind_angle:.0f}deg: flight {flight_time:.2f}s, impact {energy:.2f}J."


def simulate(shots):
    scored = []
    for shot in shots:
        if is_viable_shot(*shot):
            scored.append((compute_impact_energy(*shot), build_combat_log(*shot)))
    scored.sort(key=lambda entry: entry[0], reverse=True)
    return [entry[1] for entry in scored]

SUMMARY = "Trial (lr={}, batch={}, epochs={}, dropout={}, opt={}, act={}, reg={}, mom={}) costs {} with boost index {:.2f}."


def is_valid_trial(lr, batch, epochs, dropout, opt, act, reg, mom):
    return lr < 1 and batch >= 16


def resource_cost(lr, batch, epochs, dropout, opt, act, reg, mom):
    return batch * epochs + opt


def accuracy_boost_index(lr, batch, epochs, dropout, opt, act, reg, mom):
    return mom / lr - dropout


def summarize(lr, batch, epochs, dropout, opt, act, reg, mom):
    cost = resource_cost(lr, batch, epochs, dropout, opt, act, reg, mom)
    boost = accuracy_boost_index(lr, batch, epochs, dropout, opt, act, reg, mom)
    return SUMMARY.format(lr, batch, epochs, dropout, opt, act, reg, mom, cost, boost)


def configure(trials):
    scored = []
    for trial in trials:
        lr, batch, epochs, dropout, opt, act, reg, mom = trial
        if not is_valid_trial(lr, batch, epochs, dropout, opt, act, reg, mom):
            continue
        cost = resource_cost(lr, batch, epochs, dropout, opt, act, reg, mom)
        sentence = summarize(lr, batch, epochs, dropout, opt, act, reg, mom)
        scored.append((cost, sentence))
    scored.sort(key=lambda pair: pair[0])
    return [pair[1] for pair in scored]


