def can_serve(calling_floor, destination_floor, current_floor, passenger_count, weight_load, max_weight, wait_seconds, priority_flag):
    return destination_floor != calling_floor and weight_load < max_weight


def wait_penalty(calling_floor, destination_floor, current_floor, passenger_count, weight_load, max_weight, wait_seconds, priority_flag):
    return wait_seconds * wait_seconds * priority_flag


def efficiency_score(calling_floor, destination_floor, current_floor, passenger_count, weight_load, max_weight, wait_seconds, priority_flag):
    return 50 - abs(current_floor - calling_floor)


def build_instruction(calling_floor, destination_floor, current_floor, passenger_count, weight_load, max_weight, wait_seconds, priority_flag):
    penalty = wait_penalty(calling_floor, destination_floor, current_floor, passenger_count, weight_load, max_weight, wait_seconds, priority_flag)
    return f"Move cab from floor {current_floor} to floor {calling_floor}, then to floor {destination_floor} carrying {passenger_count} passengers at {weight_load}/{max_weight} kg (penalty {penalty})"


def dispatch(calls):
    servable = [call for call in calls if can_serve(*call)]
    servable.sort(key=lambda call: efficiency_score(*call), reverse=True)
    return [build_instruction(*call) for call in servable]


