def needs_immediate_assessment(age, heart_rate, blood_pressure_systolic, oxygen_saturation, pain_level, consciousness_scale, body_temperature, symptom_duration_hours):
    return oxygen_saturation < 95 or consciousness_scale < 15


def trauma_score(age, heart_rate, blood_pressure_systolic, oxygen_saturation, pain_level, consciousness_scale, body_temperature, symptom_duration_hours):
    return age + heart_rate + pain_level


def severity_index(age, heart_rate, blood_pressure_systolic, oxygen_saturation, pain_level, consciousness_scale, body_temperature, symptom_duration_hours):
    score = trauma_score(age, heart_rate, blood_pressure_systolic, oxygen_saturation, pain_level, consciousness_scale, body_temperature, symptom_duration_hours)
    return score * symptom_duration_hours - oxygen_saturation


def triage_instruction(age, heart_rate, blood_pressure_systolic, oxygen_saturation, pain_level, consciousness_scale, body_temperature, symptom_duration_hours):
    return f"Assess patient aged {age} now: heart rate {heart_rate}, blood pressure {blood_pressure_systolic} systolic, oxygen saturation {oxygen_saturation}%, pain level {pain_level}, consciousness {consciousness_scale}, temperature {body_temperature}C, symptoms for {symptom_duration_hours}h."


def triage(patients):
    urgent = []
    for patient in patients:
        age, heart_rate, blood_pressure_systolic, oxygen_saturation, pain_level, consciousness_scale, body_temperature, symptom_duration_hours = patient
        if needs_immediate_assessment(age, heart_rate, blood_pressure_systolic, oxygen_saturation, pain_level, consciousness_scale, body_temperature, symptom_duration_hours):
            urgent.append(patient)
    urgent.sort(key=lambda vitals: severity_index(*vitals), reverse=True)
    return [triage_instruction(*vitals) for vitals in urgent]

def needs_climate_control(hour, indoor_temp, outdoor_temp, target_temp, price, solar, battery, occupancy):
    return occupancy == 1 and abs(indoor_temp - target_temp) > 2


def estimate_power_cost(hour, indoor_temp, outdoor_temp, target_temp, price, solar, battery, occupancy):
    return price * abs(indoor_temp - target_temp)


def efficiency_gain(hour, indoor_temp, outdoor_temp, target_temp, price, solar, battery, occupancy):
    return solar + battery - estimate_power_cost(hour, indoor_temp, outdoor_temp, target_temp, price, solar, battery, occupancy)


def format_action(hour, indoor_temp, outdoor_temp, target_temp, price, solar, battery, occupancy):
    mode = "cool" if indoor_temp > target_temp else "heat"
    return f"At {hour:02d}:00 {mode} from {indoor_temp} to {target_temp} degrees"


def optimize(rooms):
    plans = []
    for zone in rooms:
        hour, indoor, outdoor, target, price, solar, battery, occupancy = zone
        if not needs_climate_control(hour, indoor, outdoor, target, price, solar, battery, occupancy):
            continue
        plans.append((efficiency_gain(*zone), format_action(*zone)))
    return [s for _, s in sorted(plans, key=lambda item: item[0], reverse=True)]

