def is_valid_job(paper_type, paper_weight, color_count, page_count, binding_type, quantity, setup_minutes, run_speed):
    return quantity > 0 and 1 <= color_count <= 4 and run_speed > 0


def material_cost(paper_type, paper_weight, color_count, page_count, binding_type, quantity, setup_minutes, run_speed):
    return page_count * quantity * paper_weight * 0.0002 + color_count * 25.0


def operational_cost(paper_type, paper_weight, color_count, page_count, binding_type, quantity, setup_minutes, run_speed):
    materials = material_cost(paper_type, paper_weight, color_count, page_count, binding_type, quantity, setup_minutes, run_speed)
    return setup_minutes * 10.0 + quantity / run_speed + materials


def quotation_sentence(paper_type, paper_weight, color_count, page_count, binding_type, quantity, setup_minutes, run_speed):
    total = operational_cost(paper_type, paper_weight, color_count, page_count, binding_type, quantity, setup_minutes, run_speed)
    return SENTENCE.format(qty=quantity, pages=page_count, paper=PAPER_TYPES.get(paper_type, "custom"), weight=paper_weight, colors=color_count, binding=BINDING_TYPES.get(binding_type, "loose"), minutes=setup_minutes, speed=run_speed, total=total)


def parse_jobs(sheet):
