def is_valid_observation(star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature):
    return planet_mass > 0 and orbital_period > 0


def radiation_load(star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature):
    return star_temperature * star_radius / semi_major_axis


def habitability_index(star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature):
    load = radiation_load(star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature)
    return load - eccentricity + planet_radius / star_mass


def summary_sentence(star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature):
    index = habitability_index(star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature)
    template = "Planet of mass {:.2f} and radius {:.2f} orbits a star of mass {:.2f} every {:.1f} days with habitability index {:.2f}"
    return template.format(planet_mass, planet_radius, star_mass, orbital_period, index)


def classify(planets):
    scored = []
    for planet in planets:
        star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature = planet
        if is_valid_observation(star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature):
            index = habitability_index(star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature)
            sentence = summary_sentence(star_mass, star_radius, planet_mass, planet_radius, orbital_period, semi_major_axis, eccentricity, star_temperature)
            scored.append((index, sentence))
    scored.sort(key=lambda entry: entry[0], reverse=True)
    return [sentence for _, sentence in scored]


