SENTENCE_TEMPLATE = "Waves {}m every {}s, wind {}kn gusting {}kn, air {}C over water {}C, pressure {}hPa, tide {}m, turbulence {:.2f}"


def storm_warning(wave_height, wave_period, wind_speed, wind_gust_speed, air_temperature, water_temperature, pressure, tide_level):
    return wave_height > 4 or wind_speed > 20


def turbulence_factor(wave_height, wave_period, wind_speed, wind_gust_speed, air_temperature, water_temperature, pressure, tide_level):
    return wave_height * wind_gust_speed / wave_period


def danger_score(wave_height, wave_period, wind_speed, wind_gust_speed, air_temperature, water_temperature, pressure, tide_level):
    turbulence = turbulence_factor(wave_height, wave_period, wind_speed, wind_gust_speed, air_temperature, water_temperature, pressure, tide_level)
    thermal_gap = abs(air_temperature - water_temperature)
    return turbulence + thermal_gap - pressure / 1000


def condition_sentence(wave_height, wave_period, wind_speed, wind_gust_speed, air_temperature, water_temperature, pressure, tide_level):
    turbulence = turbulence_factor(wave_height, wave_period, wind_speed, wind_gust_speed, air_temperature, water_temperature, pressure, tide_level)
    return SENTENCE_TEMPLATE.format(wave_height, wave_period, wind_speed, wind_gust_speed, air_temperature, water_temperature, pressure, tide_level, turbulence)


def aggregate(buoys):
    warned = []
    for readings in buoys:
        if storm_warning(*readings):
            warned.append((danger_score(*readings), condition_sentence(*readings)))
    warned.sort(key=lambda entry: entry[0], reverse=True)
    return [sentence for _, sentence in warned]


