def can_modify_geometry(overall_height, inseam_length, arm_length, torso_length, shoe_size, flexibility_index, riding_style_code, preferred_saddle_height):
    return inseam_length > 70 and flexibility_index > 0


def drag_factor(overall_height, inseam_length, arm_length, torso_length, shoe_size, flexibility_index, riding_style_code, preferred_saddle_height):
    return overall_height / flexibility_index + riding_style_code


def frame_reach(overall_height, inseam_length, arm_length, torso_length, shoe_size, flexibility_index, riding_style_code, preferred_saddle_height):
    factor = drag_factor(overall_height, inseam_length, arm_length, torso_length, shoe_size, flexibility_index, riding_style_code, preferred_saddle_height)
    return (torso_length + arm_length) / 2 - factor


def build_sentence(overall_height, inseam_length, arm_length, torso_length, shoe_size, flexibility_index, riding_style_code, preferred_saddle_height):
    reach = frame_reach(overall_height, inseam_length, arm_length, torso_length, shoe_size, flexibility_index, riding_style_code, preferred_saddle_height)
    return ("Frame for rider of {0}cm with {1}cm inseam: reach {2:.2f}, " "shoe {3}, saddle {4}cm, style {5}".format(overall_height, inseam_length, reach, shoe_size, preferred_saddle_height, riding_style_code))


def calculate(riders):
    designs = []
    for rider in riders:
        if can_modify_geometry(*rider):
            designs.append((frame_reach(*rider), build_sentence(*rider)))
    designs.sort(key=lambda entry: entry[0], reverse=True)
    return [sentence for _, sentence in designs]


