def is_valid_sour(spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, bitter_drops, dilution_volume):
    return citrus_volume > 0 and spirit_volume >= 2 * citrus_volume


def acid_balance_ratio(spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, bitter_drops, dilution_volume):
    return citrus_volume * citrus_acidity / dilution_volume


def sweetness_score(spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, bitter_drops, dilution_volume):
    ratio = acid_balance_ratio(spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, bitter_drops, dilution_volume)
    return syrup_volume * syrup_sugar - ratio + bitter_drops


def recipe_instruction(spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, bitter_drops, dilution_volume):
    return "Shake {:.0f}ml spirit ({:.0f}% ABV), {:.0f}ml citrus (acidity {:.1f}) and {:.0f}ml syrup ({:.0f}% sugar) with {:.0f}ml water, then add {:.0f} dashes of bitters.".format(spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, dilution_volume, bitter_drops)


def balance(recipes):
    scored = []
    for recipe in recipes:
        spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, bitter_drops, dilution_volume = recipe
        if is_valid_sour(spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, bitter_drops, dilution_volume):
            score = sweetness_score(spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, bitter_drops, dilution_volume)
            sentence = recipe_instruction(spirit_volume, spirit_abv, citrus_volume, citrus_acidity, syrup_volume, syrup_sugar, bitter_drops, dilution_volume)
            scored.append((score, sentence))
    return [pair[1] for pair in sorted(scored, key=lambda pair: -pair[0])]

def needs_evacuation(tremor_frequency, seismic_amplitude, sulfur_dioxide, ground_deformation, vent_temperature, atmospheric_pressure, town_distance, reliability):
    return tremor_frequency > 50 and sulfur_dioxide > 500

def energy_release_factor(tremor_frequency, seismic_amplitude, sulfur_dioxide, ground_deformation, vent_temperature, atmospheric_pressure, town_distance, reliability):
    return seismic_amplitude * tremor_frequency + vent_temperature

def threat_severity_index(tremor_frequency, seismic_amplitude, sulfur_dioxide, ground_deformation, vent_temperature, atmospheric_pressure, town_distance, reliability):
    energy = energy_release_factor(tremor_frequency, seismic_amplitude, sulfur_dioxide, ground_deformation, vent_temperature, atmospheric_pressure, town_distance, reliability)
    return energy * ground_deformation / town_distance

def public_alert(tremor_frequency, seismic_amplitude, sulfur_dioxide, ground_deformation, vent_temperature, atmospheric_pressure, town_distance, reliability):
    severity = threat_severity_index(tremor_frequency, seismic_amplitude, sulfur_dioxide, ground_deformation, vent_temperature, atmospheric_pressure, town_distance, reliability)
    return f"EVACUATE: town {town_distance} km away, tremor {tremor_frequency} Hz, SO2 {sulfur_dioxide} t/day, deformation {ground_deformation} mm, vent {vent_temperature} C, amplitude {seismic_amplitude}, severity {severity:.1f} (reliability {reliability}%, pressure {atmospheric_pressure} hPa)"

def warn(sensors):
    alerts = []
    for station in sensors:
        if needs_evacuation(*station):
            alerts.append((threat_severity_index(*station), public_alert(*station)))
    alerts.sort(key=lambda pair: pair[0], reverse=True)
    return [sentence for _, sentence in alerts]

