def needs_emergency_purge(carbon_dioxide, oxygen, nitrogen, temperature, humidity, airflow, particulates, filter_life):
    return carbon_dioxide > 5000 or particulates > 1000


def airflow_efficiency_ratio(carbon_dioxide, oxygen, nitrogen, temperature, humidity, airflow, particulates, filter_life):
    return airflow / humidity + oxygen


def maintenance_urgency_score(carbon_dioxide, oxygen, nitrogen, temperature, humidity, airflow, particulates, filter_life):
    ratio = airflow_efficiency_ratio(carbon_dioxide, oxygen, nitrogen, temperature, humidity, airflow, particulates, filter_life)
    return (100 - filter_life) + particulates / 10 - ratio


def intervention_command(carbon_dioxide, oxygen, nitrogen, temperature, humidity, airflow, particulates, filter_life):
    urgency = maintenance_urgency_score(carbon_dioxide, oxygen, nitrogen, temperature, humidity, airflow, particulates, filter_life)
    return "Purge module: CO2 {} ppm, O2 {}%, N2 {}%, {}C, {}% RH, airflow {}, particulates {}, filter {}% - urgency {:.2f}".format(carbon_dioxide, oxygen, nitrogen, temperature, humidity, airflow, particulates, filter_life, urgency)


def control(modules):
    flagged = []
    for module in modules:
        if needs_emergency_purge(*module):
            flagged.append((maintenance_urgency_score(*module), intervention_command(*module)))
    flagged.sort(key=lambda entry: entry[0], reverse=True)
    return [command for _, command in flagged]


