WORD_TO_NUMBER = {"zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6}

Order = namedtuple("Order", "name beverage size milk syrup pumps temperature")


def parse_pump_count(raw):
    text = raw.strip().lower()
    if text.isdigit():
        return int(text)
    if text in WORD_TO_NUMBER:
        return WORD_TO_NUMBER[text]
    raise ValueError("unrecognised pump count: %r" % raw)


def normalize_order(line):
    fields = [part.strip() for part in line.split(",")]
    if len(fields) != 7:
        raise ValueError("expected 7 fields in %r, found %d" % (line, len(fields)))
    name, beverage, size, milk, syrup, pumps, temperature = fields
    return Order(name.title(), beverage.title(), size.title(), milk.title(), syrup.title(), parse_pump_count(pumps), temperature.title())


def barista_instructions(beverage, size, milk, syrup, temperature):
    steps = ["pull %d shot(s) for %s" % (SHOTS_BY_SIZE[size], beverage.lower())]
    if temperature == "Hot":
        steps.append("steam %s milk to 65C" % milk.lower())
    else:
        steps.append("pour %s milk over ice" % milk.lower())
    if syrup != "None":
        steps.append("swirl %s syrup through the cup" % syrup.lower())
    return steps


def flavor_additions(size, milk, syrup, pumps, temperature):
    if syrup == "None" or pumps == 0:
        return ["no syrup"]
    notes = ["%d pump(s) of %s" % (pumps, syrup.lower())]
    allowed = MAX_PUMPS_BY_SIZE[size]
    if pumps > allowed:
        notes.append("above the %s standard of %d" % (size.lower(), allowed))
    if temperature == "Iced":
        notes.append("shake with %s milk before pouring" % milk.lower())
    return notes


def format_sticker(order, instructions, additions):
    header = "{0}: {1} {2} {3}, {4} syrup x{5}, {6}".format(order.name, order.size, order.milk, order.beverage, order.syrup, order.pumps, order.temperature)
    return "%s | %s | %s" % (header, "; ".join(instructions), "; ".join(additions))


def parse(drinks):
    stickers = []
    for line in drinks:
        order = normalize_order(line)
        instructions = barista_instructions(order.beverage, order.size, order.milk, order.syrup, order.temperature)
        additions = flavor_additions(order.size, order.milk, order.syrup, order.pumps, order.temperature)
        stickers.append(format_sticker(order, instructions, additions))
    return stickers


def main():
    orders = ["Frank, Latte, Large, Oat, Vanilla, two, Hot", "Priya, Mocha, Medium, Soy, Caramel, 5, Iced"]
    for sticker in parse(orders):
        print(sticker)


if __name__ == "__main__":
    main()

SURFACE_FACTORS = {"paved": 1.0, "gravel": 1.3, "dirt": 1.5, "sand": 1.8}
TRAFFIC_FACTORS = {"low": 1.0, "moderate": 1.2, "heavy": 1.45}

TEMPLATE = "{0}: {1:.1f} km, {2:.0f} m climb, {3} surface, {4} traffic, {5} rest stops, {6:.1f} km/h headwind -> score {7:.1f}"


def validate(name, distance, elevation, surface, traffic, rest_stops, headwind):
    if not isinstance(name, str) or not name.strip():
        raise ValueError("route name must be a non-empty string")
    if distance <= 0:
        raise ValueError("total distance must be positive")
    if elevation < 0:
        raise ValueError("elevation gain cannot be negative")
    if surface not in SURFACE_FACTORS:
        raise ValueError("unknown road surface: %r" % (surface,))
    if traffic not in TRAFFIC_FACTORS:
        raise ValueError("unknown traffic density: %r" % (traffic,))
    if rest_stops < 0:
        raise ValueError("rest stops cannot be negative")
    if headwind < 0:
        raise ValueError("headwind speed cannot be negative")
    return name.strip(), float(distance), float(elevation), surface, traffic, int(rest_stops), float(headwind)


def terrain_difficulty(distance, elevation, surface, traffic, headwind):
    base = distance * SURFACE_FACTORS[surface] * TRAFFIC_FACTORS[traffic]
    return base + elevation / 100.0 + headwind * 0.8


def environmental_challenge(elevation, surface, traffic, rest_stops, headwind):
    exposure = elevation / 250.0 + headwind * 1.1
    roughness = (SURFACE_FACTORS[surface] - 1.0) * 10.0
    congestion = (TRAFFIC_FACTORS[traffic] - 1.0) * 15.0
    total = exposure + roughness + congestion
    return total - min(rest_stops * 2.5, total)


def assess(routes):
    guidebook = []
    for route in routes:
        name, distance, elevation, surface, traffic, rest_stops, headwind = validate(route["name"], route["distance"], route["elevation"], route["surface"], route["traffic"], route["rest_stops"], route["headwind"])
        score = terrain_difficulty(distance, elevation, surface, traffic, headwind) + environmental_challenge(elevation, surface, traffic, rest_stops, headwind)
        guidebook.append(TEMPLATE.format(name, distance, elevation, surface, traffic, rest_stops, headwind, score))
    return guidebook


def main():
    valley_loop = dict(name="Valley Loop", distance=20, elevation=1000, surface="paved", traffic="low", rest_stops=2, headwind=0)
    for line in assess([valley_loop]):
        print(line)


if __name__ == "__main__":
    main()

def validate_rack(designation, used_units, max_units, power_used, power_max, cooling_used, cooling_max):
    if not isinstance(designation, str) or not designation.strip():
        raise ValueError("rack designation must be a non-empty string")
    numbers = (used_units, max_units, power_used, power_max, cooling_used, cooling_max)
    if any(not isinstance(value, int) or value < 0 for value in numbers):
        raise ValueError("capacity metrics must be non-negative integers")
    if used_units > max_units or power_used > power_max or cooling_used > cooling_max:
        raise ValueError("current usage exceeds the declared maximum")
    return (designation.strip(),) + numbers


def space_available(used_units, max_units, power_used, cooling_used, cooling_max):
    free_units = max_units - used_units
    cooling_slack = cooling_max - cooling_used
    return free_units >= 2 and cooling_slack > 0 and power_used < 400 * free_units


def overhead_ok(max_units, power_used, power_max, cooling_used, cooling_max):
    power_headroom = (power_max - power_used) / power_max
    cooling_headroom = (cooling_max - cooling_used) / cooling_max
    return power_headroom >= 0.2 and cooling_headroom >= 0.2 and max_units >= 8


def format_audit(designation, used_units, max_units, power_used, power_max, cooling_used, cooling_max):
    return "{0}: units {1}/{2}, power {3}/{4}W, cooling {5}/{6}BTU".format(designation, used_units, max_units, power_used, power_max, cooling_used, cooling_max)


def plan(racks):
    report = []
    for record in racks:
        designation, used, units, power, power_cap, cooling, cooling_cap = validate_rack(*record)
        roomy = space_available(used, units, power, cooling, cooling_cap)
        spare = overhead_ok(units, power, power_cap, cooling, cooling_cap)
        if roomy and spare:
            report.append(format_audit(designation, used, units, power, power_cap, cooling, cooling_cap))
    return report


def main():
    racks = [("Alpha", 10, 40, 2000, 5000, 100, 200)]
    for line in plan(racks):
        print(line)


if __name__ == "__main__":
    main()

