    case_material,
    stabilizer_type,
    lighting,
    wireless,
):
    issues = []
    if wireless and case_material == "aluminum":
        issues.append("aluminum case attenuates the wireless antenna")
    if wireless and lighting and layout in ("tkl", "full"):
        issues.append("lighting on a large wireless board drains the battery")
    if lighting and case_material == "wood":
        issues.append("wood case gives no light diffusion")
    if wireless and stabilizer_type == "pcbscrewin":
        issues.append("screw-in stabilizers may foul the battery tray")
    return issues


def format_build_summary(
    layout,
    switch_mount,
    case_material,
    keycap_profile,
    stabilizer_type,
    lighting,
    wireless,
    verdict,
):
    return SUMMARY_TEMPLATE.format(
        layout=LAYOUT_LABELS.get(layout, layout),
        mount=switch_mount,
        case=case_material,
        profile=keycap_profile,
        stab=stabilizer_type,
        light="yes" if lighting else "no",
        wifi="yes" if wireless else "no",
        verdict=verdict,
    )


def parse_parts_list(text):
    return [tuple(field.strip() for field in line.split(",")) for line in text.strip().splitlines()]


def verify(keyboards):
    summaries = []
    for parts in keyboards:
        layout, mount, case, profile, stabilizer, lighting, wireless = normalize_parts(parts)
        mechanical = check_mechanical_fit(
            layout,
            mount,
            case,
            profile,
            stabilizer,
        )
        electronic = check_electronics(
            layout,
            case,
            stabilizer,
            lighting,
            wireless,
        )
        if mechanical:
            verdict = "INCOMPATIBLE: " + "; ".join(mechanical + electronic)
        elif electronic:
            verdict = "COMPATIBLE WITH NOTES: " + "; ".join(electronic)
        else:
            verdict = "FULLY COMPATIBLE"
        summaries.append(
            format_build_summary(
                layout,
                mount,
                case,
                profile,
                stabilizer,
                lighting,
                wireless,
                verdict,
            )
        )
    return summaries


def main():
    catalog = """
    sixty, plate, aluminum, cherry, plate, true, true
    seventyfive, gasket, polycarbonate, SA, PCB screw-in, yes, no
    full, tray, acrylic, OEM, PCB clip-in, true, false
    """
    for summary in verify(parse_parts_list(catalog)):
        print(summary)


if __name__ == "__main__":
