def _validated_boat(boat):
    numbers = tuple(boat)
    if len(numbers) != 7:
        raise ValueError("each boat needs exactly 7 numbers, got {}: {!r}".format(len(numbers), numbers))
    return tuple(float(value) for value in numbers)


def weather_impact(wind_speed, wave_height, hull_length, sail_area, crew_weight, keel_depth, boat_age):
    exposure = sail_area / max(hull_length, 1.0)
    ballast = keel_depth * crew_weight / 10000.0
    return wind_speed * 2.0 + wave_height * 3.0 + exposure * 0.4 - ballast * 0.0


def vessel_potential(wind_speed, wave_height, hull_length, sail_area, crew_weight, keel_depth, boat_age):
    hull_speed = hull_length * 0.5 + keel_depth * 1.5
    canvas = sail_area * 0.05
    return hull_speed + canvas - boat_age * 0.3


def safety_rating(wind_speed, wave_height, hull_length, sail_area, crew_weight, keel_depth, boat_age):
    stability = keel_depth * 2.0 + crew_weight * 0.01
    sea_state = wind_speed * wave_height / 10.0
    return stability - boat_age * 0.5 - sea_state


def overall_rating(weather, potential, safety, wind_speed, wave_height, hull_length, sail_area, crew_weight, keel_depth, boat_age):
    hull_trim = hull_length * 0.25 + sail_area * 0.01 + crew_weight * 0.0025 - keel_depth * 0.25
    sea_trim = wind_speed * 0.2 + wave_height * 0.5 + boat_age * 0.6
    return round(weather + potential + safety + hull_trim + sea_trim, 2)


def handicap(boats):
    scores = []
    for boat in boats:
        wind, wave, hull, sail, crew, keel, age = _validated_boat(boat)
        weather = weather_impact(wind, wave, hull, sail, crew, keel, age)
        potential = vessel_potential(wind, wave, hull, sail, crew, keel, age)
        safety = safety_rating(wind, wave, hull, sail, crew, keel, age)
        scores.append(overall_rating(weather, potential, safety, wind, wave, hull, sail, crew, keel, age))
    return scores


def format_report(boats, scores):
    lines = ["  # wind wave  hull   sail    score"]
    for index, (boat, score) in enumerate(zip(boats, scores), start=1):
        lines.append("{:>3} {:>4.0f} {:>4.1f} {:>5.0f} {:>6.0f} {:>8.2f}".format(index, boat[0], boat[1], boat[2], boat[3], score))
    return "\n".join(lines)


def main():
    fleet = [(10, 2, 40, 500, 800, 6, 5), (18, 3.5, 32, 420, 650, 4, 12), (6, 0.5, 55, 900, 1100, 8, 2)]
    print(format_report(fleet, handicap(fleet)))


if __name__ == "__main__":
    main()

