def _clamp(value, low, high):
    return max(low, min(high, value))


def validate_batch(batch):
    if len(batch) != 7:
        raise ValueError("a tea batch needs exactly seven characteristics")
    for characteristic in batch:
        if not isinstance(characteristic, (int, float)) or isinstance(characteristic, bool):
            raise TypeError("tea characteristics must be numeric")
    return tuple(float(characteristic) for characteristic in batch)


def breakfast_affinity(
    tannin,
    floral,
    citrus,
    earthiness,
    caffeine,
    moisture,
    leaf_size,
):
    raw = 6.0 * tannin + 4.0 * earthiness + 0.5 * caffeine + 2.0 * leaf_size - 3.0 * floral - 2.0 * citrus - 1.5 * moisture
    return _clamp(raw, 0.0, 100.0)


def afternoon_affinity(
    tannin,
    floral,
    citrus,
    earthiness,
    caffeine,
    moisture,
    leaf_size,
):
    raw = 6.0 * floral + 5.0 * citrus + 0.3 * caffeine + 2.0 * leaf_size - 2.0 * tannin - 2.0 * earthiness - 1.5 * moisture
    return _clamp(raw, 0.0, 100.0)


def evening_affinity(
    tannin,
    floral,
    citrus,
    earthiness,
    caffeine,
    moisture,
    leaf_size,
):
    raw = 5.0 * floral + 3.0 * citrus + 3.0 * earthiness + 2.0 * leaf_size - 4.0 * tannin - 0.4 * caffeine - 2.0 * moisture
    return _clamp(raw, 0.0, 100.0)


def market_value(
    breakfast,
    afternoon,
    evening,
    tannin,
    floral,
    citrus,
    earthiness,
    caffeine,
    moisture,
    leaf_size,
):
    scores = sorted([breakfast, afternoon, evening], reverse=True)
    price = 0.05 * scores[0] + 0.02 * (scores[1] + scores[2]) + 0.05 * leaf_size - 0.01 * moisture + 0.0005 * caffeine + 0.001 * (tannin + floral + citrus + earthiness)
    return round(max(price, 0.0), 2)


def format_listing(index, batch, price):
    return f"batch {index}: caffeine {batch[4]:g}mg, moisture {batch[5]:g}%, leaf {batch[6]:g} -> ${price:.2f}/oz"


def blend(teas):
    prices = []
    for batch in teas:
        tannin, floral, citrus, earthiness, caffeine, moisture, leaf_size = validate_batch(batch)
        breakfast = breakfast_affinity(tannin, floral, citrus, earthiness, caffeine, moisture, leaf_size)
        afternoon = afternoon_affinity(tannin, floral, citrus, earthiness, caffeine, moisture, leaf_size)
        evening = evening_affinity(tannin, floral, citrus, earthiness, caffeine, moisture, leaf_size)
        prices.append(
            market_value(
                breakfast,
                afternoon,
                evening,
                tannin,
                floral,
                citrus,
                earthiness,
                caffeine,
                moisture,
                leaf_size,
            )
        )
    return prices


def main():
    teas = [(4, 3, 1, 5, 80, 10, 2), (1, 8, 6, 1, 25, 6, 3), (2, 6, 2, 3, 2, 8, 4)]
    for index, price in enumerate(blend(teas), start=1):
        print(format_listing(index, teas[index - 1], price))


