def validate_track(track):
    if len(track) != 7 or track[1] < 1 or track[2] <= 0 or track[3] <= 0:
        raise ValueError(f"invalid track settings: {track}")
    return tuple(float(setting) for setting in track)

def estimate_noise_reduction(noise_floor, ratio, attack, release, gain, bass, treble):
    penalty = attack / release * 10.0 + max(0.0, gain + bass + treble - 6.0) * 2.0
    return max(0.0, min(100.0, -noise_floor * (1.0 - 1.0 / ratio) * 2.0) - penalty)

def control_dynamics(noise_floor, ratio, attack, release, gain, bass, treble):
    squash = 100.0 * (1.0 - 1.0 / ratio)
    penalty = abs(attack * 10.0 - release) / 10.0 + abs(gain - 3.0) * 2.0
    penalty += max(0.0, noise_floor + 45.0) * 1.5 + max(0.0, bass + treble - 4.0) * 2.0
    return max(0.0, min(100.0, 100.0 - abs(squash - 75.0) * 0.5 - penalty))

def analyze_tonal_balance(noise_floor, ratio, attack, release, gain, bass, treble):
    pumping = max(0.0, release / attack - 20.0) * 0.1 * ratio
    tilt = abs(bass - treble) * 5.0 + max(0.0, bass + treble - 6.0) * 3.0
    hiss = max(0.0, treble * 2.0 + noise_floor + 55.0)
    return max(0.0, 100.0 - tilt - hiss - pumping)

def rate_export_quality(noise_score, dynamics_score, tonal_score, noise_floor, ratio, attack, release, gain, bass, treble):
    weighted = 0.3 * noise_score + 0.4 * dynamics_score + 0.3 * tonal_score
    penalty = (gain + bass + treble) * 0.5 + max(0.0, noise_floor + 50.0) * 0.5
    penalty += max(0.0, ratio - 8.0) * 1.5 + max(0.0, attack + release - 200.0) * 0.05
    return round(max(0.0, min(100.0, weighted - penalty)))

def master(tracks):
    ratings = []
    for track in tracks:
        floor, ratio, atk, rel, gain, bass, treble = validate_track(track)
        ratings.append(rate_export_quality(estimate_noise_reduction(floor, ratio, atk, rel, gain, bass, treble), control_dynamics(floor, ratio, atk, rel, gain, bass, treble), analyze_tonal_balance(floor, ratio, atk, rel, gain, bass, treble), floor, ratio, atk, rel, gain, bass, treble))
    return ratings

def _clamp(value, low, high):
    return max(low, min(high, value))


def _validate_habitat(index, habitat):
    if len(habitat) != 7:
        raise ValueError("habitat {0} needs exactly 7 parameters, got {1}".format(index, len(habitat)))
    for position, parameter in enumerate(habitat):
        if not isinstance(parameter, (int, float)) or isinstance(parameter, bool):
            raise ValueError("habitat {0} parameter {1} is not numeric".format(index, position))


def animal_comfort(temperature, humidity, foliage, water, slope, barrier, proximity):
    climate = 100 - abs(temperature - 75) * 2 - abs(humidity - 60)
    shelter = min(foliage, 100) * 0.1 + min(water, 600) / 60.0 + min(barrier, 20) * 0.1
    stress = slope * 0.5 + proximity * 0.4
    return _clamp(climate + shelter - stress, 0.0, 100.0)


def escape_risk(temperature, humidity, foliage, water, slope, barrier, proximity):
    containment = 100 - barrier * 5 + slope * 0.8
    opportunity = foliage * 0.05 - water * 0.01 + proximity * 0.5
    discomfort = max(0, 80 - humidity) * 0.05 + max(0, temperature - 85) * 0.4
    return _clamp(containment + opportunity + discomfort, 0.0, 100.0)


def viewing_quality(temperature, humidity, foliage, water, slope, barrier, proximity):
    obstruction = foliage * 0.25 + barrier * 1.0 + proximity * 2.0
    vantage = water * 0.01 + slope * 0.3
    weather = max(0, humidity - 80) * 0.2 + max(0, temperature - 90) * 0.3
    return _clamp(100 - obstruction + vantage - weather, 0.0, 100.0)


def overall_viability(comfort, risk, viewing, temperature, humidity, foliage, water, slope, barrier, proximity):
    base = comfort * 0.5 + (100 - risk) * 0.3 + viewing * 0.2
    bonus = min(water, 500) / 50.0 + min(foliage, 80) * 0.05
    drift = abs(temperature - 75) * 0.5 + abs(humidity - 60) * 0.3 + slope * 0.2
    hazard = max(0, 10 - barrier) * 1.5 + max(0, proximity - 20) * 0.5
    return int(round(_clamp(base + bonus - drift - hazard, 0.0, 100.0)))


def assess(habitats):
    percentages = []
    for index, habitat in enumerate(habitats):
        _validate_habitat(index, habitat)
        temperature, humidity, foliage, water, slope, barrier, proximity = habitat
        comfort = animal_comfort(temperature, humidity, foliage, water, slope, barrier, proximity)
        risk = escape_risk(temperature, humidity, foliage, water, slope, barrier, proximity)
        viewing = viewing_quality(temperature, humidity, foliage, water, slope, barrier, proximity)
        percentages.append(overall_viability(comfort, risk, viewing, temperature, humidity, foliage, water, slope, barrier, proximity))
    return percentages


def format_report(habitats, percentages):
    lines = []
    for habitat, percentage in zip(habitats, percentages):
        lines.append("temp={0} hum={1} foliage={2} water={3} slope={4} " "barrier={5} proximity={6} -> {7}%".format(*habitat, percentage))
    return "\n".join(lines)


def main():
    habitats = [(75, 60, 80, 500, 10, 12, 5), (95, 25, 10, 50, 40, 4, 30)]
    print(format_report(habitats, assess(habitats)))


if __name__ == "__main__":
    main()

import math

PROPERTY_NAMES = ("magnification", "focal_step", "exposure", "led_intensity", "filter_band", "stage_x", "stage_y")


def validate_sample(position, sample):
    if len(sample) != len(PROPERTY_NAMES):
        raise ValueError("sample {} must carry exactly {} properties".format(position, len(PROPERTY_NAMES)))
    for name, value in zip(PROPERTY_NAMES, sample):
        if not isinstance(value, (int, float)):
            raise TypeError("sample {}: property {!r} must be numeric, got {!r}".format(position, name, value))


def image_contrast(magnification, focal_step, exposure, led_intensity, filter_band, stage_x, stage_y):
    drift = (abs(stage_x) + abs(stage_y)) * 0.05
    return magnification * 0.5 + led_intensity * 0.25 + exposure * 0.02 + filter_band * 0.01 - focal_step * 2 - drift


def photo_bleaching_risk(magnification, focal_step, exposure, led_intensity, filter_band, stage_x, stage_y):
    dose = led_intensity * exposure / (10.0 * filter_band) * focal_step
    return dose + magnification * 0.1 + (abs(stage_x) + abs(stage_y)) / 30.0


def scan_duration(magnification, focal_step, exposure, led_intensity, filter_band, stage_x, stage_y):
    travel = math.hypot(stage_x, stage_y) / 10.0
    return focal_step * exposure / 1000.0 + travel + magnification / 40.0 + led_intensity / 80.0 + filter_band / 400.0


def overall_efficiency(contrast, bleaching, duration, magnification, focal_step, exposure, led_intensity, filter_band, stage_x, stage_y):
    drift = (abs(stage_x) + abs(stage_y)) * 0.15
    raw = contrast * 1.6 - bleaching * 0.5 - duration + magnification * 0.2 + filter_band * 0.02 + exposure * 0.01 + led_intensity * 0.05 - focal_step * 0.5 - drift
    return int(round(max(0.0, min(100.0, raw))))


def optimize(samples):
    indices = []
    for position, sample in enumerate(samples, start=1):
        validate_sample(position, sample)
        mag, step, exposure, led, band, stage_x, stage_y = sample
        contrast = image_contrast(mag, step, exposure, led, band, stage_x, stage_y)
        bleaching = photo_bleaching_risk(mag, step, exposure, led, band, stage_x, stage_y)
        duration = scan_duration(mag, step, exposure, led, band, stage_x, stage_y)
        indices.append(overall_efficiency(contrast, bleaching, duration, mag, step, exposure, led, band, stage_x, stage_y))
    return indices


def main():
    samples = [(40, 1, 500, 80, 400, 10, 20), (100, 2, 200, 60, 500, -30, 45), (20, 1, 900, 95, 350, 0, 0)]
    qualities = optimize(samples)
    header = " ".join("{:>8.8}".format(name) for name in PROPERTY_NAMES)
    print("{:>3} | {} | {:>5}".format("#", header, "index"))
    for position, (sample, quality) in enumerate(zip(samples, qualities), start=1):
        print("{:>3} | {} | {:>5}".format(position, " ".join("{:>8g}".format(value) for value in sample), quality))


if __name__ == "__main__":
    main()

import math

def _wind_alignment(wind_direction):
    return 1.0 + 0.25 * math.cos(math.radians(wind_direction))

def spread_velocity(wind_speed, wind_direction, relative_humidity, dry_fuel_load, slope_incline, soil_dryness_index, ambient_temperature):
    return 0.45 * wind_speed * _wind_alignment(wind_direction) + 0.60 * dry_fuel_load + 0.12 * slope_incline + 0.01 * soil_dryness_index + 0.08 * ambient_temperature - 0.06 * relative_humidity

def flame_length(wind_speed, wind_direction, relative_humidity, dry_fuel_load, slope_incline, soil_dryness_index, ambient_temperature):
    return 0.30 * math.sqrt(max(0.0, dry_fuel_load * ambient_temperature)) + 0.05 * wind_speed * _wind_alignment(wind_direction) + 0.04 * slope_incline + 0.003 * soil_dryness_index - 0.02 * relative_humidity

def spotting_distance(wind_speed, wind_direction, relative_humidity, dry_fuel_load, slope_incline, soil_dryness_index, ambient_temperature):
    return 0.25 * wind_speed * _wind_alignment(wind_direction) * math.sqrt(max(0.0, dry_fuel_load)) + 0.05 * slope_incline + 0.01 * soil_dryness_index + 0.05 * ambient_temperature - 0.10 * relative_humidity

def danger_index(velocity, flame, spotting, wind_speed, wind_direction, relative_humidity, dry_fuel_load, slope_incline, soil_dryness_index, ambient_temperature):
    hazard = 1.5 * velocity + 2.0 * flame + 0.8 * spotting
    regional = 0.20 * wind_speed * _wind_alignment(wind_direction) + 0.40 * dry_fuel_load + 0.10 * slope_incline + 0.01 * soil_dryness_index + 0.13 * ambient_temperature - 0.15 * relative_humidity
    return round(min(100.0, max(0.0, hazard + regional)), 1)

def predict(regions):
    probabilities = []
    for region in regions:
        numbers = tuple(float(value) for value in region)
        velocity = spread_velocity(*numbers)
        flame = flame_length(*numbers)
        spotting = spotting_distance(*numbers)
        probabilities.append(danger_index(velocity, flame, spotting, *numbers))
    return probabilities

def main():
    regions = [(30, 90, 15, 8, 20, 400, 35), (5, 180, 70, 2, 3, 40, 14)]
    for position, probability in enumerate(predict(regions)):
        print(f"region {position}: severe warning probability {probability:g}")

if __name__ == "__main__":
    main()

import math

G = 9.81


def _validate_slide(flow_rate, max_rider_weight, friction, drop_angle, curve_radius, pool_depth, vertical_descent):
    smallest = min(flow_rate, max_rider_weight, friction, curve_radius, pool_depth, vertical_descent)
    if smallest <= 0:
        raise ValueError("every slide measurement must be positive")
    if not 0.0 < drop_angle < 90.0:
        raise ValueError("the steepest drop angle must be between 0 and 90 degrees")


def top_speed(flow_rate, max_rider_weight, friction, drop_angle, curve_radius, pool_depth, vertical_descent):
    slope = math.tan(math.radians(drop_angle))
    efficiency = max(1.0 - friction / slope, 0.05)
    free_fall = math.sqrt(2.0 * G * vertical_descent * efficiency)
    flow_boost = 1.0 + flow_rate / 100000.0
    load_boost = 1.0 + (max_rider_weight - 150.0) / 1500.0
    curve_drag = 1.0 - 0.5 / (curve_radius + 10.0)
    splash_drag = 1.0 - pool_depth / 1000.0
    return free_fall * flow_boost * load_boost * curve_drag * splash_drag


def max_g_force(flow_rate, max_rider_weight, friction, drop_angle, curve_radius, pool_depth, vertical_descent):
    speed = top_speed(flow_rate, max_rider_weight, friction, drop_angle, curve_radius, pool_depth, vertical_descent)
    lateral = speed**2 / (curve_radius * G)
    vertical = math.cos(math.radians(drop_angle)) + pool_depth / vertical_descent
    return math.sqrt(lateral**2 + vertical**2)


def safety_margin(flow_rate, max_rider_weight, friction, drop_angle, curve_radius, pool_depth, vertical_descent):
    speed = top_speed(flow_rate, max_rider_weight, friction, drop_angle, curve_radius, pool_depth, vertical_descent)
    depth_margin = pool_depth / (speed / 10.0)
    flow_margin = flow_rate / (max_rider_weight * 0.9)
    grip_margin = (friction + 0.2) * curve_radius / math.sin(math.radians(drop_angle))
    return min(depth_margin, flow_margin, grip_margin, vertical_descent / 10.0)


def thrill_rating(speed, g_force, margin, flow_rate, max_rider_weight, friction, drop_angle, curve_radius, pool_depth, vertical_descent):
    speed_points = min(speed / 40.0, 1.0) * 4.0
    g_points = min(g_force / 6.0, 1.0) * 3.0 * min(1.0, drop_angle / 45.0)
    drop_points = min(vertical_descent / 60.0, 1.0) * 3.0
    comfort = min(1.0, margin) * (1.0 - friction / 4.0) ** 0.25
    crowding = min(1.0, flow_rate / max_rider_weight, curve_radius / pool_depth)
    raw = (speed_points + g_points + drop_points) * comfort * crowding**0.05
    return min(10.0, round(raw * 2.0) / 2.0)


def evaluate(slides):
    scores = []
    for slide in slides:
        _validate_slide(*slide)
        speed = top_speed(*slide)
        g_force = max_g_force(*slide)
        margin = safety_margin(*slide)
        scores.append(thrill_rating(speed, g_force, margin, *slide))
    return scores


def format_report(slides, scores):
    lines = []
    for index, (slide, score) in enumerate(zip(slides, scores), start=1):
        lines.append("Slide {0}: descent {1} m, top speed {2:.1f} m/s, thrill {3}/10".format(index, slide[6], top_speed(*slide), score))
    return "\n".join(lines)


def main():
    slides = [(500, 200, 0.1, 60, 5, 4, 50), (300, 120, 0.25, 35, 12, 2, 20)]
    print(format_report(slides, evaluate(slides)))


if __name__ == "__main__":
    main()

def _validate_cabin(cabin):
    if len(cabin) != 7:
        raise ValueError("each cabin needs exactly seven numbers")
    if cabin[0] <= 0 or cabin[1] <= 0:
        raise ValueError("occupants and voyage duration must be positive")
    if any(value < 0 for value in cabin):
        raise ValueError("cabin values cannot be negative")


def estimate_food_consumption(occupants, days, dining_nights, excursion_days, beverage_tier, room_service_freq, loyalty_level):
    onboard = occupants * 1.5 + dining_nights * 0.4 + room_service_freq * 0.3
    ashore = occupants * 0.2 * excursion_days / days
    return onboard - ashore + beverage_tier * 0.1 + loyalty_level * 0.05


def estimate_water_usage(occupants, days, dining_nights, excursion_days, beverage_tier, room_service_freq, loyalty_level):
    litres = occupants * 20.0 + room_service_freq * 5.0 + beverage_tier * 3.0
    litres -= occupants * excursion_days / days
    return litres + dining_nights * 0.5 + loyalty_level * 0.2


def estimate_linen_turnover(occupants, days, dining_nights, excursion_days, beverage_tier, room_service_freq, loyalty_level):
    pieces = occupants * 0.8 + dining_nights * 0.5 + room_service_freq * 0.4
    pieces += excursion_days * 0.1 + beverage_tier * 0.05 + loyalty_level * 0.05
    return pieces / max(days / 7.0, 1.0) if days > 7 else pieces


def plan_cargo_weight(food_per_day, water_per_day, linen_per_day, occupants, days, dining_nights, excursion_days, beverage_tier, room_service_freq, loyalty_level):
    weight = food_per_day * days - (beverage_tier * 0.1 + loyalty_level * 0.05) * days
    weight += water_per_day * days * 0.05
    weight += linen_per_day * days * 0.3
    weight += beverage_tier * days * 0.4
    weight += occupants * excursion_days * 0.5
    weight += loyalty_level * occupants * 0.7
    weight += dining_nights * room_service_freq * 0.2
    return round(weight)


def format_manifest_row(index, occupants, days, excursion_days, loyalty_level, weight):
    return f"cabin {index}: {occupants} pax, {days} days, {excursion_days} ashore, club {loyalty_level} -> {weight} kg"


def provision(cabins):
    weights = []
    for cabin in cabins:
        _validate_cabin(cabin)
        occupants, days, dining, excursions, beverage, service, loyalty = cabin
        food_per_day = estimate_food_consumption(occupants, days, dining, excursions, beverage, service, loyalty)
        water_per_day = estimate_water_usage(occupants, days, dining, excursions, beverage, service, loyalty)
        linen_per_day = estimate_linen_turnover(occupants, days, dining, excursions, beverage, service, loyalty)
        weights.append(plan_cargo_weight(food_per_day, water_per_day, linen_per_day, occupants, days, dining, excursions, beverage, service, loyalty))
    return weights


def main():
    cabins = [(4, 7, 2, 3, 3, 1, 5), (2, 14, 5, 6, 1, 0, 2), (6, 3, 0, 1, 2, 4, 1)]
    for index, (cabin, weight) in enumerate(zip(cabins, provision(cabins)), start=1):
        print(format_manifest_row(index, cabin[0], cabin[1], cabin[3], cabin[6], weight))


