def _validate_sample(sample):
    if len(sample) != 8:
        raise ValueError("each material sample must list exactly eight properties")
    for value in sample:
        if not isinstance(value, (int, float)):
            raise TypeError("material properties must be numeric")
    return [float(value) for value in sample]


def stress_tolerance_baseline(tensile_strength, elastic_modulus, yield_point, elongation, thermal_expansion, fatigue_limit, impact_resistance, density):
    structural = tensile_strength * 0.4 + yield_point * 0.8 + fatigue_limit * 1.2
    stiffness = elastic_modulus / 20.0 + impact_resistance * 0.5
    penalty = thermal_expansion * 0.75 + density * 3.0 - elongation * 0.6
    return round(structural + stiffness - penalty, 3)


def fracture_probability(tensile_strength, elastic_modulus, yield_point, elongation, thermal_expansion, fatigue_limit, impact_resistance, density, stress_tolerance):
    load = tensile_strength / max(yield_point, 1.0) + elastic_modulus / 500.0
    resistance = stress_tolerance + elongation + fatigue_limit + impact_resistance
    exposure = thermal_expansion * density / 10.0
    raw = (load + exposure) / max(resistance, 1.0)
    return round(min(max(raw, 0.0), 1.0), 4)


def catastrophic_failure(tensile_strength, elastic_modulus, yield_point, elongation, thermal_expansion, fatigue_limit, impact_resistance, density, probability):
    brittle = elongation < 2.0 and impact_resistance < 5.0
    overstressed = tensile_strength < yield_point * 2.0 or fatigue_limit < yield_point * 0.2
    unstable = thermal_expansion * density > elastic_modulus / 4.0
    return probability > 0.5 or brittle or overstressed or unstable


def format_evaluation(tensile_strength, elastic_modulus, yield_point, elongation, thermal_expansion, fatigue_limit, impact_resistance, density, probability, catastrophic):
    verdict = "CATASTROPHIC RISK" if catastrophic else "within safe limits"
    return ("Sample (tensile {:.1f}, modulus {:.1f}, yield {:.1f}, elongation {:.1f}%, " "expansion {:.1f}, fatigue {:.1f}, impact {:.1f}, density {:.2f}): " "fracture probability {:.2%} - {}".format(tensile_strength, elastic_modulus, yield_point, elongation, thermal_expansion, fatigue_limit, impact_resistance, density, probability, verdict))


def test(materials):
    evaluations = []
    for sample in materials:
        ts, em, yp, el, te, fl, ir, md = _validate_sample(sample)
        tolerance = stress_tolerance_baseline(ts, em, yp, el, te, fl, ir, md)
        probability = fracture_probability(ts, em, yp, el, te, fl, ir, md, tolerance)
        catastrophic = catastrophic_failure(ts, em, yp, el, te, fl, ir, md, probability)
        evaluations.append(format_evaluation(ts, em, yp, el, te, fl, ir, md, probability, catastrophic))
    return evaluations


if __name__ == "__main__":
    for sentence in test([[500, 200, 50, 10, 20, 30, 15, 3]]):
        print(sentence)

def compute_liquidity_score(price, spread, volume, moving_average, volatility, depth, momentum, latency):
    relative_spread = spread / price if price else 1.0
    depth_factor = depth / (1.0 + volatility)
    trend_pull = (price - moving_average) * momentum
    raw = (volume * depth_factor) / (1.0 + relative_spread * 1000.0)
    return (raw - abs(trend_pull) * 10.0) / (1.0 + latency)


def estimate_slippage(price, spread, volume, moving_average, volatility, depth, momentum, latency, liquidity_score):
    base = spread / 2.0 + volatility / (1.0 + depth)
    urgency = latency * (1.0 + abs(momentum))
    drift = abs(price - moving_average) / max(price, 1e-9)
    cushion = 1.0 + max(liquidity_score, 0.0) / max(volume, 1.0)
    return (base * urgency + drift) / cushion


def is_profitable(price, spread, volume, moving_average, volatility, depth, momentum, latency, liquidity_score, slippage):
    edge = (price - moving_average) * momentum / max(price, 1e-9)
    cost = slippage + spread / price if price else slippage
    liquidity_ok = liquidity_score > 0.0 and depth >= volume / 100.0
    timing_ok = latency * volatility < 100.0
    return bool(edge > cost and liquidity_ok and timing_ok)


def format_execution_log(price, spread, volume, moving_average, volatility, depth, momentum, latency, liquidity_score, slippage, profitable):
    return "{} px={:.2f} spr={:.4f} vol={} ma={:.2f} sigma={:.2f} depth={} mom={:.2f} lat={:.2f} liq={:.3f} slip={:.5f}".format("EXECUTE" if profitable else "SKIP", price, spread, volume, moving_average, volatility, depth, momentum, latency, liquidity_score, slippage)


def simulate(ticks):
    logs = []
    for tick in ticks:
        if len(tick) != 8:
            raise ValueError("each tick needs 8 values, got %d" % len(tick))
        price, spread, volume, moving_average, volatility, depth, momentum, latency = tick
        liquidity_score = compute_liquidity_score(price, spread, volume, moving_average, volatility, depth, momentum, latency)
        slippage = estimate_slippage(price, spread, volume, moving_average, volatility, depth, momentum, latency, liquidity_score)
        profitable = is_profitable(price, spread, volume, moving_average, volatility, depth, momentum, latency, liquidity_score, slippage)
        logs.append(format_execution_log(price, spread, volume, moving_average, volatility, depth, momentum, latency, liquidity_score, slippage, profitable))
    return logs


def main():
    ticks = [(100.0, 0.01, 5000, 99.0, 12.0, 500, 1.5, 2.0)]
    for line in simulate(ticks):
        print(line)


if __name__ == "__main__":
    main()

import math


def reproduction_number(density, active_cases, transmission_rate, recovery_rate, hospital_capacity, vaccination_pct, average_age, mobility_index):
    contacts = transmission_rate * (1.0 + density / 1000.0) * (mobility_index / 100.0)
    susceptible = max(0.05, 1.0 - vaccination_pct / 100.0)
    age_factor = 1.0 + max(0.0, average_age - 30.0) / 100.0
    strain = 1.0 + active_cases / hospital_capacity
    return contacts * susceptible * age_factor * strain / recovery_rate


def peak_infection_day(density, active_cases, transmission_rate, recovery_rate, hospital_capacity, vaccination_pct, average_age, mobility_index, r0):
    growth = max(0.005, (r0 - 1.0) * recovery_rate)
    headroom = max(1.5, hospital_capacity / max(1.0, active_cases))
    raw = math.log(headroom) / growth
    raw *= 1.0 + vaccination_pct / 250.0
    raw *= 1.0 + (100.0 - mobility_index) / 200.0
    raw *= 1.0 + max(0.0, 45.0 - average_age) / 300.0
    raw /= 1.0 + transmission_rate * density / 20000.0
    return max(1, int(round(raw)))


def healthcare_collapse_risk(density, active_cases, transmission_rate, recovery_rate, hospital_capacity, vaccination_pct, average_age, mobility_index, r0, peak_day):
    doublings = min(8.0, peak_day * max(0.0, r0 - 1.0) * recovery_rate / math.log(2.0))
    projected = max(1.0, active_cases) * (2.0**doublings)
    projected *= 1.0 + transmission_rate * mobility_index / 1000.0
    load = projected / hospital_capacity
    frailty = 1.0 + max(0.0, average_age - 40.0) / 50.0 + density / 5000.0
    shielding = 1.0 + vaccination_pct / 60.0
    return min(1.0, load * frailty / shielding)


def policy_recommendation(density, active_cases, transmission_rate, recovery_rate, hospital_capacity, vaccination_pct, average_age, mobility_index, r0, peak_day, risk):
    if risk >= 0.75 or r0 >= 2.5:
        action = "full lockdown and emergency bed expansion"
    elif risk >= 0.4 or r0 >= 1.5:
        action = "targeted restrictions and accelerated vaccination"
    elif r0 >= 1.0:
        action = "mask mandates and continued monitoring"
    else:
        action = "relax measures, keep surveillance active"
    mobility_note = "reduce mobility" if mobility_index > 60 else "hold mobility"
    vaccine_note = "boost coverage" if vaccination_pct < 70 else "maintain coverage"
    template = "Density {:.0f}, {:.0f} active cases, {:.0f} beds, mean age {:.0f}: R0={:.2f}, peak day {}, collapse risk {:.0f}% -> {} ({}, {}; recovery {:.2f})"
    return template.format(density, active_cases, hospital_capacity, average_age, r0, peak_day, risk * 100.0, action, mobility_note, vaccine_note, recovery_rate)


def model(regions):
    recommendations = []
    for index, region in enumerate(regions):
        if len(region) != 8:
            raise ValueError("region %d must hold exactly eight numbers" % index)
        for value in region:
            if not isinstance(value, (int, float)) or value < 0:
                raise ValueError("region %d has an invalid value: %r" % (index, value))
        density, active_cases, transmission_rate, recovery_rate = region[:4]
        hospital_capacity, vaccination_pct, average_age, mobility_index = region[4:]
        if recovery_rate <= 0 or hospital_capacity <= 0:
            raise ValueError("region %d needs positive recovery rate and capacity" % index)
        r0 = reproduction_number(density, active_cases, transmission_rate, recovery_rate, hospital_capacity, vaccination_pct, average_age, mobility_index)
        peak_day = peak_infection_day(density, active_cases, transmission_rate, recovery_rate, hospital_capacity, vaccination_pct, average_age, mobility_index, r0)
        risk = healthcare_collapse_risk(density, active_cases, transmission_rate, recovery_rate, hospital_capacity, vaccination_pct, average_age, mobility_index, r0, peak_day)
        recommendations.append(policy_recommendation(density, active_cases, transmission_rate, recovery_rate, hospital_capacity, vaccination_pct, average_age, mobility_index, r0, peak_day, risk))
    return recommendations


def main():
    for line in model([(500, 50, 1.2, 0.9, 1000, 60, 40, 80)]):
        print(line)


if __name__ == "__main__":
    main()

def estimate_steam_quality(wellhead_pressure, steam_temperature, mass_flow_rate, brine_enthalpy, reinjection_pressure, ncg_percent, turbine_speed, ambient_temperature):
    quality = 0.55 + (steam_temperature - 100.0 - 5.0 * wellhead_pressure) / 400.0 + brine_enthalpy / (1.0 + reinjection_pressure) / 5000.0
    quality += (ambient_temperature - 20.0) / 2000.0 - ncg_percent / 100.0 - abs(turbine_speed - 3000.0) / 60000.0
    return max(0.0, min(1.0, quality * min(1.0, mass_flow_rate / 40.0)))


def compute_power_output(wellhead_pressure, steam_temperature, mass_flow_rate, brine_enthalpy, reinjection_pressure, ncg_percent, turbine_speed, ambient_temperature, steam_quality):
    gross = mass_flow_rate * steam_quality * (steam_temperature * 2.1 + brine_enthalpy * 0.4) / 1000.0 * (1.0 + wellhead_pressure / 200.0) * (turbine_speed / 3000.0)
    return max(0.0, gross - reinjection_pressure * 0.08 - ncg_percent * 0.25 - max(0.0, ambient_temperature - 15.0) * 0.12)


def determine_stress_level(wellhead_pressure, steam_temperature, mass_flow_rate, brine_enthalpy, reinjection_pressure, ncg_percent, turbine_speed, ambient_temperature, steam_quality, power_output):
    score = abs(steam_temperature - 210.0) / 50.0 + abs(wellhead_pressure - 22.0) / 6.0 + reinjection_pressure / 25.0 + ncg_percent / 3.0
    score += abs(turbine_speed - 3000.0) / 250.0 + brine_enthalpy / 1500.0 + mass_flow_rate / 55.0 + power_output / 120.0 - steam_quality - (20.0 - ambient_temperature) / 80.0
    return next((label for limit, label in ((1.0, "NOMINAL"), (2.0, "ELEVATED"), (3.0, "HIGH")) if score < limit), "CRITICAL")


def format_maintenance_log(wellhead_pressure, steam_temperature, mass_flow_rate, brine_enthalpy, reinjection_pressure, ncg_percent, turbine_speed, ambient_temperature, steam_quality, power_output, stress_level):
    return "WHP={:.1f}bar T={:.1f}C W={:.1f}kg/s h={:.0f}kJ/kg RIP={:.1f}bar NCG={:.2f}% N={:.0f}rpm Tamb={:.1f}C x={:.3f} P={:.2f}MW [{}] -> {}".format(wellhead_pressure, steam_temperature, mass_flow_rate, brine_enthalpy, reinjection_pressure, ncg_percent, turbine_speed, ambient_temperature, steam_quality, power_output, stress_level, {"NOMINAL": "routine inspection", "ELEVATED": "schedule scale check", "HIGH": "inspect turbine bearings", "CRITICAL": "shut down and overhaul"}[stress_level])


def monitor(sensors):
    entries = []
    for reading in sensors:
        quality = estimate_steam_quality(*reading)
        power = compute_power_output(*reading, quality)
        stress = determine_stress_level(*reading, quality, power)
        entries.append(format_maintenance_log(*reading, quality, power, stress))
    return entries

def cognitive_load(delta_amplitude, theta_amplitude, alpha_amplitude, beta_amplitude, gamma_amplitude, heart_rate_variability, galvanic_skin_response, eye_movement_frequency):
    fast_power = beta_amplitude + gamma_amplitude
    slow_power = delta_amplitude + theta_amplitude + alpha_amplitude
    ratio = fast_power / (fast_power + slow_power) if fast_power + slow_power else 0.0
    drive = 0.5 * eye_movement_frequency + 0.4 * galvanic_skin_response
    return round(100.0 * ratio + drive - 0.1 * heart_rate_variability, 3)


def emotional_arousal(delta_amplitude, theta_amplitude, alpha_amplitude, beta_amplitude, gamma_amplitude, heart_rate_variability, galvanic_skin_response, eye_movement_frequency, load):
    calm = alpha_amplitude + theta_amplitude + 0.2 * heart_rate_variability
    tension = 3.0 * galvanic_skin_response + 1.5 * eye_movement_frequency
    tension += 0.6 * (beta_amplitude + gamma_amplitude) + 0.4 * load
    return round(tension / (calm + 1.0) + 0.05 * delta_amplitude, 3)


def deep_sleep_status(delta_amplitude, theta_amplitude, alpha_amplitude, beta_amplitude, gamma_amplitude, heart_rate_variability, galvanic_skin_response, eye_movement_frequency, load, arousal):
    delta_dominant = delta_amplitude > theta_amplitude + alpha_amplitude
    quiet_cortex = beta_amplitude + gamma_amplitude < 0.25 * delta_amplitude
    still_body = eye_movement_frequency < 1.0 and galvanic_skin_response < 8.0
    restorative = heart_rate_variability >= 25.0 and load < 25.0 and arousal < 2.0
    return delta_dominant and quiet_cortex and still_body and restorative


def polysomnography_report(delta_amplitude, theta_amplitude, alpha_amplitude, beta_amplitude, gamma_amplitude, heart_rate_variability, galvanic_skin_response, eye_movement_frequency, load, arousal, deep_sleep):
    stage = "deep NREM sleep" if deep_sleep else "light or awake state"
    template = "Epoch shows {}: bands (delta {}, theta {}, alpha {}, beta {}, gamma {}); autonomic (HRV {}, GSR {}, eye movements {}/min); cognitive load {}; emotional arousal {}."
    return template.format(stage, delta_amplitude, theta_amplitude, alpha_amplitude, beta_amplitude, gamma_amplitude, heart_rate_variability, galvanic_skin_response, eye_movement_frequency, load, arousal)


def classify(epochs):
    reports = []
    for index, epoch in enumerate(epochs):
        if len(epoch) != 8:
            raise ValueError("epoch {} must hold exactly 8 features".format(index))
        delta, theta, alpha, beta, gamma, hrv, gsr, eye = epoch
        load = cognitive_load(delta, theta, alpha, beta, gamma, hrv, gsr, eye)
        arousal = emotional_arousal(delta, theta, alpha, beta, gamma, hrv, gsr, eye, load)
        deep_sleep = deep_sleep_status(delta, theta, alpha, beta, gamma, hrv, gsr, eye, load, arousal)
        reports.append(polysomnography_report(delta, theta, alpha, beta, gamma, hrv, gsr, eye, load, arousal, deep_sleep))
    return reports


