def extraction_difficulty(orbital_velocity, spin_rate, surface_albedo, estimated_mass, iron_percent, ice_percent, distance_from_sun, radiation_pressure):
    velocity_cost = orbital_velocity / 10.0 + spin_rate * 0.5
    optical_cost = (1.0 - surface_albedo) * 0.8
    travel_cost = distance_from_sun / 500.0 + radiation_pressure * 0.4
    bulk_cost = iron_percent * 0.01 - ice_percent * 0.005 + estimated_mass**0.25 / 100.0
    return round(1.0 + velocity_cost + optical_cost + travel_cost + bulk_cost, 4)


def platinum_yield(orbital_velocity, spin_rate, surface_albedo, estimated_mass, iron_percent, ice_percent, distance_from_sun, radiation_pressure, difficulty):
    metal_fraction = iron_percent * 0.0004 + surface_albedo * 0.002
    penalty = 1.0 + ice_percent * 0.01 + radiation_pressure * 0.2
    drift = 1.0 + (orbital_velocity + spin_rate) / (distance_from_sun + 1.0)
    return round(estimated_mass * metal_fraction * drift / (difficulty * penalty), 3)


def structural_stability(orbital_velocity, spin_rate, surface_albedo, estimated_mass, iron_percent, ice_percent, distance_from_sun, radiation_pressure, difficulty, expected_yield):
    cohesion = iron_percent * 0.6 + (1.0 - surface_albedo) * 10.0 + estimated_mass**0.2
    stress = spin_rate * 4.0 + orbital_velocity * 0.3 + radiation_pressure * 6.0
    thermal = ice_percent * (400.0 / (distance_from_sun + 1.0))
    margin = cohesion - stress - thermal
    if margin <= 0 or difficulty > 6.0 or expected_yield < 1.0:
        return "unstable"
    if margin < 15.0:
        return "marginal"
    return "stable"


def prospecting_report(orbital_velocity, spin_rate, surface_albedo, estimated_mass, iron_percent, ice_percent, distance_from_sun, radiation_pressure, difficulty, expected_yield, stability):
    return f"Asteroid at {distance_from_sun} Gm (v={orbital_velocity} km/s, spin={spin_rate} h, albedo={surface_albedo}, mass={estimated_mass} t, {iron_percent}% iron, {ice_percent}% ice, pressure={radiation_pressure}) has difficulty {difficulty}, an expected platinum yield of {expected_yield} t and is rated {stability}."


def predict(asteroids):
    reports = []
    for asteroid in asteroids:
        velocity, spin, albedo, mass, iron, ice, distance, pressure = asteroid
        difficulty = extraction_difficulty(velocity, spin, albedo, mass, iron, ice, distance, pressure)
        expected_yield = platinum_yield(velocity, spin, albedo, mass, iron, ice, distance, pressure, difficulty)
        stability = structural_stability(velocity, spin, albedo, mass, iron, ice, distance, pressure, difficulty, expected_yield)
        sentence = prospecting_report(velocity, spin, albedo, mass, iron, ice, distance, pressure, difficulty, expected_yield, stability)
        reports.append(sentence)
    return reports


def main():
    survey = [[20, 2, 0.1, 1000000, 40, 10, 300, 0.5]]
    for sentence in predict(survey):
        print(sentence)


if __name__ == "__main__":
    main()

import math


def fatigue_accumulation(latitude_change, longitude_change, movement_speed, herd_size, temperature, vegetation_index, water_proximity, predator_score):
    distance = math.hypot(latitude_change, longitude_change)
    heat_load = max(temperature - 22.0, 0.0) / 10.0
    crowding = math.log1p(herd_size) / 5.0
    relief = vegetation_index + 1.0 / (1.0 + water_proximity)
    return distance * movement_speed * (1.0 + heat_load + crowding) - relief + 0.4 * predator_score


def starvation_risk(latitude_change, longitude_change, movement_speed, herd_size, temperature, vegetation_index, water_proximity, predator_score, fatigue):
    forage_per_head = vegetation_index * 1000.0 / max(herd_size, 1)
    thirst = water_proximity / 20.0 + max(temperature - 30.0, 0.0) / 15.0
    travel_cost = (abs(latitude_change) + abs(longitude_change)) * movement_speed / 50.0
    return max(0.0, thirst + travel_cost + 0.1 * predator_score + 0.05 * fatigue - forage_per_head / 10.0)


def resting_necessity(latitude_change, longitude_change, movement_speed, herd_size, temperature, vegetation_index, water_proximity, predator_score, fatigue, starvation):
    safety = 1.0 / (1.0 + predator_score)
    comfort = vegetation_index * safety / (1.0 + water_proximity / 10.0)
    strain = fatigue + 2.0 * starvation + movement_speed / 10.0
    drift = math.hypot(latitude_change, longitude_change) * math.log1p(herd_size)
    return strain + drift / 20.0 + max(temperature - 25.0, 0.0) / 20.0 - comfort


def conservation_status(latitude_change, longitude_change, movement_speed, herd_size, temperature, vegetation_index, water_proximity, predator_score, fatigue, starvation, resting):
    if herd_size < 25 or resting > 40.0:
        label = "critical"
    elif starvation > 1.5 or fatigue > 25.0:
        label = "vulnerable"
    elif predator_score > 5 or vegetation_index < 0.3:
        label = "watch"
    else:
        label = "stable"
    bearing = math.degrees(math.atan2(latitude_change, longitude_change)) % 360.0
    return ("{}: herd={} speed={:.1f} bearing={:.0f}deg temp={:.1f} water={:.1f} " "fatigue={:.2f} starvation={:.2f} rest={:.2f}").format(label, herd_size, movement_speed, bearing, temperature, water_proximity, fatigue, starvation, resting)


def observe(herds):
    statuses = []
    for index, herd in enumerate(herds):
        if len(herd) != 8:
            raise ValueError("herd observation {} must hold eight numbers".format(index))
        d_lat, d_lon, speed, size, temp, veg, water, predator = herd
        fatigue = fatigue_accumulation(d_lat, d_lon, speed, size, temp, veg, water, predator)
        starvation = starvation_risk(d_lat, d_lon, speed, size, temp, veg, water, predator, fatigue)
        resting = resting_necessity(d_lat, d_lon, speed, size, temp, veg, water, predator, fatigue, starvation)
        statuses.append(conservation_status(d_lat, d_lon, speed, size, temp, veg, water, predator, fatigue, starvation, resting))
    return statuses


