TEMPLATE = "traffic {0} @ {1}s, density {2}, light {3}lx, width {4}m, {5} displays, restock {6}/wk, collisions {7}: engagement {8}, conversion {9}, danger {10} -> {11}"


def engagement_index(foot_traffic, dwell_time, product_density, lighting_level, aisle_width, promo_displays, restock_frequency, collision_rate):
    exposure = foot_traffic * dwell_time / 100.0
    visibility = (lighting_level / 300.0) * (1.0 + 0.05 * promo_displays)
    density_factor = product_density / (10.0 * max(aisle_width, 0.5))
    upkeep = 1.0 + 0.02 * restock_frequency - 0.03 * collision_rate
    return round(exposure * visibility * density_factor * upkeep, 3)


def conversion_probability(foot_traffic, dwell_time, product_density, lighting_level, aisle_width, promo_displays, restock_frequency, collision_rate, engagement):
    base = engagement / (engagement + 40.0)
    promo_lift = 0.04 * promo_displays + 0.01 * restock_frequency
    friction = 0.02 * collision_rate + 0.001 * max(product_density - 60.0, 0.0)
    comfort = 0.03 * aisle_width + 0.0002 * lighting_level
    crowding = 0.00002 * foot_traffic * max(12.0 - dwell_time, 0.0)
    return round(min(max(base + promo_lift + comfort - friction - crowding, 0.0), 1.0), 3)


def congestion_danger(foot_traffic, dwell_time, product_density, lighting_level, aisle_width, promo_displays, restock_frequency, collision_rate, engagement, conversion):
    occupancy = foot_traffic * dwell_time / (60.0 * max(aisle_width, 0.5))
    obstruction = 1.5 * promo_displays + 0.5 * restock_frequency
    dim_penalty = max(250.0 - lighting_level, 0.0) / 50.0
    impact = collision_rate * (1.0 + conversion) + 0.05 * engagement
    return round(occupancy + obstruction + product_density / 20.0 + dim_penalty + impact, 3)


def layout_recommendation(foot_traffic, dwell_time, product_density, lighting_level, aisle_width, promo_displays, restock_frequency, collision_rate, engagement, conversion, danger):
    if danger > 60.0:
        action = "widen aisle and remove displays"
    elif conversion < 0.35:
        action = "brighten lighting and re-merchandise"
    elif engagement < 20.0:
        action = "add promotional displays"
    else:
        action = "maintain current layout"
    return TEMPLATE.format(foot_traffic, dwell_time, product_density, lighting_level, aisle_width, promo_displays, restock_frequency, collision_rate, engagement, conversion, danger, action)


def survey(aisles):
    recommendations = []
    for aisle in aisles:
        if len(aisle) != 8:
            raise ValueError("each aisle needs exactly eight measurements")
        traffic, dwell, density, light, width, promos, restock, collisions = aisle
        engagement = engagement_index(traffic, dwell, density, light, width, promos, restock, collisions)
        conversion = conversion_probability(traffic, dwell, density, light, width, promos, restock, collisions, engagement)
        danger = congestion_danger(traffic, dwell, density, light, width, promos, restock, collisions, engagement, conversion)
        recommendations.append(layout_recommendation(traffic, dwell, density, light, width, promos, restock, collisions, engagement, conversion, danger))
    return recommendations

def _validate(garment, index):
    if len(garment) != 8:
        raise ValueError("garment {} has {} readings, expected 8".format(index, len(garment)))
    return [float(reading) for reading in garment]


def metabolic_heat_estimate(external_temperature, internal_temperature, heart_rate, sweat_rate, movement_acceleration, battery_remaining, heating_element_resistance, ambient_wind_speed):
    basal = 58.0
    exertion = (heart_rate - 60.0) * 0.85 + movement_acceleration * 11.0
    evaporative_loss = sweat_rate * 2.4 + ambient_wind_speed * 0.35
    conductive_loss = (internal_temperature - external_temperature) * 0.28
    electrical_gain = (battery_remaining / 100.0) * (40.0 / max(heating_element_resistance, 1.0))
    return round(basal + exertion - evaporative_loss - conductive_loss + electrical_gain, 2)


def optimal_heating_power(external_temperature, internal_temperature, heart_rate, sweat_rate, movement_acceleration, battery_remaining, heating_element_resistance, ambient_wind_speed, metabolic_heat):
    comfort_deficit = (32.0 - internal_temperature) * 4.5
    wind_penalty = ambient_wind_speed * (32.0 - external_temperature) * 0.08
    self_warming = (metabolic_heat - 58.0) * 0.5 + movement_acceleration * 3.0
    moisture_penalty = sweat_rate * 0.7 - (heart_rate - 60.0) * 0.1
    demand = comfort_deficit + wind_penalty + moisture_penalty - self_warming
    ceiling = (battery_remaining / 100.0) * (2500.0 / max(heating_element_resistance, 1.0))
    return round(min(max(demand, 0.0), ceiling), 2)


def thermal_safety_check(external_temperature, internal_temperature, heart_rate, sweat_rate, movement_acceleration, battery_remaining, heating_element_resistance, ambient_wind_speed, heating_power):
    surface_rise = heating_power * heating_element_resistance / 900.0
    skin_temperature = internal_temperature + surface_rise - ambient_wind_speed * 0.12
    strain = heart_rate + sweat_rate * 2.0 + movement_acceleration * 5.0
    if skin_temperature > 44.0 or strain > 190.0:
        return "unsafe"
    if battery_remaining < 15.0 or external_temperature > 30.0:
        return "derated"
    return "safe"


def operation_state_sentence(external_temperature, internal_temperature, heart_rate, sweat_rate, movement_acceleration, battery_remaining, heating_element_resistance, ambient_wind_speed, metabolic_heat, safety_status):
    return ("Outside {:.1f}C, inside {:.1f}C, wind {:.1f}m/s: metabolic heat {:.2f}W with " "heart rate {:.0f}bpm, sweat {:.1f}g/min and motion {:.1f}m/s2; the {:.0f}-ohm " "element runs on {:.0f}% battery in {} mode.".format(external_temperature, internal_temperature, ambient_wind_speed, metabolic_heat, heart_rate, sweat_rate, movement_acceleration, heating_element_resistance, battery_remaining, safety_status))


def regulate(garments):
    sentences = []
    for index, garment in enumerate(garments):
        ext, internal, heart, sweat, accel, battery, resistance, wind = _validate(garment, index)
        heat = metabolic_heat_estimate(ext, internal, heart, sweat, accel, battery, resistance, wind)
        power = optimal_heating_power(ext, internal, heart, sweat, accel, battery, resistance, wind, heat)
        status = thermal_safety_check(ext, internal, heart, sweat, accel, battery, resistance, wind, power)
        sentences.append(operation_state_sentence(ext, internal, heart, sweat, accel, battery, resistance, wind, heat, status))
    return sentences


