    pressure: float
    temperature: float
    humidity: float
    battery: float
    carbon_dioxide: float
    nitrogen: float


def build_reading(values):
    if len(values) != 7:
        raise ValueError("each reading needs exactly seven numbers")
    return SuitReading(oxygen=values[0], pressure=values[1], temperature=values[2], humidity=values[3], battery=values[4], carbon_dioxide=values[5], nitrogen=values[6])


def evaluate_environment(oxygen, pressure, temperature, humidity):
    danger = 0
    if pressure < 90 or temperature > 30:
        danger += 20
    if humidity > 80 and oxygen < 25:
        danger += 5
    return danger


def evaluate_system(oxygen, battery, carbon_dioxide, nitrogen):
    danger = 0
    if oxygen < 20 or carbon_dioxide > 5:
        danger += 10
    if battery < 15 or nitrogen < 70:
        danger += 5
    return danger


def classify(environment_danger, system_danger, threshold=15):
    if environment_danger + system_danger > threshold:
        return "critical"
    return "normal"


def simulate(readings):
    alerts = []
    for values in readings:
        reading = build_reading(values)
        environment_danger = evaluate_environment(reading.oxygen, reading.pressure, reading.temperature, reading.humidity)
        system_danger = evaluate_system(reading.oxygen, reading.battery, reading.carbon_dioxide, reading.nitrogen)
        alerts.append(classify(environment_danger, system_danger))
    return alerts


def parse_readings(text):
    rows = []
    for line in text.strip().splitlines():
        rows.append([float(part) for part in line.replace(",", " ").split()])
    return rows


def format_report(readings, alerts, label="suit"):
    lines = []
    for index, (values, alert) in enumerate(zip(readings, alerts), start=1):
        line = "{} {}: O2={:g} P={:g} T={:g} -> {}".format(label, index, values[0], values[1], values[2], alert.upper())
        lines.append(line)
    return "\n".join(lines)


