def all_ints(*values):
    return all(isinstance(value, int) and not isinstance(value, bool) for value in values)


def validate_record(age, grade_level, gender_code, sleep_score, allergy_severity, study_group, room_preference):
    if not all_ints(age, grade_level, gender_code, sleep_score, allergy_severity, study_group, room_preference):
        return False
    if not (0 < age < 120 and 1 <= grade_level <= 12):
        return False
    if gender_code not in (1, 2, 3):
        return False
    if not (0 <= sleep_score <= 10 and 0 <= allergy_severity <= 10):
        return False
    return study_group > 0 and room_preference in (1, 2)


def build_record(age, grade_level, gender_code, sleep_score, allergy_severity, study_group, room_preference):
    return dict(age=age, grade_level=grade_level, gender_code=gender_code, sleep_score=sleep_score, allergy_severity=allergy_severity, study_group=study_group, room_preference=room_preference)


def study_compatible(age_a, grade_a, group_a, age_b, grade_b, group_b):
    if abs(age_a - age_b) > 2:
        return False
    if grade_a == grade_b:
        return group_a == group_b
    return abs(grade_a - grade_b) == 1


def living_compatible(sleep_a, allergy_a, preference_a, sleep_b, allergy_b, preference_b):
    if abs(sleep_a - sleep_b) > 2:
        return False
    if max(allergy_a, allergy_b) > 8:
        return False
    return preference_a == preference_b == 2


def find_partner(record, records, own_index):
    for index, other in enumerate(records):
        if other is None or index == own_index:
            continue
        study_ok = study_compatible(record["age"], record["grade_level"], record["study_group"], other["age"], other["grade_level"], other["study_group"])
        living_ok = living_compatible(record["sleep_score"], record["allergy_severity"], record["room_preference"], other["sleep_score"], other["allergy_severity"], other["room_preference"])
        if study_ok and living_ok:
            return True
    return False


def assign(students):
    records = []
    categories = []
    for row in students:
        if not isinstance(row, (list, tuple)) or len(row) != 7:
            records.append(None)
            categories.append("invalid")
            continue
        age, grade, gender, sleep, allergy, group, preference = row
        if not validate_record(age, grade, gender, sleep, allergy, group, preference):
            records.append(None)
            categories.append("invalid")
            continue
        records.append(build_record(age, grade, gender, sleep, allergy, group, preference))
        categories.append("single")
    for index, record in enumerate(records):
        if record is None or record["allergy_severity"] > 8:
            continue
        if find_partner(record, records, index):
            categories[index] = "shared"
    return categories


def format_summary(total, single_count, shared_count, invalid_count):
    return "{} students: {} single, {} shared, {} invalid".format(total, single_count, shared_count, invalid_count)


def main():
    roster = [[15, 10, 1, 8, 9, 3, 2], [16, 10, 1, 7, 2, 3, 2], [15, 10, 1, 6, 1, 3, 2], [14, 9, 2, 4, 20, 1, 2]]
    categories = assign(roster)
    for row, category in zip(roster, categories):
        print(row, "->", category)
    print(format_summary(len(categories), categories.count("single"), categories.count("shared"), categories.count("invalid")))


if __name__ == "__main__":
    main()

from typing import List


class FlightProfile:
    def __init__(self, payload_weight, burner_power, envelope_volume, ambient_temperature, wind_speed, altitude_limit, fuel_capacity):
        self.payload_weight = payload_weight
        self.burner_power = burner_power
        self.envelope_volume = envelope_volume
        self.ambient_temperature = ambient_temperature
        self.wind_speed = wind_speed
        self.altitude_limit = altitude_limit
        self.fuel_capacity = fuel_capacity


def build_profile(values):
    if len(values) != 7:
        raise ValueError("each flight needs exactly seven values")
    if any(not isinstance(value, (int, float)) for value in values):
        raise ValueError("flight values must be numeric")
    return FlightProfile(payload_weight=values[0], burner_power=values[1], envelope_volume=values[2], ambient_temperature=values[3], wind_speed=values[4], altitude_limit=values[5], fuel_capacity=values[6])


def compute_lift_capacity(payload_weight, burner_power, envelope_volume, ambient_temperature):
    available_lift = envelope_volume * 0.2
    thermal_boost = burner_power / max(ambient_temperature, 1)
    return payload_weight <= available_lift and thermal_boost > 0


def evaluate_weather_resistance(ambient_temperature, wind_speed, altitude_limit):
    gust_load = ambient_temperature * wind_speed
    return altitude_limit > 0 and gust_load >= 0, gust_load


def plan(flights: List[list]) -> List[str]:
    outcomes = []
    for values in flights:
        profile = build_profile(values)
        lift_ok = compute_lift_capacity(payload_weight=profile.payload_weight, burner_power=profile.burner_power, envelope_volume=profile.envelope_volume, ambient_temperature=profile.ambient_temperature)
        altitude_ok, gust_load = evaluate_weather_resistance(ambient_temperature=profile.ambient_temperature, wind_speed=profile.wind_speed, altitude_limit=profile.altitude_limit)
        weather_ok = altitude_ok and profile.burner_power > gust_load
        fuel_ok = profile.fuel_capacity >= profile.altitude_limit / 10
        outcomes.append("feasible" if lift_ok and weather_ok and fuel_ok else "grounded")
    return outcomes


def format_report(flights, outcomes, title):
    lines = [title]
    for index, (values, outcome) in enumerate(zip(flights, outcomes), start=1):
        lines.append("flight {0}: payload={1} volume={2} wind={3} -> {4}".format(index, values[0], values[2], values[4], outcome))
    return lines


def main():
    flights = [[200, 5000, 1500, 20, 10, 5000, 1000], [400, 800, 1200, 25, 30, 9000, 200]]
    report = format_report(flights=flights, outcomes=plan(flights), title="Balloon flight plan")
    for line in report:
        print(line)


if __name__ == "__main__":
    main()

def validate_trick(trick, index):
    if len(trick) != 7:
        raise ValueError("trick {} must contain exactly seven factors, got {}".format(index, len(trick)))
    return [float(factor) for factor in trick]


def build_trick_record(prop_weight, setup_minutes, stage_position, lighting_cue, sound_volume, assistant_required, duration):
    return dict(prop_weight=prop_weight, setup_minutes=setup_minutes, stage_position=stage_position, lighting_cue=lighting_cue, sound_volume=sound_volume, assistant_required=bool(assistant_required), duration=duration)


def stage_readiness(prop_weight, setup_minutes, stage_position, lighting_cue, assistant_required):
    score = 100.0
    score -= prop_weight * 0.4
    score -= setup_minutes * 1.5
    score -= abs(stage_position - 3.0) * 2.0
    score -= lighting_cue * 0.5
    if prop_weight > 50 and not assistant_required:
        score -= 20.0
    return max(0.0, score)


def crew_coordination(lighting_cue, sound_volume, assistant_required, duration):
    warnings = []
    score = 100.0 - sound_volume * 0.3 - duration * 1.2
    if assistant_required:
        score += 5.0
    if sound_volume > 80:
        if lighting_cue > 0:
            score -= 5.0
        else:
            score -= 15.0
            warnings.append("loud cue has no matching lighting cue")
    return max(0.0, score), warnings


def format_report_row(index, prop_weight, stage_score, crew_score, readiness, warnings):
    note = "; ".join(warnings) if warnings else "ok"
    return "trick {:>2} | {:>6.1f}kg | stage {:>6.2f} | crew {:>6.2f} | score {:>6.2f} | {}".format(index, prop_weight, stage_score, crew_score, readiness, note)


def sequence(tricks):
    scores = []
    for index, trick in enumerate(tricks):
        factors = validate_trick(trick, index)
        record = build_trick_record(factors[0], factors[1], factors[2], factors[3], factors[4], factors[5], factors[6])
        stage_score = stage_readiness(record["prop_weight"], record["setup_minutes"], record["stage_position"], record["lighting_cue"], record["assistant_required"])
        crew_score, warnings = crew_coordination(record["lighting_cue"], record["sound_volume"], record["assistant_required"], record["duration"])
        readiness = round(stage_score * 0.6 + crew_score * 0.4, 2)
        print(format_report_row(index, record["prop_weight"], stage_score, crew_score, readiness, warnings))
        scores.append(readiness)
    return scores


if __name__ == "__main__":
    print(sequence([[60, 10, 3, 5, 85, 1, 15], [70, 4, 1, 0, 95, 0, 8]]))

CRITERIA_COUNT = 7


class Routine:
    def __init__(self, difficulty_rating, execution_precision, synchronization_level, maximum_height, transition_smoothness, flip_count, twist_count):
        self.difficulty_rating = difficulty_rating
        self.execution_precision = execution_precision
        self.synchronization_level = synchronization_level
        self.maximum_height = maximum_height
        self.transition_smoothness = transition_smoothness
        self.flip_count = flip_count
        self.twist_count = twist_count


def validate_criteria(criteria, expected_count, index):
    if len(criteria) != expected_count:
        raise ValueError("routine {} needs {} criteria, got {}".format(index, expected_count, len(criteria)))
    return [float(value) for value in criteria]


def evaluate_execution(difficulty_rating, execution_precision, synchronization_level, transition_smoothness):
    base = difficulty_rating * execution_precision
    adjusted = base + (transition_smoothness - 5.0) * 1.5
    return adjusted + synchronization_level * 0.5


def evaluate_difficulty(maximum_height, flip_count, twist_count):
    points = flip_count * 2.0 + twist_count * 3.0
    if maximum_height > 20:
        if flip_count >= 3:
            points += 5.0
        if twist_count >= 2:
            points += 4.0
    return points


def score(routines):
    totals = []
    for index, criteria in enumerate(routines):
        values = validate_criteria(criteria, CRITERIA_COUNT, index)
        routine = Routine(*values)
        execution_points = evaluate_execution(routine.difficulty_rating, routine.execution_precision, routine.synchronization_level, routine.transition_smoothness)
        difficulty_points = evaluate_difficulty(routine.maximum_height, routine.flip_count, routine.twist_count)
        totals.append(round(execution_points + difficulty_points, 2))
    return totals


def format_report(index, criteria, total):
    return "Routine {}: difficulty {:.0f}, height {:.0f} ft -> {:.2f} points".format(index + 1, criteria[0], criteria[3], total)


def main():
    routines = [[8, 9, 7, 25, 8, 3, 2], [6, 7, 9, 18, 4, 2, 1], [9, 8, 8, 22, 6, 4, 3]]
    for index, total in enumerate(score(routines)):
        print(format_report(index, routines[index], total))


if __name__ == "__main__":
    main()

def validate_drone(record):
    if len(record) != 7:
        raise ValueError("each drone needs exactly seven numbers, got %d" % len(record))
    for value in record:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError("drone telemetry values must be numbers: %r" % (value,))
    return record


def make_telemetry(drone_id, start_x, start_y, start_z, target_x, target_y, target_z):
    return dict(drone_id=drone_id, start_x=start_x, start_y=start_y, start_z=start_z, target_x=target_x, target_y=target_y, target_z=target_z)


def check_launch_clearance(drone_id, start_x, start_y, start_z):
    if drone_id <= 0:
        return False
    if abs(start_x) > 10000 or abs(start_y) > 10000:
        return False
    return start_z > 0


def check_airspace_restriction(start_x, start_y, start_z, target_x, target_y, target_z):
    dx, dy, dz = target_x - start_x, target_y - start_y, target_z - start_z
    distance = (dx * dx + dy * dy + dz * dz) ** 0.5
    return target_z > 400, distance


def format_flight_report(drone_id, status, distance, target_z):
    return "drone {}: {} ({:.1f} m to fly, ceiling {:.0f} m)".format(drone_id, status, distance, target_z)


def evaluate_drone(record):
    validate_drone(record)
    telemetry = make_telemetry(record[0], record[1], record[2], record[3], record[4], record[5], record[6])
    launch_ok = check_launch_clearance(telemetry["drone_id"], telemetry["start_x"], telemetry["start_y"], telemetry["start_z"])
    restricted, distance = check_airspace_restriction(telemetry["start_x"], telemetry["start_y"], telemetry["start_z"], telemetry["target_x"], telemetry["target_y"], telemetry["target_z"])
    status = "cleared" if launch_ok and not restricted else "restricted"
    return status, distance


def coordinate(drones):
    return [evaluate_drone(record)[0] for record in drones]


def main():
    fleet = [[1, 0, 0, 10, 50, 50, 100], [2, 5, 5, 0, 20, 20, 300], [3, -10, 40, 25, 400, 120, 650]]
    for record in fleet:
        status, distance = evaluate_drone(record)
        print(format_flight_report(record[0], status, distance, record[6]))


if __name__ == "__main__":
    main()

