SPEC_LABELS = ("engine_displacement", "curb_weight", "manufacture_year", "suspension_stiffness", "brake_diameter", "driver_experience_years", "weather_severity")
VINTAGE_CUTOFF = 1960


def build_profile(engine_displacement, curb_weight, manufacture_year, suspension_stiffness, brake_diameter, driver_experience_years, weather_severity):
    return dict(engine_displacement=float(engine_displacement), curb_weight=float(curb_weight), manufacture_year=int(manufacture_year), suspension_stiffness=float(suspension_stiffness), brake_diameter=float(brake_diameter), driver_experience_years=float(driver_experience_years), weather_severity=float(weather_severity))


def mechanical_advantage(engine_displacement, curb_weight, manufacture_year, suspension_stiffness):
    if curb_weight <= 0:
        raise ValueError("curb_weight must be positive")
    power_ratio = engine_displacement / curb_weight
    if manufacture_year < VINTAGE_CUTOFF:
        power_ratio += (VINTAGE_CUTOFF - manufacture_year) * 0.05
    stiffness_factor = 1.0 + (10.0 - suspension_stiffness) * 0.02
    return round(power_ratio * stiffness_factor, 3)


def environmental_penalty(brake_diameter, driver_experience_years, weather_severity):
    exposure = weather_severity * 1.5
    mitigation = min(exposure, driver_experience_years * 0.2)
    brake_relief = brake_diameter * 0.05
    return round(max(0.0, exposure - mitigation - brake_relief), 3)


def handicap(vehicles):
    scores = []
    for specs in vehicles:
        if len(specs) != len(SPEC_LABELS):
            raise ValueError("each vehicle needs these specs: " + ", ".join(SPEC_LABELS))
        profile = build_profile(specs[0], specs[1], specs[2], specs[3], specs[4], specs[5], specs[6])
        mechanical = mechanical_advantage(profile["engine_displacement"], profile["curb_weight"], profile["manufacture_year"], profile["suspension_stiffness"])
        environmental = environmental_penalty(profile["brake_diameter"], profile["driver_experience_years"], profile["weather_severity"])
        scores.append(round(mechanical + environmental, 3))
    return scores


def format_penalty_line(index, specs, penalty):
    return "#{0} {1} {2:.0f}cc/{3:.0f}kg -> {4:.3f}".format(index, specs[2], specs[0], specs[1], penalty)


def main():
    fleet = [[3000, 1500, 1955, 8, 12, 15, 6], [1600, 900, 1972, 6, 10, 2, 9]]
    penalties = handicap(fleet)
    for index, (specs, penalty) in enumerate(zip(fleet, penalties), start=1):
        print(format_penalty_line(index, specs, penalty))
    print("total handicap:", round(sum(penalties), 3))


if __name__ == "__main__":
    main()

from dataclasses import dataclass


@dataclass
class Bridge:
    span_distance: float
    ice_thickness: float
    snow_density: float
    ambient_temperature: float
    weight_load_limit: float
    anchor_depth: float
    rope_tension: float


def validate_measurements(span_distance, ice_thickness, snow_density, weight_load_limit, anchor_depth, rope_tension):
    measurements = dict(span_distance=span_distance, ice_thickness=ice_thickness, snow_density=snow_density, weight_load_limit=weight_load_limit, anchor_depth=anchor_depth, rope_tension=rope_tension)
    for name, value in measurements.items():
        if value <= 0:
            raise ValueError(f"{name.replace('_', ' ')} must be positive, got {value}")


def tensile_strength(span_distance, ice_thickness, snow_density, ambient_temperature, anchor_depth, rope_tension):
    margin = ice_thickness - span_distance / 5.0
    margin += max(0.0, (snow_density - 600.0) / 1000.0)
    if ambient_temperature < 0:
        margin += min(-ambient_temperature, 20.0) * 0.02
    holds = anchor_depth > 1.0 and rope_tension <= 20.0 * span_distance
    return margin, holds and margin >= 0.0


def thermal_degradation(weight_load_limit, anchor_depth, rope_tension, ambient_temperature, snow_density):
    loss = rope_tension / (anchor_depth * 10000.0)
    stable = True
    if ambient_temperature > 0:
        loss += ambient_temperature * weight_load_limit / snow_density
        stable = snow_density >= 900.0
    return loss, stable and loss <= 0.25


def combine_assessment(tensile_margin, tensile_ok, thermal_loss, thermal_ok):
    if tensile_ok and thermal_ok and tensile_margin - thermal_loss >= 0.0:
        return "safe"
    if tensile_ok or thermal_ok:
        return "caution"
    return "unsafe"


def format_report(index, determination, tensile_margin, thermal_loss):
    return f"bridge {index}: {determination} (margin {tensile_margin:.2f}, loss {thermal_loss:.3f})"


def evaluate(record):
    validate_measurements(record[0], record[1], record[2], record[4], record[5], record[6])
    bridge = Bridge(span_distance=record[0], ice_thickness=record[1], snow_density=record[2], ambient_temperature=record[3], weight_load_limit=record[4], anchor_depth=record[5], rope_tension=record[6])
    tensile_margin, tensile_ok = tensile_strength(bridge.span_distance, bridge.ice_thickness, bridge.snow_density, bridge.ambient_temperature, bridge.anchor_depth, bridge.rope_tension)
    thermal_loss, thermal_ok = thermal_degradation(bridge.weight_load_limit, bridge.anchor_depth, bridge.rope_tension, bridge.ambient_temperature, bridge.snow_density)
    determination = combine_assessment(tensile_margin, tensile_ok, thermal_loss, thermal_ok)
    return determination, tensile_margin, thermal_loss


def inspect(bridges):
    return [evaluate(record)[0] for record in bridges]


def main():
    bridges = [[12, 3, 800, -5, 500, 2, 150], [30, 2, 400, 6, 900, 0.5, 900]]
    print(inspect(bridges))
    for index, record in enumerate(bridges):
        determination, margin, loss = evaluate(record)
        print(format_report(index, determination, margin, loss))


if __name__ == "__main__":
    main()

HIGH_POROSITY = 7
PROPERTY_COUNT = 7


class BatchRecord:
    def __init__(self, clay_porosity, glaze_melting_point, ramp_rate, peak_temperature, hold_time, cooling_speed, internal_humidity):
        self.clay_porosity = clay_porosity
        self.glaze_melting_point = glaze_melting_point
        self.ramp_rate = ramp_rate
        self.peak_temperature = peak_temperature
        self.hold_time = hold_time
        self.cooling_speed = cooling_speed
        self.internal_humidity = internal_humidity


def validate_properties(values):
    if len(values) != PROPERTY_COUNT:
        raise ValueError("each batch needs exactly %d properties" % PROPERTY_COUNT)
    if values[2] <= 0 or values[5] <= 0:
        raise ValueError("ramp rate and cooling speed must be positive")
    return values


def thermal_shock_hold(clay_porosity, glaze_melting_point, ramp_rate, peak_temperature, hold_time):
    margin = max(glaze_melting_point - peak_temperature, 1)
    risk = ramp_rate / margin + clay_porosity / 10.0
    if clay_porosity > HIGH_POROSITY:
        hold_time = hold_time * 1.2
    if risk > 1.0:
        hold_time = hold_time + (risk - 1.0) * 10.0
    return hold_time


def firing_duration(peak_temperature, ramp_rate, hold_time, cooling_speed, internal_humidity):
    heating_minutes = peak_temperature / ramp_rate
    cooling_minutes = peak_temperature / cooling_speed
    moisture_minutes = internal_humidity * 0.25
    return heating_minutes + hold_time + cooling_minutes + moisture_minutes


def format_row(position, clay_porosity, peak_temperature, total_minutes):
    template = "batch {0}: porosity {1}, peak {2}C, total {3:.2f}min"
    return template.format(position, clay_porosity, peak_temperature, total_minutes)


def schedule(batches):
    totals = []
    for values in batches:
        record = BatchRecord(*validate_properties(values))
        adjusted_hold = thermal_shock_hold(record.clay_porosity, record.glaze_melting_point, record.ramp_rate, record.peak_temperature, record.hold_time)
        total = firing_duration(record.peak_temperature, record.ramp_rate, adjusted_hold, record.cooling_speed, record.internal_humidity)
        totals.append(round(total, 2))
    return totals


def main():
    batches = [[8, 1200, 100, 1200, 30, 10, 40], [4, 1280, 80, 1150, 45, 15, 12]]
    totals = schedule(batches)
    for position, values in enumerate(batches, start=1):
        print(format_row(position, values[0], values[3], totals[position - 1]))


if __name__ == "__main__":
    main()

