DENSE_FOOD_THRESHOLD = 7
DENSE_FOOD_PENALTY = 0.8


def validate_factors(
    position,
    factors,
):
    if len(factors) != 7:
        raise ValueError(
            "contestant {0} needs exactly 7 factors, got {1}".format(
                position,
                len(factors),
            )
