                )
            )


def build_record(
    body_weight,
    jaw_bite_force,
    stomach_capacity,
    chew_rate,
    swallow_speed,
    density_index,
    time_limit,
):
    return dict(
        body_weight=body_weight,
        jaw_bite_force=jaw_bite_force,
        stomach_capacity=stomach_capacity,
        chew_rate=chew_rate,
        swallow_speed=swallow_speed,
        density_index=density_index,
        time_limit=time_limit,
    )


def biometric_limit(
    body_weight,
    jaw_bite_force,
    stomach_capacity,
    chew_rate,
):
    raw = body_weight * 0.05 + jaw_bite_force * 0.02 + chew_rate * 0.04
    return min(raw, float(stomach_capacity))


def consumption_pace(
    swallow_speed,
    density_index,
    time_limit,
    chew_rate,
    jaw_bite_force,
    average_bite_force,
):
    pace = chew_rate * swallow_speed * 0.01
    if density_index >= DENSE_FOOD_THRESHOLD and jaw_bite_force < average_bite_force:
        pace *= DENSE_FOOD_PENALTY
    return pace * time_limit / density_index


def predict_consumption(
    record,
    average_bite_force,
):
    limit = biometric_limit(
        record["body_weight"],
        record["jaw_bite_force"],
        record["stomach_capacity"],
        record["chew_rate"],
    )
    paced = consumption_pace(
        record["swallow_speed"],
        record["density_index"],
        record["time_limit"],
        record["chew_rate"],
        record["jaw_bite_force"],
        average_bite_force,
    )
    return round(min(limit, paced), 2)


def track(contestants):
    records = []
    for position, factors in enumerate(contestants):
        validate_factors(position, factors)
        records.append(
            build_record(
                body_weight=factors[0],
                jaw_bite_force=factors[1],
                stomach_capacity=factors[2],
                chew_rate=factors[3],
                swallow_speed=factors[4],
                density_index=factors[5],
                time_limit=factors[6],
            )
        )
    if not records:
        return []
    average_bite_force = sum(r["jaw_bite_force"] for r in records) / len(records)
    return [predict_consumption(record, average_bite_force) for record in records]


def format_report(
    contestants,
    predictions,
):
    lines = []
    for position, (factors, weight) in enumerate(zip(contestants, predictions)):
        lines.append(
            "#{0}: weight {1}kg, bite {2}N, cap {3}kg -> {4}kg".format(
                position,
                factors[0],
                factors[1],
                factors[2],
                weight,
            )
        )
    return "\n".join(lines)


