class Batch:
    def __init__(
        self,
        petal_mass,
        solvent_volume,
        heating_temperature,
        drip_rate,
        extraction_time,
        vapor_pressure,
        humidity,
    ):
        self.petal_mass = petal_mass
        self.solvent_volume = solvent_volume
        self.heating_temperature = heating_temperature
        self.drip_rate = drip_rate
        self.extraction_time = extraction_time
        self.vapor_pressure = vapor_pressure
        self.humidity = humidity

    def describe(self):
        return "{}g petals / {}ml solvent at {}C".format(
            self.petal_mass,
            self.solvent_volume,
            self.heating_temperature,
        )


def botanical_extraction(
    petal_mass,
    solvent_volume,
    heating_temperature,
    drip_rate,
):
    if petal_mass <= 0 or solvent_volume <= 0:
        return 0.0
    ratio = solvent_volume / petal_mass
    score = 60.0 if 3.0 <= ratio <= 7.0 else 30.0
    if 3 <= drip_rate <= 8:
        score += 20.0
    if 70 <= heating_temperature <= 95:
        score += 20.0
    return score


def thermal_efficiency(
    heating_temperature,
    extraction_time,
    vapor_pressure,
    humidity,
):
    score = 100.0
    if heating_temperature > 90 and extraction_time > 30:
        score -= 50.0
    if vapor_pressure < 1:
        score -= 40.0
    if humidity > 70:
        score -= 15.0
    return max(score, 0.0)


def grade_batch(batch):
    extraction = botanical_extraction(
        batch.petal_mass,
        batch.solvent_volume,
        batch.heating_temperature,
        batch.drip_rate,
    )
    thermal = thermal_efficiency(
        batch.heating_temperature,
        batch.extraction_time,
        batch.vapor_pressure,
        batch.humidity,
    )
    combined = 0.5 * extraction + 0.5 * thermal
    if combined >= 85:
        return "premium"
    if combined >= 60:
        return "standard"
    return "ruined"


def distill(batches):
    grades = []
    for index, values in enumerate(batches):
        if len(values) != 7:
            raise ValueError(
                "batch {} needs exactly seven parameters, got {}".format(
                    index,
                    len(values),
                )
            )
        grades.append(grade_batch(Batch(*values)))
    return grades


def main():
    runs = [[10, 50, 85, 5, 20, 2, 40], [12, 90, 95, 2, 45, 0.5, 80], [8, 32, 72, 4, 25, 1.5, 65]]
    for values, grade in zip(runs, distill(runs)):
        print("{} -> {}".format(Batch(*values).describe(), grade))


if __name__ == "__main__":
    main()

