def score_athletic(swimmer_count, average_depth, formation_complexity, breath_hold):
    return formation_complexity * swimmer_count + average_depth * 2.0 + breath_hold * 0.5


def score_choreography(music_tempo, leg_extension, splash_penalty, breath_hold):
    score = music_tempo * 0.1 + (leg_extension / 180.0) * 20.0
    score -= splash_penalty * 3.0
    if breath_hold < 30:
        score -= (30 - breath_hold) * 0.5
    return score


def format_routine_line(index, swimmer_count, athletic, choreography, final_score):
    template = "Routine {0}: {1} swimmers | athletic {2:.2f} | choreography {3:.2f} | final {4:.2f}"
    return template.format(index, swimmer_count, athletic, choreography, final_score)


def evaluate(routines):
    scores = []
    for routine in routines:
        if len(routine) != 7:
            raise ValueError("each routine needs exactly seven values")
        record = make_routine_record(routine[0], routine[1], routine[2], routine[3], routine[4], routine[5], routine[6])
        athletic = score_athletic(record["swimmer_count"], record["average_depth"], record["formation_complexity"], record["breath_hold"])
        choreography = score_choreography(record["music_tempo"], record["leg_extension"], record["splash_penalty"], record["breath_hold"])
        scores.append(round(athletic + choreography, 2))
    return scores


def main():
    routines = [[8, 3, 9, 45, 120, 170, 2], [4, 2, 6, 25, 100, 140, 5]]
    finals = evaluate(routines)
    for index, routine in enumerate(routines, start=1):
        line = format_routine_line(index, routine[0], score_athletic(routine[0], routine[1], routine[2], routine[3]), score_choreography(routine[4], routine[5], routine[6], routine[3]), finals[index - 1])
        print(line)
    print("Final scores:", finals)


if __name__ == "__main__":
    main()

class HuntProfile:
    """Full description of a single raptor hunting attempt."""

    def __init__(self, wingspan, terminal_velocity, prey_mass, wind_resistance, canopy_density, hour, previous_hunts):
        self.wingspan = wingspan
        self.terminal_velocity = terminal_velocity
        self.prey_mass = prey_mass
        self.wind_resistance = wind_resistance
        self.canopy_density = canopy_density
        self.hour = hour
        self.previous_hunts = previous_hunts


def avian_strike_probability(wingspan, terminal_velocity, prey_mass, wind_resistance):
    chance = 0.95
    if prey_mass > wingspan / 2:
        chance *= 0.55
    if terminal_velocity <= wind_resistance * 2:
        chance *= 0.45
    return chance


def field_visibility_probability(canopy_density, hour, previous_hunts):
    chance = 0.9
    if canopy_density > 70 and abs(hour - 12) > 2:
        chance *= 0.4
    return min(1.0, chance + min(previous_hunts, 10) * 0.01)


def calculate(hunts):
    percentages = []
    for values in hunts:
        profile = HuntProfile(values[0], values[1], values[2], values[3], values[4], values[5], values[6])
        strike_chance = avian_strike_probability(profile.wingspan, profile.terminal_velocity, profile.prey_mass, profile.wind_resistance)
        visibility_chance = field_visibility_probability(profile.canopy_density, profile.hour, profile.previous_hunts)
        combined = strike_chance * visibility_chance
        percentages.append(round(max(0.0, min(1.0, combined)) * 100, 2))
    return percentages


if __name__ == "__main__":
    sample = [[100, 200, 30, 50, 40, 12, 5], [180, 90, 120, 60, 85, 19, 0]]
    print(calculate(sample))

