FACTOR_COUNT = 7


def make_race(
    hill_slope,
    cheese_weight,
    ground_dampness,
    sprint_speed,
    footwear_traction,
    rock_count,
    barrier_density,
):
    race = {"hill_slope": hill_slope, "cheese_weight": cheese_weight, "ground_dampness": ground_dampness, "sprint_speed": sprint_speed, "footwear_traction": footwear_traction, "rock_count": rock_count, "barrier_density": barrier_density}
    for name, value in race.items():
        if value < 0:
            raise ValueError("{} must be non-negative, got {!r}".format(name, value))
    if ground_dampness > 100:
        raise ValueError("ground_dampness is a percentage, got {!r}".format(ground_dampness))
    if footwear_traction == 0:
        raise ValueError("footwear_traction must be greater than zero")
    return race


def velocity_potential(
    hill_slope,
    cheese_weight,
    ground_dampness,
    sprint_speed,
):
    base_danger = hill_slope * sprint_speed
    wheel_load = 1.0 + cheese_weight / 10.0
    damp_drag = 1.0 - ground_dampness / 200.0
    return base_danger * wheel_load * damp_drag


def tumble_probability(
    ground_dampness,
    footwear_traction,
    rock_count,
    barrier_density,
):
    effective_grip = float(footwear_traction)
    slip_factor = 1.0
    if ground_dampness > 50:
        effective_grip = max(footwear_traction - (ground_dampness - 50) / 25.0, 0.5)
        slip_factor = 2.0
    crowd_risk = slip_factor * barrier_density / effective_grip
    return crowd_risk + 3.0 * rock_count


def risk_index(race):
    velocity = velocity_potential(
        race["hill_slope"],
        race["cheese_weight"],
        race["ground_dampness"],
        race["sprint_speed"],
    )
    tumble = tumble_probability(
        race["ground_dampness"],
        race["footwear_traction"],
        race["rock_count"],
        race["barrier_density"],
    )
    return round(velocity * 0.1 + tumble + race["cheese_weight"] * 0.5, 2)


def build_races(races):
    built = []
    for factors in races:
        if len(factors) != FACTOR_COUNT:
            raise ValueError("each race needs {} factors".format(FACTOR_COUNT))
        built.append(
            make_race(
                factors[0],
                factors[1],
                factors[2],
                factors[3],
                factors[4],
                factors[5],
                factors[6],
            )
        )
    return built


def predict(races):
    return [risk_index(race) for race in build_races(races)]


def format_race_report(
    position,
    race,
    risk,
):
    return "Race {}: slope={} damp={}% grip={} rocks={} -> risk {}".format(
        position,
        race["hill_slope"],
        race["ground_dampness"],
        race["footwear_traction"],
        race["rock_count"],
        risk,
    )


def main():
    factor_rows = [[30, 10, 60, 15, 4, 5, 80], [12, 25, 20, 9, 6, 0, 40]]
    risks = predict(factor_rows)
    for position, race in enumerate(build_races(factor_rows), start=1):
        print(
            format_race_report(
                position,
                race,
                risks[position - 1],
            )
        )
    print("risk indices:", risks)


if __name__ == "__main__":
