def make_design_record(
    starting_paper_size,
    paper_thickness_gauge,
    total_step_count,
    crease_overlap_density,
    curved_fold_count,
    wet_folding_required,
    structural_integrity_score,
):
    return dict(
        starting_paper_size=starting_paper_size,
        paper_thickness_gauge=paper_thickness_gauge,
        total_step_count=total_step_count,
        crease_overlap_density=crease_overlap_density,
        curved_fold_count=curved_fold_count,
        wet_folding_required=bool(wet_folding_required),
        structural_integrity_score=structural_integrity_score,
    )


def material_constraint_score(
    starting_paper_size,
    paper_thickness_gauge,
    total_step_count,
    crease_overlap_density,
):
    score = paper_thickness_gauge * 0.5 + total_step_count / 50.0
    if crease_overlap_density > 60 and paper_thickness_gauge > 1:
        score += 3.0
    elif crease_overlap_density > 40:
        score += 1.5
    if starting_paper_size < 10:
        score += 1.0
    return score


def geometric_complexity_score(
    total_step_count,
    curved_fold_count,
    wet_folding_required,
    structural_integrity_score,
):
    score = curved_fold_count * 0.3 + (10 - structural_integrity_score) * 0.2
    if wet_folding_required:
        score += 1.5
    forced_master = total_step_count > 100 or curved_fold_count > 10
    return score, forced_master


def finalize_tier(material_score, geometric_score, forced_master):
    if forced_master:
        return "master"
    combined = material_score + geometric_score
    if combined >= 6.0:
        return "master"
    if combined >= 3.0:
        return "intermediate"
    return "beginner"


def format_report_line(design_index, record, tier):
    return "design {0}: {1} steps, {2} curved folds, integrity {3} -> {4}".format(
        design_index,
        record["total_step_count"],
        record["curved_fold_count"],
        record["structural_integrity_score"],
        tier,
    )


def rate(designs):
    tiers = []
    for design in designs:
        if len(design) != 7:
            raise ValueError("each design needs exactly seven characteristics")
        record = make_design_record(*design)
        material_score = material_constraint_score(
            record["starting_paper_size"],
            record["paper_thickness_gauge"],
            record["total_step_count"],
            record["crease_overlap_density"],
        )
        geometric_score, forced_master = geometric_complexity_score(
            record["total_step_count"],
            record["curved_fold_count"],
            record["wet_folding_required"],
            record["structural_integrity_score"],
        )
        tiers.append(finalize_tier(material_score, geometric_score, forced_master))
    return tiers


def main():
    designs = [[15, 2, 150, 80, 15, 1, 9], [20, 1, 25, 20, 0, 0, 9], [12, 2, 60, 45, 4, 1, 6]]
    tiers = rate(designs)
    for index, design in enumerate(designs, start=1):
        print(format_report_line(index, make_design_record(*design), tiers[index - 1]))
    print(tiers)


if __name__ == "__main__":
