import math
from collections import namedtuple

GRAVITY = 9.81

Flight = namedtuple("Flight", "distance apex air_time stability")
Absorption = namedtuple("Absorption", "drop_rate margin tip_risk")


class JumpProfile:
    def __init__(self, incline_angle, approach_velocity, truck_weight, tire_pressure, suspension_travel, cog_height, drag_resistance):
        self.incline_angle = incline_angle
        self.approach_velocity = approach_velocity
        self.truck_weight = truck_weight
        self.tire_pressure = tire_pressure
        self.suspension_travel = suspension_travel
        self.cog_height = cog_height
        self.drag_resistance = drag_resistance


def compute_flight(incline_angle, approach_velocity, truck_weight, tire_pressure):
    radians = math.radians(incline_angle)
    vertical = approach_velocity * math.sin(radians)
    horizontal = approach_velocity * math.cos(radians)
    air_time = 2 * vertical / GRAVITY
    return Flight(distance=horizontal * air_time, apex=vertical ** 2 / (2 * GRAVITY), air_time=air_time, stability=(tire_pressure / 30.0) / max(truck_weight / 5000.0, 0.1))


def compute_absorption(suspension_travel, cog_height, drag_resistance, truck_weight, apex_height):
    free_fall = math.sqrt(2 * GRAVITY * max(apex_height, 0.0))
    drop_rate = free_fall * truck_weight / (truck_weight + drag_resistance * 100.0)
    return Absorption(drop_rate=drop_rate, margin=suspension_travel - drop_rate * cog_height / 10.0, tip_risk=cog_height / max(suspension_travel, 0.1))


def classify(flight, absorption):
    if absorption.margin < 0 or absorption.tip_risk > 1.5:
        return "crash"
    if flight.air_time > 6.0 and flight.stability < 0.5:
        return "crash"
    if absorption.margin < 2.0 or flight.stability < 0.8:
        return "rough"
    return "safe"


def evaluate(jumps):
    outcomes = []
    for jump in jumps:
        profile = JumpProfile(jump[0], jump[1], jump[2], jump[3], jump[4], jump[5], jump[6])
        flight = compute_flight(profile.incline_angle, profile.approach_velocity, profile.truck_weight, profile.tire_pressure)
        absorption = compute_absorption(profile.suspension_travel, profile.cog_height, profile.drag_resistance, profile.truck_weight, flight.apex)
        outcomes.append(classify(flight, absorption))
    return outcomes


def main():
    jumps = [[30, 80, 5000, 30, 20, 5, 10], [45, 120, 9000, 20, 8, 9, 2]]
    for jump, outcome in zip(jumps, evaluate(jumps)):
        print("angle={0} velocity={1} -> {2}".format(jump[0], jump[1], outcome))


if __name__ == "__main__":
    main()

IDEAL_RATIO_RANGE = (15.0, 25.0)
CRITICAL_SLENDERNESS = 1.5
METRIC_NAMES = ("total sand volume", "water mixture ratio", "foundation base width", "central tower height", "wall compaction force", "high tide distance", "seashell reinforcement count")


def check_metrics(index, metrics):
    if len(metrics) != len(METRIC_NAMES):
        raise ValueError("castle {} needs {} metrics, got {}".format(index, len(METRIC_NAMES), len(metrics)))
    for name, value in zip(METRIC_NAMES, metrics):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("castle {}: {} must be numeric".format(index, name))
    if metrics[2] <= 0:
        raise ValueError("castle {}: foundation base width must be positive".format(index))


def build_record(sand_volume, water_ratio, base_width, tower_height, compaction_force, tide_distance, shell_count):
    return dict(sand_volume=float(sand_volume), water_ratio=float(water_ratio), base_width=float(base_width), tower_height=float(tower_height), compaction_force=float(compaction_force), tide_distance=float(tide_distance), shell_count=float(shell_count))


def gravitational_hours(sand_volume, water_ratio, base_width, tower_height):
    hours = sand_volume * 0.05 + base_width * 2.0
    low, high = IDEAL_RATIO_RANGE
    if water_ratio < low or water_ratio > high:
        hours *= 0.1
    if tower_height / base_width > CRITICAL_SLENDERNESS:
        hours *= 0.2
    return hours


def tidal_hours(compaction_force, tide_distance, shell_count):
    if tide_distance < 10.0:
        return 0.0
    exposure = min(tide_distance / 40.0, 1.0)
    return (compaction_force * 0.1 + shell_count * 0.4) * exposure


def format_report(index, water_ratio, tide_distance, shell_count, standing_hours):
    return "castle {}: ratio={:.1f} tide={:.1f}m shells={:.0f} -> {:.2f} hours".format(index, water_ratio, tide_distance, shell_count, standing_hours)


def validate(castles):
    standing = []
    for index, metrics in enumerate(castles):
        check_metrics(index, metrics)
        record = build_record(metrics[0], metrics[1], metrics[2], metrics[3], metrics[4], metrics[5], metrics[6])
        gravity = gravitational_hours(record["sand_volume"], record["water_ratio"], record["base_width"], record["tower_height"])
        erosion = tidal_hours(record["compaction_force"], record["tide_distance"], record["shell_count"])
        standing.append(round(gravity + erosion, 2))
    return standing


def main():
    castles = [[500, 20, 10, 5, 100, 5, 50], [1200, 22, 20, 12, 180, 35, 140], [800, 40, 12, 6, 150, 25, 60]]
    hours = validate(castles)
    for index, (metrics, standing_hours) in enumerate(zip(castles, hours)):
        print(format_report(index, metrics[1], metrics[5], metrics[6], standing_hours))
    print("total standing hours:", round(sum(hours), 2))


if __name__ == "__main__":
    main()

OPTIMAL_TEMPERATURE = 24.0
FACTOR_NAMES = ("hives", "workers", "floral_density", "sunny_days", "temperature", "rainfall", "mite_level")


def build_profile(hives, workers, floral_density, sunny_days, temperature, rainfall, mite_level):
    return dict(hives=max(int(hives), 0), workers=max(workers, 0.0), floral_density=max(floral_density, 0.0), sunny_days=max(sunny_days, 0.0), temperature=temperature, rainfall=max(rainfall, 0.0), mite_level=max(mite_level, 0.0))


def validate_factors(factors, expected_length, index):
    if len(factors) != expected_length:
        raise ValueError("apiary {0} needs {1} factors, got {2}".format(index, expected_length, len(factors)))
    return [float(value) for value in factors]


def colony_health(hives, workers, floral_density, sunny_days, mite_level):
    per_hive = workers / hives if hives else 0.0
    strength = min(max(per_hive / 900.0, 0.2), 1.3)
    forage = 1.0 + floral_density / 400.0
    weather = 1.0 + 0.01 * sunny_days
    health = strength * forage * weather
    if mite_level >= 3.0:
        health *= 0.35
    else:
        health *= 1.0 - 0.08 * mite_level
    return max(health, 0.05)


def nectar_flow(workers, floral_density, sunny_days, temperature, rainfall):
    base = workers * floral_density / 100000.0
    sun_boost = 1.0 + 0.02 * sunny_days
    temp_factor = max(1.0 - abs(temperature - OPTIMAL_TEMPERATURE) / 40.0, 0.1)
    rain_penalty = 1.0 if rainfall <= 12.0 else max(1.0 - (rainfall - 12.0) * 0.05, 0.2)
    return base * sun_boost * temp_factor * rain_penalty


def estimate(apiaries):
    volumes = []
    for index, factors in enumerate(apiaries):
        profile = build_profile(*validate_factors(factors, len(FACTOR_NAMES), index))
        health = colony_health(profile["hives"], profile["workers"], profile["floral_density"], profile["sunny_days"], profile["mite_level"])
        flow = nectar_flow(profile["workers"], profile["floral_density"], profile["sunny_days"], profile["temperature"], profile["rainfall"])
        volumes.append(round(flow * health, 2))
    return volumes


def format_report(apiaries, volumes, unit):
    lines = []
    for index, (factors, volume) in enumerate(zip(apiaries, volumes), start=1):
        described = ", ".join("{0}={1:g}".format(name, value) for name, value in zip(FACTOR_NAMES, factors))
        lines.append("Apiary {0} [{1}] -> {2:.2f} {3}".format(index, described, volume, unit))
    return "\n".join(lines)


def main():
    apiaries = [[50, 40000, 80, 10, 25, 5, 2], [12, 18000, 45, 3, 31, 22, 4], [80, 62000, 95, 18, 23, 9, 0]]
    print(format_report(apiaries, estimate(apiaries), "liters"))


if __name__ == "__main__":
    main()

RING_REFERENCE_DIAMETER = 4.55
MINIMUM_ENGAGEMENT = 8.0


class SumoMatch:
    def __init__(self, first_weight, first_height, first_tier, second_weight, second_height, second_tier, ring_diameter):
        self.first_weight = first_weight
        self.first_height = first_height
        self.first_tier = first_tier
        self.second_weight = second_weight
        self.second_height = second_height
        self.second_tier = second_tier
        self.ring_diameter = ring_diameter


def validate_wrestler(weight, height, tier, side):
    if weight <= 0 or height <= 0:
        raise ValueError(f"{side} wrestler needs positive weight and height")
    if tier < 1:
        raise ValueError(f"{side} wrestler tier must be at least 1")


def leverage_advantage(first_weight, first_height, second_weight, second_height):
    weight_gap = abs(first_weight - second_weight)
    height_gap = abs(first_height - second_height)
    grinding_time = 45.0 - (0.35 * weight_gap) - (0.8 * height_gap)
    return max(MINIMUM_ENGAGEMENT, grinding_time)


def tactical_pacing(first_tier, second_tier, ring_diameter):
    if ring_diameter <= 0:
        raise ValueError("clay ring diameter must be positive")
    probing_time = 12.0 + 6.0 * first_tier * second_tier
    crowding_factor = min(1.0, ring_diameter / RING_REFERENCE_DIAMETER)
    return probing_time * crowding_factor


def forecast_match(match):
    validate_wrestler(match.first_weight, match.first_height, match.first_tier, "first")
    validate_wrestler(match.second_weight, match.second_height, match.second_tier, "second")
    grappling = leverage_advantage(match.first_weight, match.first_height, match.second_weight, match.second_height)
    pacing = tactical_pacing(match.first_tier, match.second_tier, match.ring_diameter)
    return int(round(grappling + pacing))


def predict(matches):
    predictions = []
    for row in matches:
        if len(row) != 7:
            raise ValueError("each matchup needs exactly seven attributes")
        match = SumoMatch(row[0], row[1], row[2], row[3], row[4], row[5], row[6])
        predictions.append(forecast_match(match))
    return predictions


def format_report(matches, predictions):
    lines = []
