        lines.append(f"{row[0]}kg/{row[1]}cm (tier {row[2]}) vs " f"{row[3]}kg/{row[4]}cm (tier {row[5]}) " f"in a {row[6]}m ring -> {seconds}s")
    return "\n".join(lines)


