def jacket_yardage(shoulder_width, chest_circumference, waist_taper, arm_length, neck_girth, torso_length, bicep_circumference, posture_score):
    body = (shoulder_width * 2.0 + chest_circumference * 1.4 + waist_taper * 0.8) / 36.0
    sleeves = (arm_length * 2.0 + bicep_circumference * 1.6) / 36.0
    collar = (neck_girth * 0.9 + torso_length * 1.1) / 36.0
    return round(body + sleeves + collar + (10.0 - posture_score) * 0.05, 3)


def shirt_yardage(shoulder_width, chest_circumference, waist_taper, arm_length, neck_girth, torso_length, bicep_circumference, posture_score):
    panels = (chest_circumference * 1.2 + waist_taper * 0.6 + torso_length * 1.3) / 36.0
    sleeves = (arm_length * 1.8 + bicep_circumference * 1.2) / 36.0
    yoke = (shoulder_width * 1.1 + neck_girth * 1.4) / 36.0
    return round(panels + sleeves + yoke + (10.0 - posture_score) * 0.02, 3)


def fit_difficulty(shoulder_width, chest_circumference, waist_taper, arm_length, neck_girth, torso_length, bicep_circumference, posture_score):
    drop = abs(chest_circumference - waist_taper) / 6.0
    sleeve_balance = abs(arm_length * 2.0 - torso_length * 1.5) / 8.0
    girth_ratio = (bicep_circumference * 2.0 + neck_girth) / shoulder_width
    return round(drop + sleeve_balance + girth_ratio + (10.0 - posture_score) * 0.4, 2)


def labor_hours(shoulder_width, chest_circumference, waist_taper, arm_length, neck_girth, torso_length, bicep_circumference, posture_score):
    jacket = jacket_yardage(shoulder_width, chest_circumference, waist_taper, arm_length, neck_girth, torso_length, bicep_circumference, posture_score)
    shirt = shirt_yardage(shoulder_width, chest_circumference, waist_taper, arm_length, neck_girth, torso_length, bicep_circumference, posture_score)
    difficulty = fit_difficulty(shoulder_width, chest_circumference, waist_taper, arm_length, neck_girth, torso_length, bicep_circumference, posture_score)
    return round(jacket * 4.5 + shirt * 3.0 + difficulty * 1.75, 2)


def measure(clients):
    total = 0.0
    for client in clients:
        if fit_difficulty(*client) < MAX_DIFFICULTY:
            total += labor_hours(*client)
    return round(total, 2)


def parse_clients(text):
    clients = []
    for line in text.strip().splitlines():
        fields = [float(value) for value in line.split(",")]
        if len(fields) != 8:
