def judge(pours):
    best = None
    for index, attempt in enumerate(pours):
        if len(attempt) != 8:
            raise ValueError("attempt %d needs 8 metrics, got %d" % (index, len(attempt)))
        metrics = [float(value) for value in attempt]
        score = final_score(visual_appeal(*metrics), technical_penalty(*metrics), milk_degradation_speed(*metrics), taste_preservation(*metrics))
        if best is None or score > best:
            best = score
    return best


