def _clamp(value, low, high):
    return max(low, min(high, value))


def _thermal_match(melting_point, application_temperature):
    return _clamp(1.0 - abs(melting_point - application_temperature) / 40.0, 0.0, 1.0)


def dune_glide_velocity(paraffin_concentration, beeswax_ratio, fluorocarbon_additive, melting_point, application_temperature, sand_friction, base_porosity, cure_time):
    slickness = 0.55 * paraffin_concentration + 0.85 * fluorocarbon_additive
    slickness += 0.15 * base_porosity
    slickness -= 0.40 * sand_friction + 0.10 * beeswax_ratio
    cure_factor = min(1.0, cure_time / 6.0)
    fit = _thermal_match(melting_point, application_temperature)
    return _clamp(slickness * fit * cure_factor * 90.0, 0.0, 90.0)


def layer_durability(paraffin_concentration, beeswax_ratio, fluorocarbon_additive, melting_point, application_temperature, sand_friction, base_porosity, cure_time):
    bonding = 0.45 * beeswax_ratio + 0.25 * paraffin_concentration + 0.10 * fluorocarbon_additive
    anchoring = 0.20 * base_porosity + 0.25 * min(1.0, cure_time / 8.0)
    hardness = 0.15 * _clamp((melting_point - application_temperature) / 30.0, 0.0, 1.0)
    return _clamp(bonding + anchoring + hardness - 0.30 * sand_friction, 0.0, 1.0)


def sand_stickiness_prevention(paraffin_concentration, beeswax_ratio, fluorocarbon_additive, melting_point, application_temperature, sand_friction, base_porosity, cure_time):
    repellency = 0.50 * fluorocarbon_additive + 0.20 * paraffin_concentration
    smoothness = 0.20 * (1.0 - base_porosity) + 0.20 * min(1.0, cure_time / 5.0)
    tackiness = 0.35 * beeswax_ratio * (1.0 - _thermal_match(melting_point, application_temperature))
    return _clamp(repellency + smoothness - tackiness - 0.15 * sand_friction, 0.0, 1.0)


def environmental_biodegradability(paraffin_concentration, beeswax_ratio, fluorocarbon_additive, melting_point, application_temperature, sand_friction, base_porosity, cure_time):
    natural = 0.65 * beeswax_ratio + 0.20 * paraffin_concentration
    residue = 0.10 * base_porosity * sand_friction + 0.05 * min(1.0, cure_time / 10.0)
    volatility = 0.05 * _thermal_match(melting_point, application_temperature)
    return _clamp(natural + volatility - 0.90 * fluorocarbon_additive - residue, 0.0, 1.0)


