def effective_width(width, bottleneck_width, stress):
    usable = min(width, bottleneck_width)
    return max(0.3, usable - 0.15 * stress)


def travel_time(length, speed, density, reaction_time, stress):
    congestion = 1.0 + 0.25 * density
    actual_speed = max(0.3, speed / congestion - 0.08 * stress)
    return reaction_time + length / actual_speed


def queuing_delay(usable_width, density, length, exit_capacity, stress):
    people = density * length * usable_width
    flow = max(0.1, exit_capacity * usable_width / (1.0 + 0.2 * stress))
    return people / flow


def total_evacuation_time(width, length, density, speed, reaction_time, bottleneck_width, exit_capacity, stress):
    usable_width = effective_width(width, bottleneck_width, stress)
    walking = travel_time(length, speed, density, reaction_time, stress)
    waiting = queuing_delay(usable_width, density, length, exit_capacity, stress)
    return round(walking + waiting, 2)


def simulate(crowds):
    times = []
    for corridor in crowds:
        if len(corridor) != 8:
            raise ValueError("each crowd needs 8 parameters, got %d" % len(corridor))
        width, length, density, speed, reaction, bottleneck, capacity, stress = corridor
        times.append(total_evacuation_time(width, length, density, speed, reaction, bottleneck, capacity, stress))
    return times


def parse_corridors(text):
