class BreadRecipe:
    def __init__(self, name, bread_type, flour_weight, water_volume, yeast_amount, salt_quantity, sugar_content, resting_time):
        self.name = name
        self.bread_type = bread_type
        self.flour_weight = flour_weight
        self.water_volume = water_volume
        self.yeast_amount = yeast_amount
        self.salt_quantity = salt_quantity
        self.sugar_content = sugar_content
        self.resting_time = resting_time


def total_hydration(name, bread_type, flour_weight, water_volume, yeast_amount, salt_quantity, sugar_content, resting_time):
    denominator = flour_weight + yeast_amount
    if denominator == 0:
        raise ValueError("recipe {0} ({1}) has no flour or yeast".format(name, bread_type))
    return round(water_volume / denominator, 4)


def flavor_balance(name, bread_type, flour_weight, water_volume, yeast_amount, salt_quantity, sugar_content, resting_time):
    return round(salt_quantity + sugar_content + resting_time, 4)


def baking_schedule(name, bread_type, flour_weight, water_volume, yeast_amount, salt_quantity, sugar_content, resting_time):
    hydration = total_hydration(name, bread_type, flour_weight, water_volume, yeast_amount, salt_quantity, sugar_content, resting_time)
    balance = flavor_balance(name, bread_type, flour_weight, water_volume, yeast_amount, salt_quantity, sugar_content, resting_time)
    return "{0} is a {1} loaf with hydration {2} and flavor balance {3}.".format(name, bread_type, hydration, balance)


def batch(recipes):
    results = []
    for name, bread_type, flour, water, yeast, salt, sugar, rest in recipes:
        recipe = BreadRecipe(name, bread_type, flour, water, yeast, salt, sugar, rest)
        hydration = total_hydration(recipe.name, recipe.bread_type, recipe.flour_weight, recipe.water_volume, recipe.yeast_amount, recipe.salt_quantity, recipe.sugar_content, recipe.resting_time)
        balance = flavor_balance(recipe.name, recipe.bread_type, recipe.flour_weight, recipe.water_volume, recipe.yeast_amount, recipe.salt_quantity, recipe.sugar_content, recipe.resting_time)
        schedule = baking_schedule(recipe.name, recipe.bread_type, recipe.flour_weight, recipe.water_volume, recipe.yeast_amount, recipe.salt_quantity, recipe.sugar_content, recipe.resting_time)
        results.append((hydration, balance, schedule))
    return results


