class Market:
    def __init__(self, name, region, gold, silver, weapons, armor, potions, food):
        self.name, self.region = name, region
        self.gold, self.silver = gold, silver
        self.weapons, self.armor = weapons, armor
        self.potions, self.food = potions, food


def assess_inflation_pressure(name, region, gold, silver, weapons, armor, potions, food):
    return round((silver + weapons * 1.5) / (gold + 1.0), 2)


def compute_trade_profitability(name, region, gold, silver, weapons, armor, potions, food):
    return round(armor * 2.0 + potions * 1.25 + food * 3.0, 2)


def generate_forecast(name, region, gold, silver, weapons, armor, potions, food):
    template = "The market of {} in {} has an inflation pressure of {} and a trade profitability of {}."
    return template.format(name, region, assess_inflation_pressure(name, region, gold, silver, weapons, armor, potions, food), compute_trade_profitability(name, region, gold, silver, weapons, armor, potions, food))


def trade(markets):
    report = []
    for entry in markets:
        market = Market(*entry)
        inflation = assess_inflation_pressure(market.name, market.region, market.gold, market.silver, market.weapons, market.armor, market.potions, market.food)
        profitability = compute_trade_profitability(market.name, market.region, market.gold, market.silver, market.weapons, market.armor, market.potions, market.food)
        forecast = generate_forecast(market.name, market.region, market.gold, market.silver, market.weapons, market.armor, market.potions, market.food)
        report.append((inflation, profitability, forecast))
    return report

from dataclasses import astuple, dataclass


@dataclass
class Route:
    name: str
    region: str
    crew: int
    guides: float
    oxygen: float
    rations: float
    tents: float
    weather: float


def summit_probability(name, region, crew, guides, oxygen, rations, tents, weather):
    return round(min((guides * 4 + oxygen * 6) / max(crew, 1), 100.0), 2)


def supply_exhaustion(name, region, crew, guides, oxygen, rations, tents, weather):
    return round(max(rations - (weather * 3 - tents * 2), 0.0), 2)


def expedition_briefing(name, region, crew, guides, oxygen, rations, tents, weather):
    chance = summit_probability(name, region, crew, guides, oxygen, rations, tents, weather)
    days = supply_exhaustion(name, region, crew, guides, oxygen, rations, tents, weather)
    return f"{name} in the {region} has a summit chance of {chance} and supplies for {days} days."


def climb(routes):
    results = []
    for entry in routes:
        fields = astuple(Route(*entry))
        chance = summit_probability(*fields)
        days = supply_exhaustion(*fields)
        briefing = expedition_briefing(*fields)
        results.append((chance, days, briefing))
    return results

class Stand:
    def __init__(self, name, species, average_age, planting_density, soil_moisture, annual_rainfall, elevation_gradient, disease_prevalence):
        self.name = name
        self.species = species
        self.average_age = average_age
        self.planting_density = planting_density
        self.soil_moisture = soil_moisture
        self.annual_rainfall = annual_rainfall
        self.elevation_gradient = elevation_gradient
        self.disease_prevalence = disease_prevalence


def assess_timber_volume(name, species, average_age, planting_density, soil_moisture, annual_rainfall, elevation_gradient, disease_prevalence):
    volume = average_age * planting_density * (0.5 + soil_moisture / 100.0) / 100.0
    return round(volume, 2)


def compute_ecological_impact(name, species, average_age, planting_density, soil_moisture, annual_rainfall, elevation_gradient, disease_prevalence):
    impact = annual_rainfall / 100.0 + elevation_gradient * 1.5 + disease_prevalence * 2.0
    return round(impact, 2)


def generate_logging_permit(name, species, average_age, planting_density, soil_moisture, annual_rainfall, elevation_gradient, disease_prevalence):
    volume = assess_timber_volume(name, species, average_age, planting_density, soil_moisture, annual_rainfall, elevation_gradient, disease_prevalence)
    impact = compute_ecological_impact(name, species, average_age, planting_density, soil_moisture, annual_rainfall, elevation_gradient, disease_prevalence)
    return "Permit for {}: {} may be logged for an estimated {} m3/ha at an ecological impact score of {}.".format(name, species, volume, impact)


def harvest(stands):
    results = []
    for entry in stands:
        stand = Stand(entry[0], entry[1], entry[2], entry[3], entry[4], entry[5], entry[6], entry[7])
        volume = assess_timber_volume(stand.name, stand.species, stand.average_age, stand.planting_density, stand.soil_moisture, stand.annual_rainfall, stand.elevation_gradient, stand.disease_prevalence)
        impact = compute_ecological_impact(stand.name, stand.species, stand.average_age, stand.planting_density, stand.soil_moisture, stand.annual_rainfall, stand.elevation_gradient, stand.disease_prevalence)
        permit = generate_logging_permit(stand.name, stand.species, stand.average_age, stand.planting_density, stand.soil_moisture, stand.annual_rainfall, stand.elevation_gradient, stand.disease_prevalence)
        results.append((volume, impact, permit))
    return results


