from collections import namedtuple

Microgrid = namedtuple("Microgrid", "grid_name county_name solar_generation wind_generation battery_charge residential_demand industrial_demand frequency_variance")

def assess_power_surplus(grid_name, county_name, solar_generation, wind_generation, battery_charge, residential_demand, industrial_demand, frequency_variance):
    return round(solar_generation + wind_generation + battery_charge, 2)

def compute_blackout_risk(grid_name, county_name, solar_generation, wind_generation, battery_charge, residential_demand, industrial_demand, frequency_variance):
    return round(residential_demand + industrial_demand + frequency_variance, 2)

def generate_switching_directive(grid_name, county_name, solar_generation, wind_generation, battery_charge, residential_demand, industrial_demand, frequency_variance):
    surplus = round(solar_generation + wind_generation + battery_charge, 2)
    risk = round(residential_demand + industrial_demand + frequency_variance, 2)
    return f"Microgrid {grid_name} in {county_name} reports a power surplus of {surplus} MW against a blackout risk of {risk}."

def island(grids):
    report = []
    for entry in grids:
        grid = Microgrid(*entry)
        surplus = assess_power_surplus(grid.grid_name, grid.county_name, grid.solar_generation, grid.wind_generation, grid.battery_charge, grid.residential_demand, grid.industrial_demand, grid.frequency_variance)
        risk = compute_blackout_risk(grid.grid_name, grid.county_name, grid.solar_generation, grid.wind_generation, grid.battery_charge, grid.residential_demand, grid.industrial_demand, grid.frequency_variance)
        directive = generate_switching_directive(grid.grid_name, grid.county_name, grid.solar_generation, grid.wind_generation, grid.battery_charge, grid.residential_demand, grid.industrial_demand, grid.frequency_variance)
        report.append((surplus, risk, directive))
    return report

from collections import namedtuple

OSCILLATOR_WAVEFORMS = ("sine", "triangle", "sawtooth", "square", "noise")
FILTER_TYPES = ("lowpass", "highpass", "bandpass", "notch")
PatchConfig = namedtuple("PatchConfig", "waveform coarse_hz detune filter_type cutoff_hz resonance attack_s release_s")

def make_patch(waveform, coarse_hz, detune, filter_type, cutoff_hz, resonance, attack_s, release_s):
    if waveform not in OSCILLATOR_WAVEFORMS:
        raise ValueError("unknown waveform: %s" % waveform)
    if filter_type not in FILTER_TYPES:
        raise ValueError("unknown filter type: %s" % filter_type)
    if coarse_hz <= 0.0 or cutoff_hz <= 0.0:
        raise ValueError("coarse tuning and cutoff must be positive")
    return PatchConfig(waveform, float(coarse_hz), float(detune), filter_type, float(cutoff_hz), float(resonance), float(attack_s), float(release_s))

PATCHES = dict(deep_bass=make_patch("sine", 55.0, -0.03, "lowpass", 180.0, 0.35, 0.005, 0.42), string_pad=make_patch("sawtooth", 220.0, 0.12, "lowpass", 1400.0, 0.22, 0.85, 2.6), brass_lead=make_patch("square", 330.0, 0.04, "bandpass", 2200.0, 0.55, 0.06, 0.35), crystal_bell=make_patch("triangle", 880.0, 0.008, "highpass", 3600.0, 0.18, 0.001, 1.9), snare_drum=make_patch("noise", 190.0, 0.5, "bandpass", 2800.0, 0.7, 0.001, 0.18), kick_drum=make_patch("sine", 48.0, -0.25, "lowpass", 120.0, 0.12, 0.002, 0.28), wind_noise=make_patch("noise", 400.0, 0.9, "notch", 900.0, 0.06, 1.4, 3.2), laser_zap=make_patch("sawtooth", 1200.0, -0.6, "highpass", 4500.0, 0.88, 0.001, 0.09))

def patch(presets):
    if isinstance(presets, str):
        return patch([presets])[0]
    built = []
    for name in presets:
        key = "_".join(name.lower().split())
        if key not in PATCHES:
            raise KeyError("no such preset: %s" % name)
        built.append(PATCHES[key])
    return built

def format_row(name, config):
    return "{:<13}{:>9}{:>9.2f}{:>8.3f}{:>11}{:>9.1f}{:>7.2f}{:>8.3f}{:>7.2f}".format(name, config.waveform, config.coarse_hz, config.detune, config.filter_type, config.cutoff_hz, config.resonance, config.attack_s, config.release_s)

def main():
    for name, config in zip(PATCHES, patch(PATCHES)):
        print(format_row(name, config))
    print("string pad ->", patch("string pad"))

if __name__ == "__main__":
    main()

