FIELD_NAMES = ("flour hydration ratio", "whole wheat proportion", "ambient temperature", "feed frequency", "aeration volume", "lactic acid concentration", "yeast colony density")


def validate_culture(
    culture,
    index,
):
    if len(culture) != len(FIELD_NAMES):
        raise ValueError(
            "culture {} must have {} values, got {}".format(
                index,
                len(FIELD_NAMES),
                len(culture),
            )
        )
    for name, value in zip(FIELD_NAMES, culture):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(
                "culture {}: {} must be numeric, got {!r}".format(
                    index,
                    name,
                    value,
                )
            )
    if culture[3] == 0:
        raise ValueError("culture {}: feed frequency must be non-zero".format(index))


def is_viable(
    ambient_temperature,
    feed_frequency,
    lactic_acid_concentration,
):
    return ambient_temperature + feed_frequency > lactic_acid_concentration


def growth_multiplier(
    flour_hydration_ratio,
    whole_wheat_proportion,
    ambient_temperature,
    feed_frequency,
    aeration_volume,
    yeast_colony_density,
):
    mass = flour_hydration_ratio + whole_wheat_proportion + aeration_volume + yeast_colony_density
    return mass * ambient_temperature / feed_frequency


def forecast(cultures):
    multipliers = []
    for index, culture in enumerate(cultures):
        validate_culture(
            culture,
            index,
        )
        hydration, whole_wheat, temperature, feeds, aeration, lactic_acid, colony = culture
        if is_viable(
            temperature,
            feeds,
            lactic_acid,
        ):
            multipliers.append(
                growth_multiplier(
                    hydration,
                    whole_wheat,
                    temperature,
                    feeds,
                    aeration,
                    colony,
                )
            )
        else:
            multipliers.append(0)
    return multipliers


def format_row(
    index,
    temperature,
    feeds,
    lactic_acid,
    multiplier,
):
    verdict = "viable" if multiplier else "dormant"
    return "#{:<3}{:>8.1f}{:>8.1f}{:>8.1f}{:>12.2f}  {}".format(
        index,
        temperature,
        feeds,
        lactic_acid,
        multiplier,
        verdict,
    )


def build_report(
    cultures,
    multipliers,
):
    lines = ["idx     temp   feeds  lactic   multiplier  status"]
    for index, (culture, multiplier) in enumerate(zip(cultures, multipliers)):
        lines.append(
            format_row(
                index,
                culture[2],
                culture[3],
                culture[5],
                multiplier,
            )
        )
    return "\n".join(lines)


def main():
    cultures = [(70, 30, 25, 2, 40, 10, 100), (55, 20, 4, 1, 30, 90, 60), (80, 15, 30, 3, 25, 12, 120)]
    multipliers = forecast(cultures)
    print(
        build_report(
            cultures,
            multipliers,
        )
    )
    print("total potential: {:.2f}".format(sum(multipliers)))


if __name__ == "__main__":
    main()

