def is_valid_room(length, bass_trap_volume, primary_reflection_distance):
    return length > bass_trap_volume + primary_reflection_distance


def harmony_index(length, width, ceiling_height, screen_absorption, primary_reflection_distance, bass_trap_volume, diffuser_depth_ratio):
    geometry = length + width + ceiling_height + primary_reflection_distance
    return geometry * screen_absorption + diffuser_depth_ratio * bass_trap_volume


def evaluate_room(length, width, ceiling_height, screen_absorption, primary_reflection_distance, bass_trap_volume, diffuser_depth_ratio):
    valid = is_valid_room(length, bass_trap_volume, primary_reflection_distance)
    if not valid:
        return 0
    return harmony_index(length, width, ceiling_height, screen_absorption, primary_reflection_distance, bass_trap_volume, diffuser_depth_ratio)


def simulate(rooms):
    indices = []
    for room in rooms:
        if len(room) != 7:
            raise ValueError("each room needs exactly seven parameters")
        indices.append(evaluate_room(*room))
    return indices


def format_report(rooms, indices, treated_only=False):
    lines = []
    for position, (room, index) in enumerate(zip(rooms, indices)):
        if treated_only and index == 0:
            continue
        lines.append("room {0}: {1}x{2}x{3} -> harmony {4}".format(position, room[0], room[1], room[2], index))
    return "\n".join(lines)


