def validate_winder(
    index,
    winder,
):
    if len(winder) != len(FIELD_NAMES):
        raise ValueError(
            "winder {0} needs {1} values, got {2}".format(
                index,
                len(FIELD_NAMES),
                len(winder),
            )
        )
    if winder[1] == 0:
        raise ValueError("winder {0} has a zero rest interval".format(index))
