def is_safe(
    rotations,
    rest,
    torque,
):
    return rotations / rest < torque


def preservation_score(
    ratio,
    torque,
    angle,
    shielding,
    resonance,
    rest,
):
    return (ratio + angle + shielding + resonance) * torque - rest


def calibrate(winders):
    scores = []
    for index, winder in enumerate(winders):
        rotations, rest, ratio, torque, angle, shielding, resonance = validate_winder(
            index,
            winder,
        )
        if is_safe(
            rotations,
            rest,
            torque,
        ):
            scores.append(
                preservation_score(
                    ratio,
                    torque,
                    angle,
                    shielding,
                    resonance,
                    rest,
                )
            )
        else:
            scores.append(0)
    return scores


