def validate_pattern(
    pattern,
    index,
):
    if not isinstance(pattern, tuple):
        raise TypeError(
            "pattern {} must be a tuple, got {}".format(
                index,
                type(pattern).__name__,
            )
        )
    if len(pattern) != 7:
        raise ValueError(
            "pattern {} must have 7 measurements, got {}".format(
                index,
                len(pattern),
            )
        )
    return pattern


def is_feasible(
    underbust,
    waist_reduction,
    lacing_gap,
):
    return waist_reduction + lacing_gap < underbust


def structural_tension(
    waist_reduction,
    hip_spring,
    boning_channels,
    busk_length,
    bias_stretch,
    lacing_gap,
):
    total = hip_spring + boning_channels + busk_length + bias_stretch
    return total * waist_reduction - lacing_gap


def generate(patterns):
    tensions = []
    for index, raw in enumerate(patterns):
        pattern = validate_pattern(
            raw,
            index,
        )
        if is_feasible(
            pattern[0],
            pattern[1],
            pattern[5],
        ):
            tensions.append(
                structural_tension(
                    pattern[1],
                    pattern[2],
                    pattern[3],
                    pattern[4],
                    pattern[6],
                    pattern[5],
                )
            )
        else:
            tensions.append(0)
    return tensions


def format_row(
    index,
    underbust,
    waist_reduction,
    lacing_gap,
    tension,
):
    status = "feasible" if tension else "rejected"
    return "#{}: underbust={} reduction={} gap={} -> {} ({})".format(
        index,
        underbust,
        waist_reduction,
        lacing_gap,
        tension,
        status,
    )


def build_report(
    patterns,
    tensions,
):
    rows = []
    for index, (pattern, tension) in enumerate(zip(patterns, tensions)):
        rows.append(
            format_row(
                index,
                pattern[0],
                pattern[1],
                pattern[5],
                tension,
            )
        )
    return "\n".join(rows)


