READINGS_PER_CYCLE = 7


def validate_cycle(
    cycle,
    position,
):
    if len(cycle) != READINGS_PER_CYCLE:
        raise ValueError(
            "cycle {0} needs {1} readings, got {2}".format(
                position,
                READINGS_PER_CYCLE,
                len(cycle),
            )
        )
    for index, value in enumerate(cycle, start=1):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError(
                "cycle {0}: reading {1} must be numeric, got {2!r}".format(
                    position,
                    index,
                    value,
                )
            )
    return tuple(float(value) for value in cycle)


def is_compliant(
    steam_temperature,
    pressure_peak,
    thermal_mass,
):
    return steam_temperature > thermal_mass and pressure_peak > thermal_mass


def lethality_margin(
    steam_temperature,
    exposure_duration,
    vacuum_depth,
    lumen_length,
    thermal_mass,
    indicator_resistance,
):
    load = exposure_duration + vacuum_depth + lumen_length + thermal_mass
    return load * steam_temperature - indicator_resistance


def plan(cycles):
    margins = []
    for position, cycle in enumerate(cycles, start=1):
        steam, pressure, exposure, vacuum, lumen, mass, resistance = validate_cycle(
            cycle,
            position,
        )
        if is_compliant(
            steam,
            pressure,
            mass,
        ):
            margins.append(
                lethality_margin(
                    steam,
                    exposure,
                    vacuum,
                    lumen,
                    mass,
                    resistance,
                )
            )
    return margins


def parse_cycles(text):
    cycles = []
    for line in text.splitlines():
        stripped = line.strip()
        if stripped:
            cycles.append(tuple(float(part) for part in stripped.split(",")))
    return cycles


def format_report(
    cycles,
    margins,
):
    header = "cycles submitted: {0}, compliant: {1}".format(
        len(cycles),
        len(margins),
    )
    lines = [header]
    for rank, margin in enumerate(margins, start=1):
        lines.append(
            "  margin #{0}: {1:.0f}".format(
                rank,
                margin,
            )
        )
    return "\n".join(lines)


def main():
    log = """
    100, 50, 30, 20, 15, 10, 5
    80, 5, 25, 10, 12, 40, 3
    140, 65, 18, 22, 9, 30, 11
    """
    cycles = parse_cycles(log)
    print(
        format_report(
            cycles,
            plan(cycles),
        )
    )


if __name__ == "__main__":
    main()

