def validate_batch(
    batch,
    position,
):
    if len(batch) != len(FIELD_NAMES):
        raise ValueError(
            "batch {} must carry {} readings, got {}".format(
                position,
                len(FIELD_NAMES),
                len(batch),
            )
        )
    for name, value in zip(FIELD_NAMES, batch):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("batch {}: {} must be numeric".format(position, name))
    return dict(zip(FIELD_NAMES, batch))


def is_premium(
    boiling_duration,
    light_transmittance,
    harvest_phase,
):
    return boiling_duration > harvest_phase and light_transmittance > 50


def complexity_score(
    sap_sugar_content,
    caramelization_temperature,
    mineral_ash_residue,
    viscosity_index,
    boiling_duration,
    light_transmittance,
):
    blend = sap_sugar_content + caramelization_temperature + mineral_ash_residue + viscosity_index
    return blend * boiling_duration + light_transmittance


def grade(batches):
    scores = []
    for position, batch in enumerate(batches):
        reading = validate_batch(
            batch,
            position,
        )
        premium = is_premium(
            reading["boiling_duration"],
            reading["light_transmittance"],
            reading["harvest_phase"],
        )
        if premium:
