import sys
from collections import namedtuple

Summary = namedtuple("Summary", ["path", "lines", "words", "characters", "blank_lines"])


def count_lines_in_file(filepath):
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        return sum(1 for _ in handle)


def format_summary_row(path, lines, words, characters, blank_lines, path_width):
    return "{:<{}}  {:>7}  {:>7}  {:>9}  {:>7}".format(path, path_width, lines, words, characters, blank_lines)


def summarize_file(filepath):
    lines = 0
    words = 0
    characters = 0
    blank_lines = 0
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            lines += 1
            words += len(line.split())
            characters += len(line)
            if not line.strip():
                blank_lines += 1
    return Summary(path=filepath, lines=lines, words=words, characters=characters, blank_lines=blank_lines)


def write_report(summaries, stream):
    path_width = max(len("TOTAL"), *(len(s.path) for s in summaries))
    rows = []
    header = format_summary_row(path="FILE", lines="lines", words="words", characters="chars", blank_lines="blank", path_width=path_width)
    rows.append(header)
    for summary in summaries:
        rows.append(format_summary_row(path=summary.path, lines=summary.lines, words=summary.words, characters=summary.characters, blank_lines=summary.blank_lines, path_width=path_width))
    total = format_summary_row(path="TOTAL", lines=sum(s.lines for s in summaries), words=sum(s.words for s in summaries), characters=sum(s.characters for s in summaries), blank_lines=sum(s.blank_lines for s in summaries), path_width=path_width)
    rows.append(total)
    stream.write("\n".join(rows) + "\n")


def main(argv):
    paths = argv[1:]
    if not paths:
        sys.stderr.write("usage: {} FILE [FILE ...]\n".format(argv[0]))
        return 1
    write_report(summaries=[summarize_file(path) for path in paths], stream=sys.stdout)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

