def caesar_cipher_encrypt(
    text,
    shift,
):
    encrypted_text_chars = []
    for char_val in text:
        if 'a' <= char_val <= 'z':
            start_val = ord('a')
            shifted_val = (
                ord(char_val)
                - start_val
                + shift
            ) % 26
            encrypted_text_chars.append(
                chr(
                    start_val
                    + shifted_val
                )
            )
        elif 'A' <= char_val <= 'Z':
            start_val = ord('A')
            shifted_val = (
                ord(char_val)
                - start_val
                + shift
            ) % 26
            encrypted_text_chars.append(
                chr(
                    start_val
                    + shifted_val
                )
            )
        else:
            encrypted_text_chars.append(char_val)
    return "".join(
        encrypted_text_chars
    )

