def validate_email(email):
    at_index = email.find(
        "@",
    )
    dot_index = email.find(
        ".",
        at_index,
    )

    if (
        at_index == -1
        or dot_index == -1
        or at_index > dot_index
    ):
        return False

    if (
        at_index == 0
        or dot_index == len(email) - 1
    ):
        return False

    if (
        email[at_index - 1] == "."
        or email[at_index + 1] == "."
    ):
        return False

    if (
        email.count("@") > 1
        or email.count("..") > 0
    ):
        return False

    return True

