import re

def extract_hashtags(
    text,
):
    """
    Finds all hashtags (words starting with '#') in a given string
    and returns them in a list, without the '#' symbol.
    """
    hashtag_pattern = re.compile(
        r"#(\w+)",
        re.UNICODE,
        re.IGNORECASE,
    )

    found_hashtags = hashtag_pattern.findall(
        text,
    )

    return list(
        found_hashtags,
    )

