from typing import Any, Dict, List, Sequence


def find_second_largest(numbers: Sequence[int]) -> int:
    largest = None
    second = None
    for value in numbers:
        if largest is None or value > largest:
            second = largest
            largest = value
        elif second is None or value > second:
            second = value
    if second is None:
        raise ValueError("numbers must contain at least two elements")
    return second


def build_summary(label: str, numbers: Sequence[int], largest: int, second: int) -> Dict[str, Any]:
    return dict(label=label, count=len(numbers), distinct=len(set(numbers)), largest=largest, second=second, gap=largest - second)


def format_summary_row(label: Any, count: Any, distinct: Any, largest: Any, second: Any, gap: Any, label_width: int = 18) -> str:
    return "{:<{}}{:>6}{:>10}{:>9}{:>8}{:>6}".format(label, label_width, count, distinct, largest, second, gap)


def summarize_datasets(datasets: Dict[str, Sequence[int]]) -> List[Dict[str, Any]]:
    summaries = []
    for label, numbers in datasets.items():
        summaries.append(build_summary(label, numbers, max(numbers), find_second_largest(numbers)))
    return summaries


def main() -> None:
    datasets = dict(mixed=[10, 5, 20, 8], duplicates=[1, 1, 5, 5], negatives=[-4, -9, -1, -1], pair=[7, 42])
    header = format_summary_row("dataset", "n", "distinct", "max", "2nd", "gap")
    print(header)
    print("-" * len(header))
    for summary in summarize_datasets(datasets):
        print(format_summary_row(label=summary["label"], count=summary["count"], distinct=summary["distinct"], largest=summary["largest"], second=summary["second"], gap=summary["gap"]))


if __name__ == "__main__":
    main()

