def run_length_encode(
    input_string,
):
    if not input_string:
        return ""

    encoded_parts = []
    current_char = input_string[0]
    current_count = 0

    for char in (
        input_string
    ):
        if char == current_char:
            current_count += 1
        else:
            encoded_parts.append(
                f"{current_char}{current_count}",
            )
            current_char = char
            current_count = 1

    encoded_parts.append(
        f"{current_char}{current_count}",
    )

    final_result = "".join(
        encoded_parts,
    )

    return final_result

