def char_frequency(text):
    if not isinstance(text, str):
        raise TypeError(
            "char_frequency() expects a string, got " + type(text).__name__
        )
    frequency_map = {}
    for character in text.lower():
        frequency_map[character] = frequency_map.get(character, 0) + 1
    return frequency_map


def sorted_frequency_entries(
    frequency_map,
    order_by_count=True,
    descending=True,
    skip_whitespace=False
):
    entries = list(frequency_map.items())
    if skip_whitespace:
        entries = [item for item in entries if not item[0].isspace()]
    entries.sort(key=lambda item: item[0])
    if order_by_count:
        entries.sort(key=lambda item: item[1], reverse=descending)
    elif descending:
        entries.reverse()
    return entries


def top_characters(frequency_map, limit=3):
    return sorted_frequency_entries(
        frequency_map,
        order_by_count=True,
        descending=True,
        skip_whitespace=True
    )[:limit]


def format_frequency_row(
    character,
    count,
    total_characters,
    bar_width=20,
    bar_character="#"
):
    share = count / total_characters if total_characters else 0.0
    label = repr(character) if character.isspace() else character
    return "{label:>4}  {count:>4}  {share:>7.1%}  {bar}".format(
        label=label,
        count=count,
        share=share,
        bar=bar_character * max(1, round(share * bar_width))
    )


def format_frequency_report(
    report_title,
    frequency_map,
    entry_limit=3,
    bar_width=20,
    underline_character="="
):
    total_characters = sum(frequency_map.values())
    lines = [report_title]
    lines.append(underline_character * len(report_title))
    for character, count in top_characters(frequency_map, limit=entry_limit):
        lines.append(
            format_frequency_row(
                character,
                count,
                total_characters,
                bar_width=bar_width,
                bar_character="*"
            )
        )
    alphabetical = sorted_frequency_entries(
        frequency_map,
        order_by_count=False,
        descending=False,
        skip_whitespace=True
    )
    lines.append("order: " + " ".join(item[0] for item in alphabetical))
    lines.append(
        "distinct={0} total={1}".format(len(frequency_map), total_characters)
    )
    return "\n".join(lines)


def main():
    for sample in ("hello", "Python", "Mississippi River"):
        print(
            format_frequency_report(
                "Frequencies for {0!r}".format(sample),
                char_frequency(sample),
                entry_limit=4,
                bar_width=24,
                underline_character="-"
            )
        )
        print()


if __name__ == "__main__":
    main()

