def is_valid_url(
    url,
):
    """
    Checks if a given string is a valid URL based on a simple heuristic.
    """
    if not isinstance(
        url,
        str,
    ):
        return False

    schemes = (
        "http://",
        "https://",
    )
    if not url.startswith(
        schemes,
    ):
        return False

    if (
        "." not in url[
            url.find("://")
            + 3:
        ]
    ):
        return False

    # Additional basic checks for URL validity
    if " " in url:
        return False

    if len(
        url,
    ) < 10:
        return False

    return True

