class StackOperationError(ValueError):
    """Raised when a stack request cannot be interpreted."""


def validate_request(
    stack,
    operation,
    item,
):
    if not isinstance(stack, list):
        raise StackOperationError("stack must be a list")
    if operation not in ("push", "pop"):
        raise StackOperationError("operation must be 'push' or 'pop'")
    if operation == "push" and item is None:
        raise StackOperationError("push requires an item")


def simulate_stack(stack, operation, item=None):
    validate_request(
        stack,
        operation,
        item,
    )
    if operation == "push":
        stack.append(item)
        return stack
    if not stack:
        return None
    return stack.pop()


def format_step(
    index,
    operation,
    item,
    result,
    stack,
):
    shown = "-" if item is None else repr(item)
    return "{:>3}  {:<5} {:<6} -> {:<12} {}".format(
        index,
        operation,
        shown,
        repr(result),
        stack,
    )


def coerce_item(text):
    try:
        return int(text)
    except ValueError:
        return text


def parse_requests(spec):
    requests = []
    for chunk in spec.split(";"):
        parts = chunk.split()
        item = coerce_item(parts[1]) if len(parts) > 1 else None
        requests.append((parts[0], item))
    return requests


def apply_operations(stack, requests):
    steps = []
    for index, (operation, item) in enumerate(requests, start=1):
        result = simulate_stack(stack, operation, item)
        steps.append(
            format_step(
                index,
                operation,
                item,
                result,
                list(stack),
            )
        )
    return steps


def render_report(
    title,
    steps,
    final_stack,
    width=60,
):
    lines = [title.center(width), "-" * width]
    lines.extend(steps)
    lines.append("-" * width)
    lines.append("final stack: {}".format(final_stack))
    return "\n".join(lines)


def main():
    stack = [1, 2]
    requests = parse_requests("push 3; pop; pop; push a; pop; pop; pop")
    steps = apply_operations(stack, requests)
    print(
        render_report(
            "STACK SIMULATION",
            steps,
            stack,
            width=58,
        )
    )
    try:
        simulate_stack(stack, "push")
    except StackOperationError as error:
        print("rejected: {}".format(error))


if __name__ == "__main__":
    main()

