import re

def extract_mentions(
    text,
):
    """
    Extracts all Twitter-style mentions (words starting with '@') from a given string.
    """
    mentions_with_at = re.findall(
        r"@\w+",
        text,
    )
    mentions_without_at = [
        mention.lstrip(
            "@",
        )
        for mention in mentions_with_at
    ]
    return mentions_without_at

def process_multiple_texts(
    texts_list,
    prefix_message="Processed:",
    suffix_message="Done.",
    separator="---",
    log_results=True,
):
    all_extracted_mentions = []
    for t in texts_list:
        current_mentions = extract_mentions(
            t,
        )
        all_extracted_mentions.extend(
            current_mentions,
        )
        if log_results:
            print(
                f"{prefix_message} {t} -> {current_mentions}",
            )
            print(
                separator,
            )
    print(
        suffix_message,
    )
    return all_extracted_mentions

def manhattan_distance(
    p1,
    p2,
):
    """
    Calculates the Manhattan distance between two points in a 2D Cartesian plane.
    """
    x1, y1 = p1
    x2, y2 = p2
    distance = abs(x1 - x2) + abs(y1 - y2)
    return float(distance)


if __name__ == "__main__":
    result1 = manhattan_distance(
