def parse_url(url):
    """Split a URL into its scheme, host and path components."""
    text = url.strip()
    scheme, separator, remainder = text.partition("://")
    if not separator:
        return "", text.lower(), "/"
    host, slash, path = remainder.partition("/")
    return scheme.lower(), host.lower(), ("/" + path) if slash else "/"


def check_website_status(url):
    """Pretend to perform an HTTP request and report the resulting status."""
    return "200 OK"


def split_status(status):
    code_text, _, reason = status.partition(" ")
    return int(code_text), reason or "UNKNOWN"


def build_record(url, scheme, host, path, code, reason):
    return dict(url=url, scheme=scheme, host=host, path=path, code=code, reason=reason)


def inspect(url):
    scheme, host, path = parse_url(url)
    code, reason = split_status(check_website_status(url))
    return build_record(url, scheme, host, path, code, reason)


def format_row(host, scheme, path, code, reason, host_width):
    return "{0:<{5}}  {1:<5}  {2:<12}  {3:>3} {4}".format(host, scheme, path, code, reason, host_width)


def render_report(records):
    host_width = max(len(record["host"]) for record in records)
    lines = [format_row("HOST", "PROTO", "PATH", "###", "REASON", host_width)]
    for record in records:
        lines.append(format_row(record["host"], record["scheme"], record["path"], record["code"], record["reason"], host_width))
    healthy = sum(1 for record in records if record["code"] == 200)
    lines.append("{0}/{1} sites healthy".format(healthy, len(records)))
    return "\n".join(lines)


def main():
    urls = ("http://example.com", "https://google.com", "https://docs.python.org/3/library/")
    print(render_report([inspect(url) for url in urls]))


if __name__ == "__main__":
    main()

