def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {
        ")": "(",
        "]": "[",
        "}": "{",
    }
    opening_brackets = {
        "(",
        "[",
        "{",
    }
    for char in s:
        if char in opening_brackets:
            stack.append(
                char,
            )
        elif char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
    return not stack

