from datetime import datetime

def days_between_dates(
    start_date_str: str,
    end_date_str: str,
) -> int:
    start_date = datetime.strptime(
        start_date_str,
        '%Y-%m-%d',
    )
    end_date = datetime.strptime(
        end_date_str,
        '%Y-%m-%d',
    )
    time_difference = (
        end_date
        - start_date
    )
    return time_difference.days

