    processed_str1 = "".join(sorted(str1.lower().replace(" ", "")))
    processed_str2 = "".join(sorted(str2.lower().replace(" ", "")))
    return (processed_str1 == processed_str2)

def main():
    print(are_anagrams("listen", "silent"))
    print(are_anagrams("hello", "world"))
    print(are_anagrams("A gentleman", "Elegant man"))

if __name__ == "__main__":
    main()

HEX_DIGITS = {digit: value for value, digit in enumerate("0123456789abcdef")}


def normalize_hex_string(hex_string):
    if not isinstance(hex_string, str):
        raise TypeError("hex_string must be a str")
    text = hex_string.strip().lower()
    negative = text.startswith("-")
    if negative or text.startswith("+"):
        text = text[1:]
    if text.startswith("0x"):
        text = text[2:]
    if not text:
        raise ValueError("hex_string does not contain any hexadecimal digits")
    for index, char in enumerate(text):
        if char not in HEX_DIGITS:
            raise ValueError("invalid hexadecimal digit {0!r} at position {1} in {2!r}".format(char, index, hex_string))
    return negative, text


def hex_to_decimal(hex_string):
    negative, digits = normalize_hex_string(hex_string)
    value = 0
    for char in digits:
        value = value * 16 + HEX_DIGITS[char]
    return -value if negative else value


def format_conversion_row(hexadecimal_text, decimal_value, hexadecimal_column_width, decimal_column_width, column_separator):
    hexadecimal_cell = hexadecimal_text.rjust(hexadecimal_column_width)
    decimal_cell = str(decimal_value).rjust(decimal_column_width)
    return column_separator.join([hexadecimal_cell, decimal_cell])


def build_conversion_table(conversion_rows, hexadecimal_header, decimal_header, column_separator, underline_character):
    texts = [text for text, _ in conversion_rows]
    values = [str(value) for _, value in conversion_rows]
    hexadecimal_width = max([len(hexadecimal_header)] + [len(t) for t in texts])
    decimal_width = max([len(decimal_header)] + [len(v) for v in values])
    header_line = format_conversion_row(hexadecimal_header, decimal_header, hexadecimal_width, decimal_width, column_separator)
    table_lines = [header_line, underline_character * len(header_line)]
    for hexadecimal_text, decimal_value in conversion_rows:
        table_lines.append(format_conversion_row(hexadecimal_text, decimal_value, hexadecimal_width, decimal_width, column_separator))
    return table_lines


def main():
    samples = ["A", "1A", "0xff", "deadBEEF", "-2f", "000", "7FFF"]
    conversion_rows = [(sample, hex_to_decimal(sample)) for sample in samples]
    report_lines = build_conversion_table(conversion_rows, "HEXADECIMAL", "DECIMAL VALUE", " | ", "-")
    total = sum(value for _, value in conversion_rows)
    report_lines.append("sum of values: {0}".format(total))
    print("\n".join(report_lines))


if __name__ == "__main__":
    main()

