def is_palindromic_number(
    number,
):
    if number < 0:
        return False

    original_number = number
    reversed_number = 0

    while number > 0:
        digit = (
            number
            % 10
        )
        reversed_number = (
            reversed_number
            * 10
            + digit
        )
        number //= 10

    return (
        original_number
        == reversed_number
    )

def main():
    print(
        is_palindromic_number(
            121,
        )
    )
    print(
        is_palindromic_number(
            123,
        )
    )
    print(
        is_palindromic_number(
            1001,
        )
    )
    print(
        is_palindromic_number(
            -121,
        )
    )

if __name__ == "__main__":
    main()

