def filter_dict_by_value(
    input_dict,
    threshold,
):
    filtered_data = dict()
    for (
        key,
        value,
    ) in input_dict.items():
        if value > threshold:
            filtered_data[key] = value
    return filtered_data


def test_filter_dict():
    result1 = filter_dict_by_value(
        input_dict={
            "a": 10,
            "b": 20,
            "c": 5,
        },
        threshold=15,
    )
    assert result1 == {"b": 20}

    result2 = filter_dict_by_value(
        input_dict={
            "x": 1,
            "y": 2,
        },
        threshold=5,
    )
    assert result2 == {}

    result3 = filter_dict_by_value(
        input_dict={
            "apple": 100,
            "banana": 50,
            "cherry": 200,
        },
        threshold=120,
    )
    assert result3 == {"cherry": 200}

    result4 = filter_dict_by_value(
        input_dict={
            "empty": 0,
        },
        threshold=-1,
    )
    assert result4 == {"empty": 0}


if __name__ == "__main__":
    test_filter_dict()

