import re

def extract_emails(
    text,
):
    email_pattern = re.compile(
        r"[a-zA-Z0-9._%+-]+@"
        r"[a-zA-Z0-9.-]+\."
        r"[a-zA-Z]{2,}",
    )
    return email_pattern.findall(
        text,
    )

if __name__ == '__main__':
    emails_found = extract_emails(
        "Contact us at info@example.com or support@test.org, also "
        "another.one@sub.domain.co.uk and an invalid.email@.com. "
        "No, this is invalid: user@localhost. "
        "But this is fine: valid-user@domain-name.net.",
    )
