def count_vowels(
    text,
):
    vowels = (
        "a",
        "e",
        "i",
        "o",
        "u",
    )
    count = 0
    for char in text:
        if char.lower() in vowels:
            count += 1
    return count


def example_usage():
    result1 = count_vowels(
        "Hello World",
    )
    print(
        f"Result for 'Hello World': {result1}",
    )

