def encrypt_shift(
    text,
    shift,
):
    encrypted_text = ""
    for char in text:
        if 'a' <= char <= 'z':
            encrypted_text += chr(
                (
                    ord(char)
                    - ord('a')
                    + shift
                )
                % 26
                + ord('a')
            )
        elif 'A' <= char <= 'Z':
            encrypted_text += chr(
                (
                    ord(char)
                    - ord('A')
                    + shift
                )
                % 26
                + ord('A')
            )
        else:
            encrypted_text += char
    return encrypted_text

def test_encryption():
    assert encrypt_shift(
        'abc',
        1,
    ) == 'bcd'
    assert encrypt_shift(
        'XYZ',
        3,
    ) == 'ABC'
    assert encrypt_shift(
        'Hello, World!',
        5,
    ) == 'Mjqqt, Btwqi!'
    assert encrypt_shift(
        '123',
        10,
    ) == '123'
    assert encrypt_shift(
        '',
        7,
    ) == ''

if __name__ == '__main__':
    test_encryption()
    print(
        encrypt_shift(
            "Python Programming",
            3,
        )
    )
    print(
        encrypt_shift(
            "Cryptography is FUN!",
            13,
        )
    )

