def longest_common_prefix(
    strings,
):
    if not strings:
        return ""

    shortest_string = min(
        strings,
        key=len,
    )

    for i, char in enumerate(
        shortest_string,
    ):
        for other_string in strings:
            if other_string[i] != char:
                return shortest_string[:i]

    return shortest_string


