def roman_to_int(
    roman_numeral,
):

    roman_map = {
        "I": 1,
        "V": 5,
        "X": 10,
        "L": 50,
        "C": 100,
        "D": 500,
        "M": 1000,
    }

    integer_value = 0
    prev_value = 0

    for char in reversed(
        roman_numeral
    ):
        current_value = roman_map[
            char
        ]
        if current_value < prev_value:
            integer_value -= current_value
        else:
            integer_value += current_value
        prev_value = current_value
    return integer_value

def example_usage():

    result1 = roman_to_int(
        "III"
    )
    result2 = roman_to_int(
        "LVIII"
    )
    result3 = roman_to_int(
        "MCMXCIV"
    )

    print(
        f"III: {result1}"
    )
    print(
        f"LVIII: {result2}"
    )
    print(
        f"MCMXCIV: {result3}"
    )

if __name__ == "__main__":
    example_usage()

