def convert_length(
    value,
    from_unit,
    to_unit,
):
    M_TO_FT = 3.28084
    FT_TO_M = 1 / M_TO_FT

    if from_unit == 'm' and to_unit == 'ft':
        return (
            value
            * M_TO_FT
        )
    elif (
        from_unit == 'ft'
        and to_unit == 'm'
    ):
        return (
            value
            * FT_TO_M
        )
    elif (
        from_unit == to_unit
    ):
        return value
    else:
        raise ValueError(
            "Invalid units provided. Use 'm' or 'ft'.",
        )

