def calculate_power(
    base,
    exponent,
):
    """
    Calculates the result of a base number raised to an exponent.
    """
    if exponent == 0:
        return 1
    elif exponent > 0:
        result = 1
        for _ in range(
            exponent,
        ):
            result *= base
        return result
    else:
        positive_exponent_result = calculate_power(
            base,
            -exponent,
        )
        return 1 / positive_exponent_result

if __name__ == '__main__':
    power1 = calculate_power(
        2,
