import math

def mean_absolute_deviation(
    numbers,
):
    if not numbers:
        return 0.0

    mean_val = (
        sum(numbers)
        / len(numbers)
    )

    absolute_deviations = [
        abs(
            num - mean_val,
        )
        for num in numbers
    ]

    mad = (
        sum(absolute_deviations)
        / len(absolute_deviations)
    )

    return mad

if __name__ == "__main__":
    test_cases = [
        (
            [],
            0.0,
        ),
        (
            [1, 2, 3, 4],
            1.0,
        ),
        (
            [10, 20, 30],
            20/3,
        ),
        (
            [5.0, 10.0, 15.0, 20.0],
            5.0,
        ),
        (
            [
                -1,
                0,
                1,
            ],
            2/3,
        ),
    ]

    for numbers, expected in test_cases:
        result = mean_absolute_deviation(
            numbers,
        )
        assert abs(
            result - expected,
        ) < 1e-9, f"For {numbers}, expected {expected}, got {result}"
        print(
            f"Test passed for {numbers}. Result: {result}",
        )

