def convert_base(
    number,
    base,
):
    if not (2 <= base <= 16):
        raise ValueError(
            "Base must be between 2 and 16 inclusive."
        )

    digits = "0123456789ABCDEF"
    result = []

    if number == 0:
        return "0"

    current_number = number
    while current_number > 0:
        remainder = current_number % base
        result.append(
            digits[
                remainder
            ]
        )
        current_number //= base

    return "".join(
        reversed(
            result
        )
    )

