from collections import defaultdict

def word_frequency(
    words,
):
    """
    Calculates the frequency of each word in a list of strings, case-insensitively.
    """
    frequency_map = defaultdict(
        int,
    )
    for word in words:
        lowercase_word = word.lower()
        frequency_map[lowercase_word] += 1
    return dict(
        frequency_map,
    )

if __name__ == "__main__":
    result1 = word_frequency(
        [
            'Apple',
            'banana',
            'apple',
            'Orange',
        ],
    )
    print(
        result1,
    )

    result2 = word_frequency(
        [],
    )
    print(
        result2,
    )

    result3 = word_frequency(
        [
            'one',
            'Two',
            'one',
            'THREE',
            'two',
            'One',
        ],
    )
    print(
        result3,
    )

def xor_cipher(
    text,
    key_char,
):
    """
    Encrypts/decrypts text using a XOR cipher with a single character key.
    """
    result = []
    key_val = ord(key_char)
    for char_val in map(
        ord,
        text,
    ):
        result.append(
            chr(
                char_val
                ^ key_val,
            )
        )
    return "".join(
        result,
    )

def _test_xor_cipher():
    assert xor_cipher(
        "Hello",
        "A",
    ) == '\x09\x04\x0f\x0f\x0a'
    assert xor_cipher(
        xor_cipher(
            "Test",
            "B",
        ),
        "B",
    ) == "Test"
    assert xor_cipher(
        "Python",
        "K",
    ) == '\x15\x00\x1a\x11\x0e\x1b'
    assert xor_cipher(
        xor_cipher(
            "Another example string",
            "X",
        ),
        "X",
    ) == "Another example string"
    assert xor_cipher(
        "",
        "Z",
    ) == ""

if __name__ == '__main__':
    _test_xor_cipher()

