def check_password_strength(password):
    length_ok = len(password) >= 8
    has_upper = any(
        char.isupper()
        for char in password
    )
    has_lower = any(
        char.islower()
        for char in password
    )
    has_digit = any(
        char.isdigit()
        for char in password
    )

    if (
        length_ok
        and has_upper
        and has_lower
        and has_digit
    ):
        return 'Strong'

    conditions_met = sum(
        [
            has_upper,
            has_lower,
            has_digit,
        ]
    )

    if (
        len(password) >= 6
        and conditions_met >= 2
    ):
        return 'Medium'
    else:
        return 'Weak'

