from numbers import Number


def _validate_operand(values, name):
    if not isinstance(values, (list, tuple)):
        raise TypeError(
            "{name} must be a list or tuple, got {kind}".format(
                name=name,
                kind=type(values).__name__
            )
        )
    for index, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, Number):
            raise TypeError(
                "{name}[{index}] is not a number: {value!r}".format(
                    name=name,
                    index=index,
                    value=value
                )
            )
    for index in range(len(values) - 1):
        if values[index] > values[index + 1]:
            raise ValueError(
                "{name} is not sorted: {left} > {right} at index {index}".format(
                    name=name,
                    left=values[index],
                    right=values[index + 1],
                    index=index
                )
            )


def merge_sorted_lists(list1, list2):
    _validate_operand(list1, "list1")
    _validate_operand(list2, "list2")
    merged = []
    left = 0
    right = 0
    while left < len(list1) and right < len(list2):
        if list1[left] <= list2[right]:
            merged.append(list1[left])
            left += 1
        else:
            merged.append(list2[right])
            right += 1
    merged.extend(list1[left:])
    merged.extend(list2[right:])
    return merged


def summarize_merge(list1, list2, merged):
    return dict(
        left_count=len(list1),
        right_count=len(list2),
        total=len(merged),
        minimum=merged[0] if merged else None,
        maximum=merged[-1] if merged else None
    )


def format_merge_report(
    label,
    list1,
    list2,
    merged,
    stats
):
    header = "{0}: {1} + {2} -> {3}".format(label, list1, list2, merged)
    counts = "  counts: {left_count} + {right_count} = {total}".format(**stats)
    span = "  range: {minimum} .. {maximum}".format(**stats)
    return "\n".join([header, counts, span])


def report_case(label, list1, list2):
    merged = merge_sorted_lists(list1, list2)
    return format_merge_report(
        label=label,
        list1=list1,
        list2=list2,
        merged=merged,
        stats=summarize_merge(list1, list2, merged)
    )


def main():
    print(report_case("interleaved", [1, 3, 5], [2, 4, 6]))
    print(report_case("single value", [10], []))
    print(report_case("with duplicates", [1, 2, 2, 9], [2, 3]))
    print(report_case("floats and ints", [-1.5, 0, 7], [-2, 6.25]))


if __name__ == "__main__":
    main()

