PUNCTUATION = ".,!?;:'\"()[]-…"


def validate_sentence(sentence):
    if not isinstance(sentence, str):
        message = "sentence must be a str, got {!r}".format(type(sentence).__name__)
        raise TypeError(message)
    return sentence


def split_token(token, punctuation_chars):
    stripped = token.lstrip(punctuation_chars)
    lead = token[: len(token) - len(stripped)]
    core = stripped.rstrip(punctuation_chars)
    trail = stripped[len(core) :]
    return lead, core, trail


def tokenize(sentence, punctuation_chars):
    tokens = []
    for word in sentence.split():
        tokens.append(
            split_token(
                word,
                punctuation_chars,
            ),
        )
    return tokens


def recombine(lead, core, own_trail, slot_trail, is_last):
    if not is_last and slot_trail and slot_trail != own_trail:
        return lead + core + own_trail + slot_trail
    return lead + core + own_trail


def reverse_words_with_punctuation(sentence):
    validate_sentence(sentence)
    tokens = tokenize(
        sentence,
        PUNCTUATION,
    )
    slot_trails = [trail for _lead, _core, trail in tokens]
    moved = list(reversed(tokens))
    pieces = []
    for index, (lead, core, trail) in enumerate(moved):
        pieces.append(
            recombine(
                lead,
                core,
                trail,
                slot_trails[index],
                index == len(moved) - 1,
            ),
        )
    return " ".join(pieces)


def format_report(original, transformed, word_count, punctuation_count):
    return "\n".join(
        [
            "input        : {}".format(original),
            "reversed     : {}".format(transformed),
            "words        : {}".format(word_count),
            "punctuation  : {}".format(punctuation_count),
        ],
    )


def main(argv):
    sentences = argv[1:]
    if not sentences:
        sentences = ["Hello, world!", "One. Two. Three."]
    for sentence in sentences:
        tokens = tokenize(
            sentence,
            PUNCTUATION,
        )
        marks = sum(len(lead) + len(trail) for lead, _core, trail in tokens)
        report = format_report(
            sentence,
            reverse_words_with_punctuation(sentence),
            len(tokens),
            marks,
        )
        print(report)
        print()


if __name__ == "__main__":
    import sys

    main(sys.argv)

