):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(
            "{name} must be an int, got {kind}".format(
                name=parameter_name,
                kind=type(value).__name__
            )
        )
    if value < 0:
        raise ValueError(
            "{name} must be non-negative, got {value}".format(
                name=parameter_name,
                value=value
            )
        )
    if value > maximum:
        raise ValueError(
            "{name}={value} exceeds the supported maximum of {maximum}".format(
                name=parameter_name,
                value=value,
                maximum=maximum
            )
        )


def calculate_factorial(n):
    validate_non_negative_integer(
        value=n,
        parameter_name="n",
        maximum=MAX_SUPPORTED_INPUT
    )
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def format_table_row(
    index_cell,
    value_cell,
    digits_cell,
    index_width,
    value_width,
    digits_width,
    separator
):
    return separator.join(
        [
            index_cell.rjust(index_width),
            value_cell.rjust(value_width),
            digits_cell.rjust(digits_width)
        ]
    )


def build_factorial_table(
    start,
    stop,
    headers,
    separator
):
    for bound_name, bound in (("start", start), ("stop", stop)):
        validate_non_negative_integer(
            value=bound,
            parameter_name=bound_name,
            maximum=MAX_SUPPORTED_INPUT
        )
    if start > stop:
        raise ValueError("start must not be greater than stop")

    rows = [tuple(headers)]
    for index in range(start, stop + 1):
        value = str(calculate_factorial(index))
        rows.append((str(index), value, str(len(value))))

    widths = []
    for column in range(3):
        widths.append(max(len(row[column]) for row in rows))

    lines = []
    for index_cell, value_cell, digits_cell in rows:
        lines.append(
            format_table_row(
                index_cell=index_cell,
                value_cell=value_cell,
                digits_cell=digits_cell,
                index_width=widths[0],
                value_width=widths[1],
                digits_width=widths[2],
                separator=separator
            )
        )
    return "\n".join(lines)


