import math
from collections import namedtuple

SquareFacts = namedtuple(
    "SquareFacts",
    ["number", "is_square", "floor_root", "gap", "next_square"]
)


def _require_non_negative_int(
    value,
    argument_name,
    function_name
):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(
            "{}() expects an int for {!r}, got {}".format(
                function_name,
                argument_name,
                type(value).__name__
            )
        )
    if value < 0:
        raise ValueError(
            "{}() expects {!r} to be non-negative, got {}".format(
                function_name,
                argument_name,
                value
            )
        )
    return value


def is_perfect_square(n):
    _require_non_negative_int(
        n,
        "n",
        "is_perfect_square"
    )
    root = math.isqrt(n)
    return root * root == n


def describe(n):
    _require_non_negative_int(
        n,
        "n",
        "describe"
    )
    root = math.isqrt(n)
    return SquareFacts(
        n,
        root * root == n,
        root,
        n - root * root,
        (root + 1) * (root + 1)
    )


def format_report_line(
    number,
    is_square,
    floor_root,
    gap,
    next_square,
    number_width
):
    if is_square:
        detail = "= {}^2".format(floor_root)
    else:
        detail = "{}^2 + {}, next square is {}".format(
            floor_root,
            gap,
            next_square
        )
    return "{:>{width}}  {:<4} {}".format(
        number,
        "yes" if is_square else "no",
        detail,
        width=number_width
    )


def build_report(numbers, title, separator):
    width = max((len(str(n)) for n in numbers), default=1)
    lines = [title, separator * len(title)]
    for n in numbers:
        facts = describe(n)
        lines.append(
            format_report_line(
                facts.number,
                facts.is_square,
                facts.floor_root,
                facts.gap,
                facts.next_square,
                width
            )
        )
    squares = sum(1 for n in numbers if is_perfect_square(n))
    lines.append(
        "{} of {} values are perfect squares".format(
            squares,
            len(numbers)
        )
    )
    return "\n".join(lines)


def main():
    print(
        build_report(
            [0, 1, 9, 10, 144, 145, 1000000],
            "Perfect square report",
            "-"
        )
    )


if __name__ == "__main__":
    main()

